Consider a vector A[1…n] of ‘n’ numbers. We define an operation Si,j (1 ≤ i ≤ j ≤ n) on A as A[i] + A[i+1] – A[i+2] + A[i+3] – A[i+4] + …. A[j]. Given A, implement an algorithm to determine all pairs of i and j that results in the highest non-zero negative value of Si,j. The corresponding value of Si,j is also to be returned by the algorithm.

Function Prototype: vector<pair<int,int>> subarray(vector<int> A, int *value);

given Sample: 
Input: A = {-4, 6, -7, 2, 2}
Output: (1,2),(1,4), value = -1

GIVE CPP CODE

Here's a C++ implementation for the problem:

```cpp
#include <iostream>
#include <vector>
#include <utility>
#include <climits>
#include <algorithm>

using namespace std;

vector<pair<int,int>> subarray(vector<int> A, int *value) {
    int n = A.size();

    vector<int> B(n); // Transforming the array to further simplify the problem
    for (int i = 0; i < n; i++) {
        B[i] = (i % 2 ? 1 : -1) * A[i];
    }

    // Start of the Kadane's Algorithm Logic
    vector<int> dp(n);
    vector<int> start_indices(n);
    dp[0] = B[0];
    start_indices[0] = 1;
    int max_val = dp[0];
    int index = 0; 

    for (int i = 1; i < n; ++i) {
        if (dp[i - 1] >= 0) {
            dp[i] = dp[i - 1] + B[i];
            start_indices[i] = start_indices[i - 1];
        } else {
            dp[i] = B[i];
            start_indices[i] = i + 1;
        }

        if (dp[i] > max_val) {
            max_val = dp[i];
            index = i;
        }
    }
    // End of the Kadane's Algorithm Logic

    int end_index = index + 1;
    int start_index = start_indices[index];

    // Extracting pairs resulting in highest non-zero negative value
    vector<pair<int, int>> result;
    *value = max_val;
    for (int i = start_index; i <= end_index; ++i) {
        result.push_back(make_pair(start_index, i));
    }

    return result;
}

int main() {
    vector<int> A = {-4, 6, -7, 2, 2};
    int value;
    vector<pair<int,int>> result = subarray(A, &value);

    cout << "Output Pairs: ";
    for (auto p : result) {
        cout << "(" << p.first << "," << p.second << "),";
    }
    cout << " value = " << value << endl;

    return 0;
}
```

This solution uses the Kadane's Algorithm to find the contiguous subarray with the highest negative summation. The time complexity of this algorithm is `O(n)` where `n` is the size of the input array.

Given a vector A of ‘n’ numbers and a positive integer ‘k’, implement an algorithm to arrange numbers in the vector such that the last k0 numbers are sorted in non-decreasing order, the next last k1 numbers in non-increasing order, the preceding k2 numbers in non-decreasing order and continuing to sort the alternate ki last numbers in non-decreasing and non-increasing orders respectively.

Function Prototype: void sortRearrange(vector<int> &A, int k);

Sample: Input: A = {4, 1, 7, 3, 5, 6, 3, 1, 10, 2}, k = 2, Output: {7, 4, 1, 3, 3, 5, 6, 10, 1, 2}

Here's a C++ implementation of the algorithm to rearrange the vector according to the given conditions. In this algorithm, first, sort the given vector in non-decreasing order, then swap the elements in pairs, starting from the end, in every k elements alternately.

```cpp
#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

void sortRearrange(vector<int> &A, int k) {
    int n = A.size();
    sort(A.begin(), A.end()); // Sort the initial vector in a non-decreasing order

    for (int i = n - k; i >= 0; i -= 2 * k) {
        int j = i, count = 0;

        while (count < k && j < n - 1) {
            swap(A[j], A[j+1]); // Swap the elements in pairs
            j += 2;
            count++;
        }
    }
}

int main() {
    vector<int> A = {4, 1, 7, 3, 5, 6, 3, 1, 10, 2};
    int k = 2;

    sortRearrange(A, k);

    cout << "Output: ";
    for (int i : A) {
        cout << i << " ";
    }
    cout << endl;

    return 0;
}
```

The time complexity of this algorithm is `O(n log n)` due to the initial sorting operation, where `n` is the size of the input array.

