import android.app.AlarmManager
import android.app.PendingIntent
import android.content.Context
import android.content.Intent
import dagger.hilt.android.HiltAndroidApp

@HiltAndroidApp
class XegeraTrucking : Application() {
    private lateinit var alarmManager: AlarmManager

    override fun onCreate() {
        super.onCreate()
        alarmManager = getSystemService(Context.ALARM_SERVICE) as AlarmManager
        scheduleLocationUpdate(5 * 60 * 1000L) // 5 minutes in milliseconds
    }

    fun scheduleLocationUpdate(intervalMillis: Long) {
        val intent = Intent(this, LocationUpdateReceiver::class.java).apply {
            action = LocationUpdateReceiver.ACTION_UPDATE_LOCATION
        }

        val pendingIntent = PendingIntent.getBroadcast(this, 0, intent, PendingIntent.FLAG_UPDATE_CURRENT)

        alarmManager.setRepeating(
            AlarmManager.RTC_WAKEUP,
            System.currentTimeMillis() + intervalMillis,
            intervalMillis,
            pendingIntent
        )
    }
}
