Update the `LocationUpdateReceiver`:

```kotlin
import android.Manifest
import android.content.BroadcastReceiver
import android.content.Context
import android.content.Intent
import android.content.pm.PackageManager
import androidx.core.app.ActivityCompat
import com.google.android.gms.location.FusedLocationProviderClient
import com.google.android.gms.location.LocationServices
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.launch

class LocationUpdateReceiver : BroadcastReceiver() {
    companion object {
        const val ACTION_UPDATE_LOCATION = "com.yourpackage.location.ACTION_UPDATE_LOCATION"
    }

    private lateinit var fusedLocationClient: FusedLocationProviderClient

    override fun onReceive(context: Context, intent: Intent) {
        if (intent.action == ACTION_UPDATE_LOCATION) {
            fusedLocationClient = LocationServices.getFusedLocationProviderClient(context)
            updateLocation(context)
        }
    }

    // Update location using FusedLocationProviderClient
    private fun updateLocation(context: Context) {
        CoroutineScope(Dispatchers.IO).launch {
            if (ActivityCompat.checkSelfPermission(
                    context,
                    Manifest.permission.ACCESS_FINE_LOCATION
                ) == PackageManager.PERMISSION_GRANTED
                || ActivityCompat.checkSelfPermission(
                    context,
                    Manifest.permission.ACCESS_COARSE_LOCATION
                ) == PackageManager.PERMISSION_GRANTED
            ) {
                try {
                    val lastLocation = fusedLocationClient.lastLocation.await()

                    if (lastLocation != null) {
                        // Handle the location update here
                        // For example, you can update the location to your server or store it in your app
                        println("Location Updated - Latitude: ${lastLocation.latitude}, Longitude: ${lastLocation.longitude}")
                    } else {
                        println("Failed to get the location")
                    }
                } catch (exception: Exception) {
                    println("Error updating location: $exception")
                }
            } else {
                // The app does not have the required location permissions. Handle this case accordingly.
                println("No location permission granted")
            }
        }
    }
}
```

In this example, I used the `FusedLocationProviderClient` to get the last known location. Make sure to handle the case when the app does not have the required location permissions. You could request the necessary permissions in your MainActivity and inform users about its purpose.

