//| Custom indicator iteration function                              |
//+------------------------------------------------------------------+
int start()
  {
   int limit, counted_bars = IndicatorCounted();

   if (counted_bars < 0) return(-1);
   if (counted_bars > 0) limit = Bars - counted_bars;
   else limit = Bars - 1; 

   double MA_Values[3];
   double Difference;
   string objName;
   bool breakout = false;

   for (int i = limit; i >= 0; i--)
     {
      MA1_Buffer[i] = iLWMA(NULL,0,MA1_Period,0,i);
      MA2_Buffer[i] = iLWMA(NULL,0,MA2_Period,0,i);
      MA3_Buffer[i] = iLWMA(NULL,0,MA3_Period,0,i);

      MA_Values[0] = MA1_Buffer[i];
      MA_Values[1] = MA2_Buffer[i];
      MA_Values[2] = MA3_Buffer[i];

      ArraySort(MA_Values);

      Difference = MA_Values[2] - MA_Values[0];

      if ((Difference / Point) <= Max_MA_Range)
        {
         if (!ObjectFind("RangeBox_"+TimeToStr(iBarShift(NULL,0,Time[i],true))) != -1) 
          {
           ObjectCreate("RangeBox_"+TimeToStr(iBarShift(NULL,0,Time[i],true)), OBJ_RECTANGLE_LABEL, 0, Time[i], MA_Values[2], Time[i], MA_Values[0]);
           ObjectSet("RangeBox_"+TimeToStr(iBarShift(NULL,0,Time[i],true)), OBJPROP_BACK, true);
          }
        }

      objName = "BreakoutText";
      if (!breakout && i == limit)
        {
         for (int j = 2; j >= 0; j--)
           {
            if (Bid > MA_Values[j] + (Max_MA_Range * Point) || Bid < MA_Values[j] - (Max_MA_Range * Point))
              {
               if (!ObjectFind(objName) != -1) ObjectCreate(objName, OBJ_TEXT, 0, Time[i], Low[i] - 10 * Point);
               ObjectSetText(objName, "BREAKOUT", 10, "Arial", Yellow);
               ObjectSet(objName, OBJPROP_CORNER, 3);

               if (IsTradeAllowed())
                {
                 SendNotification("Breakout detected at Bid: " + DoubleToStr(Bid, Digits));
                }

               breakout = true;
               break;
              }
           }
        }
     }

   return(0);
  }
//+------------------------------------------------------------------+
