async function cachedGetUserProfile(userId: string): Promise<UserProfile> {
  if (!memo.has(userId)) {
    const userProfilePromise = getUserProfile(userId);
    memo.set(userId, userProfilePromise);
  }

  return await memo.get(userId);
}

