  "description": "Find out what Elon Musk said about a topic by right-clicking on a term.",
  "permissions": ["contextMenus", "activeTab"],
  "background": {
    "scripts": ["background.js"],
    "persistent": false
  },
  "icons": {
    "128": "icon128.png"
  }
}
```

3. Create a background script:

   a. Create a new JavaScript file in your extension's directory named `background.js`.
   b. Add the following code to the `background.js`:

```js
chrome.runtime.onInstalled.addListener(() => {
  chrome.contextMenus.create({
    id: "findMuskQuote",
    title: "Find Elon Musk Quote",
    contexts: ["selection"],
  });
});

chrome.contextMenus.onClicked.addListener((info, tab) => {
  if (info.menuItemId === "findMuskQuote" && info.selectionText) {
    const encodedQuery = encodeURIComponent(info.selectionText);
    getMuskQuote(encodedQuery).then((quote) => {
      chrome.tabs.sendMessage(tab.id, { action: "showQuote", quote: quote });
    });
  }
});

async function getMuskQuote(query) {
  try {
    const axios = require('axios');
    const response = await axios.get(
      `https://api.url/your-api/?search=${query}`
    );
    return response.data || "No quote found.";
  } catch (error) {
    return "Error fetching the quote.";
  }
}
