interface SideTypeProps {
  order: Order;
}

const SideType = ({order}: SideTypeProps) => {
  let label = '';
  let color = 'default';
  const icon = order?.side && 'sell' === order.side
    ? ArrowDownwardRoundedIcon
    : ArrowUpwardRoundedIcon;

  switch (order?.type) {
    case 'limit':
      label = 'L';
      color = 'success'
      break;
    case 'market':
      label = 'M';
      color = 'warning'
      break;
    case 'stop_market':
      label = 'F';
      color = 'primary'
      break;
  }

  return <>
    <Badge
      badgeContent={label}
      // @ts-ignore
      color={color}
    >
      <Icon component={icon} color="action" />
    </Badge>
  </>
}

