        setWaiting(false);
        if (!data) return;

        const newOrders: Array<TradeEntity> = [];

        data.orders.forEach(order => {
          const timestamp = Math.floor(order.msTimestamp) - timezoneOffset;

          newOrders.push({
            time: timestamp,
            position: order.side,
            value: parseFloat(order.price),
          });
        });

        setTrade(data);
        setOrders(newOrders);
