```c
#include "zc_io.h"
#include <sys/mman.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>

struct zc_file {
    // Insert the fields you need here.
    void *mapped;
    off_t offset;
    size_t total_size;
    int fd;
};

zc_file *zc_open(const char *path) {
    zc_file *file = malloc(sizeof(zc_file));
    if (!file) return NULL;

    file->fd = open(path, O_CREAT | O_RDWR);
    if (file->fd == -1) {
        free(file);
        return NULL;
    }

    struct stat st;
    fstat(file->fd, &st);
    file->total_size = st.st_size;

    file->mapped = mmap(NULL, file->total_size, PROT_READ | PROT_WRITE, MAP_SHARED, file->fd, 0);
    if (file->mapped == MAP_FAILED) {
        close(file->fd);
        free(file);
        return NULL;
    }
    file->offset = 0;

    return file;
}

int zc_close(zc_file *file) {
    if (!file) return -1;

    msync(file->mapped, file->total_size, MS_SYNC);
    munmap(file->mapped, file->total_size);
    close(file->fd);
    free(file);

    return 0;
}

const char *zc_read_start(zc_file *file, size_t *size) {
    if (!file || !size) return NULL;

    size_t remaining = file->total_size - file->offset;
    if (*size > remaining) {
        *size = remaining;
    }

    const char *data = (const char *)file->mapped + file->offset;
    file->offset += *size;

    return data;
}

void zc_read_end(zc_file *file) {
    // Nothing to do here
}

char *zc_write_start(zc_file *file, size_t size) {
    if (!file) return NULL;

    off_t required_size = file->offset + size;
    if (required_size > file->total_size) {
        if (ftruncate(file->fd, required_size) == -1) {
            return NULL;
        }
        file->total_size = required_size;
    }

    char *buffer = (char *)file->mapped + file->offset;
    file->offset += size;

    return buffer;
}

void zc_write_end(zc_file *file) {
    // Flush the changes to the file
    msync(file->mapped, file->total_size, MS_SYNC);
}

off_t zc_lseek(zc_file *file, long offset, int whence) {
    if (!file) return (off_t)-1;

    off_t new_offset = 0;
    if (whence == SEEK_SET) {
        new_offset = offset;
    } else if (whence == SEEK_CUR) {
        new_offset = file->offset + offset;
    } else if (whence == SEEK_END) {
        new_offset = file->total_size + offset;
    } else {
        return (off_t)-1;
    }

    if (new_offset < 0) {
        return (off_t)-1;
    }

    file->offset = new_offset;
    return file->offset;
}

int zc_copyfile(const char *source, const char *dest) {
    if (!source || !dest) return -1;

    zc_file *src_file = zc_open(source);
    if (!src_file) return -1;

    zc_file *dst_file = zc_open(dest);
    if (!dst_file) {
        zc_close(src_file);
        return -1;
    }

    size_t remaining = src_file->total_size;

    while (remaining > 0) {
        size_t chunk_size = remaining;
        const char *src_data = zc_read_start(src_file, &chunk_size);

        if (chunk_size == 0) {
            break;
        }

        char *dst_data = zc_write_start(dst_file, chunk_size);
        memcpy(dst_data, src_data, chunk_size);

        zc_write_end(dst_file);
        remaining -= chunk_size;
    }

    zc_close(src_file);
    zc_close(dst_file);

    return 0;
}
```

To solve this exercise, we will need to use a reader-writer lock (pthread_rwlock_t). We will also modify the zc_file structure to include the rwlock and a mutex for protecting the offset variable (pthread_mutex_t).

Here's the solution to Exercise 4:

```c
#include "zc_io.h"
#include <sys/mman.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <pthread.h>

struct zc_file {
    // Insert the fields you need here.
    void *mapped;
    off_t offset;
    size_t total_size;
    int fd;
    pthread_rwlock_t rwlock;
    pthread_mutex_t offset_mutex;
};

zc_file *zc_open(const char *path) {
    zc_file *file = malloc(sizeof(zc_file));
    if (!file) return NULL;

    file->fd = open(path, O_CREAT | O_RDWR);
    if (file->fd == -1) {
        free(file);
        return NULL;
    }

    struct stat st;
    fstat(file->fd, &st);
    file->total_size = st.st_size;

    file->mapped = mmap(NULL, file->total_size, PROT_READ | PROT_WRITE, MAP_SHARED, file->fd, 0);
    if (file->mapped == MAP_FAILED) {
        close(file->fd);
        free(file);
        return NULL;
    }
    file->offset = 0;

    pthread_rwlock_init(&file->rwlock, NULL);
    pthread_mutex_init(&file->offset_mutex, NULL);

    return file;
}

int zc_close(zc_file *file) {
    if (!file) return -1;

    msync(file->mapped, file->total_size, MS_SYNC);
    munmap(file->mapped, file->total_size);
    close(file->fd);

    pthread_rwlock_destroy(&file->rwlock);
    pthread_mutex_destroy(&file->offset_mutex);

    free(file);

    return 0;
}

const char *zc_read_start(zc_file *file, size_t *size) {
    if (!file || !size) return NULL;

    pthread_rwlock_rdlock(&file->rwlock);

    pthread_mutex_lock(&file->offset_mutex);
    size_t remaining = file->total_size - file->offset;
    if (*size > remaining) {
        *size = remaining;
    }

    const char *data = (const char *)file->mapped + file->offset;
    file->offset += *size;
    pthread_mutex_unlock(&file->offset_mutex);

    return data;
}

void zc_read_end(zc_file *file) {
    if (!file) return;

    pthread_rwlock_unlock(&file->rwlock);
}

char *zc_write_start(zc_file *file, size_t size) {
    if (!file) return NULL;

    pthread_rwlock_wrlock(&file->rwlock);

    pthread_mutex_lock(&file->offset_mutex);
    off_t required_size = file->offset + size;
    if (required_size > file->total_size) {
        if (ftruncate(file->fd, required_size) == -1) {
            pthread_mutex_unlock(&file->offset_mutex);
            return NULL;
        }
        file->total_size = required_size;
    }

    char *buffer = (char *)file->mapped + file->offset;
    file->offset += size;
    pthread_mutex_unlock(&file->offset_mutex);

    return buffer;
}

void zc_write_end(zc_file *file) {
    if (!file) return;

    // Flush the changes to the file
    msync(file->mapped, file->total_size, MS_SYNC);

    pthread_rwlock_unlock(&file->rwlock);
}

off_t zc_lseek(zc_file *file, long offset, int whence) {
    if (!file) return (off_t)-1;

    pthread_rwlock_wrlock(&file->rwlock);

    off_t new_offset = 0;
    if (whence == SEEK_SET) {
        new_offset = offset;
    } else if (whence == SEEK_CUR) {
        new_offset = file->offset + offset;
    } else if (whence == SEEK_END) {
        new_offset = file->total_size + offset;
    } else {
        pthread_rwlock_unlock(&file->rwlock);
        return (off_t)-1;
    }

    if (new_offset < 0) {
        pthread_rwlock_unlock(&file->rwlock);
        return (off_t)-1;
    }

    file->offset = new_offset;

    pthread_rwlock_unlock(&file->rwlock);

    return file->offset;
}
```

This implementation ensures that multiple zc_read operations can take place at the same time for the same instance of the zc_file, while no other operation should take place at the same time with a zc_write or zc_lseek operation. It also ensures that all operations issued while zc_write or zc_lseek is executing would block waiting to start. This is achieved by using reader-writer locks (pthread_rwlock_t) and a mutex for protecting the offset variable (pthread_mutex_t).

