import { Options, WebSocketHook, JsonValue } from './types';
export declare const useWebSocket: <T extends JsonValue | null = JsonValue | null>(url: string | (() => string | Promise<string>) | null, options?: Options, connect?: boolean) => WebSocketHook<T, MessageEvent<any> | null>;
useWebSocket

To use a WebSocket hook with React, you can create a custom hook that manages the WebSocket connection and updates the state with real-time data. Here's an example of a custom `useWebSocket` hook for your project:

```javascript
import { useState, useEffect, useRef } from "react";

const useWebSocket = (url, onMessage) => {
  const [socket, setSocket] = useState(null);
  const socketRef = useRef(null);

  useEffect(() => {
    if (url && typeof onMessage === 'function') {
      const ws = new WebSocket(url);
      setSocket(ws);
      socketRef.current = ws;

      ws.addEventListener('message', onMessage);

      ws.onopen = () => console.log("Socket opened", ws);
      ws.onclose = () => console.log("Socket closed", ws);
      ws.onerror = (error) => console.log("Socket error", error);
    }

    return () => {
      if (socketRef.current) {
        socketRef.current.close();
      }
    };
  }, [url, onMessage]);

  return [socket];
};

export default useWebSocket;
```

To use this `useWebSocket` hook with the Binance WebSocket API, first import the hook, and then update the `TradeDetails` component as follows:

