```csharp
private int GetMatchingOrNextAvailableBucket(K key)
{
    int startPosition = key.GetHashCode() % Table.Length;

    for (int i = 0; i < Capacity; i++)
    {
        int bucket = (startPosition + i) % Capacity;

        if (Table[bucket] == null || Table[bucket].Key.Equals(key))
