```csharp
public V Put(K key, V value)
{
    if (key == null)
    {
        throw new ArgumentNullException();
    }
    if (value == null)
    {
        throw new ArgumentNullException();
    }

    // Check if the current size meets the load factor threshold and trigger a Rehash if necessary.
    if (Size() >= this.Capacity * this.LoadFactor)
    {
