            entry.Value = value;
            return oldValue;
        }
    }

    // If the existing entry loop did not find a matching key, add a new entry.
    Entry<K, V> newEntry = new Entry<K, V>(key, value);
    newEntry.Next = this.Table[bucket];
    this.Table[bucket] = newEntry;
    this.size++;

