Using `ViewTreeObserver.OnPreDrawListener` allows you to run a `Runnable` before the view is drawn, while still being able to get called before the view is drawn, without having to delay your request.

以下是使用Apache Flink访问MySQL数据库的基本示例代码：

```java
import org.apache.flink.api.common.functions.MapFunction;
import org.apache.flink.api.java.DataSet;
import org.apache.flink.api.java.ExecutionEnvironment;
import org.apache.flink.api.java.tuple.Tuple2;
import org.apache.flink.connector.jdbc.JdbcConnectionOptions;
import org.apache.flink.connector.jdbc.JdbcInputFormat;
import org.apache.flink.connector.jdbc.JdbcOutputFormat;
import org.apache.flink.streaming.api.environment.StreamExecutionEnvironment;
import org.apache.flink.streaming.api.functions.sink.SinkFunction;
import org.apache.flink.types.Row;
import java.sql.PreparedStatement;
import java.util.Properties;

public class FlinkMySQLExample {

    public static void main(String[] args) throws Exception {

        // 执行批处理
        batchProcessing();

        // 执行流处理
        streamProcessing();
    }

    public static void batchProcessing() throws Exception {
        // 创建执行环境
        ExecutionEnvironment env = ExecutionEnvironment.getExecutionEnvironment();

        //配置连接参数
        final Properties props = new Properties();
        props.setProperty("driver", "com.mysql.jdbc.Driver");
        props.setProperty("url", "jdbc:mysql://localhost:3306/test");
        props.setProperty("username", "root");
        props.setProperty("password", "root");

        //创建JDBC输入格式
        JdbcInputFormat inputFormat = JdbcInputFormat.buildJdbcInputFormat()
                .setDBUrl(props.getProperty("url"))
                .setDrivername(props.getProperty("driver"))
                .setUsername(props.getProperty("username"))
                .setPassword(props.getProperty("password"))
                .setQuery("SELECT * FROM student")
                .setRowTypeInfo(null) //设置类型信息
                .finish();

        //读取数据
        DataSet<Row> rowData = env.createInput(inputFormat);

        //将数据map为tuple2
        DataSet<Tuple2<Integer, String>> resultSet = rowData.map(new MapFunction<Row, Tuple2<Integer, String>>() {
            @Override
            public Tuple2<Integer, String> map(Row row) throws Exception {
                return Tuple2.of((Integer) row.getField(0), row.getField(1).toString());
            }
        });

        //输出结果
        resultSet.print();
    }

    public static void streamProcessing() throws Exception {
        // 创建执行环境
        StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();

        //配置连接参数
        final Properties props = new Properties();
        props.setProperty("driver", "com.mysql.jdbc.Driver");
        props.setProperty("url", "jdbc:mysql://localhost:3306/test");
        props.setProperty("username", "root");
        props.setProperty("password", "root");

        //创建JDBC输入格式
        JdbcInputFormat inputFormat = JdbcInputFormat.buildJdbcInputFormat()
                .setDBUrl(props.getProperty("url"))
                .setDrivername(props.getProperty("driver"))
                .setUsername(props.getProperty("username"))
                .setPassword(props.getProperty("password"))
                .setQuery("SELECT * FROM student WHERE id > ?") //占位符
                .setRowTypeInfo(null) //设置类型信息
                .setParameterTypes(int.class) //设置占位符类型
                .finish();

        //创建数据源
        DataSet<Row> rowData = env.createInput(inputFormat);

        //将数据map为tuple2
        DataSet<Tuple2<Integer, String>> resultSet = rowData.map(new MapFunction<Row, Tuple2<Integer, String>>() {
            @Override
            public Tuple2<Integer, String> map(Row row) throws Exception {
                return Tuple2.of((Integer) row.getField(0), row.getField(1).toString());
            }
        });

        //将数据写入MySQL
        JdbcOutputFormat jdbcOutputFormat = JdbcOutputFormat.buildJdbcOutputFormat()
                .setDrivername(props.getProperty("driver"))
                .setDBUrl(props.getProperty("url"))
                .setUsername(props.getProperty("username"))
                .setPassword(props.getProperty("password"))
                .setQuery("INSERT INTO result VALUES (?,?)") //占位符
                .setSqlTypes(new int[] {java.sql.Types.INTEGER, java.sql.Types.VARCHAR}) //设置占位符类型
                .finish();

        resultSet.addSink(new SinkFunction<Tuple2<Integer, String>>() {
            @Override
            public void invoke(Tuple2<Integer, String> value) throws Exception {
                PreparedStatement preparedStatement = jdbcOutputFormat.getPreparedStatement(value);
                preparedStatement.execute();
            }
        });

        //执行任务
        env.execute();
    }
}
