public class MyBatisPlusDataSource extends RichSourceFunction<DataSource> {

    private static final String MYBATIS_CONFIG_PATH = "/flink/jdbc/mybatis.xml";
    private static final String JDBC_CONFIG_PATH = "/flink/jdbc/jdbc.properties";
    private DataSource dataSource;

    @Override
    public void open(Configuration parameters) throws Exception {
        super.open(parameters);

        // 读取MyBatis配置文件
        byte[] bytes = Files.readAllBytes(Paths.get(MYBATIS_CONFIG_PATH));
        String xml = new String(bytes, StandardCharsets.UTF_8);
        MybatisSqlSessionFactoryBean builder = new MybatisSqlSessionFactoryBean();
        builder.setDataSource(dataSource);
        builder.setConfiguration(new MybatisConfiguration());
        builder.setTypeAliasesPackage("com.xyz.entity");
        builder.setMapperLocations(new PathMatchingResourcePatternResolver().getResources("classpath*:mapper/*.xml"));
        builder.setGlobalConfig(new GlobalConfig()); //如果需要逻辑删除、分页等功能需要设置分页插件和逻辑删除插件等信息
        builder.setSqlSessionFactoryBuilder(new MybatisSqlSessionFactoryBuilder());
        builder.setConfigLocation(new ByteArrayResource(xml.getBytes(StandardCharsets.UTF_8)));
        SqlSessionFactory factory = builder.getObject();

        // 读取JDBC配置文件
        Properties properties = new Properties();
        FileSystem fs = getFS();
        Path path = new Path(JDBC_CONFIG_PATH);
        if (fs.exists(path)) {
            try (FSDataInputStream in = fs.open(path)) {
                properties.load(in);
            }
        }

        // 创建DataSource
        HikariDataSource dataSource = new HikariDataSource();
        dataSource.setDriverClassName("com.mysql.cj.jdbc.Driver");
        dataSource.setJdbcUrl(properties.getProperty("url"));
        dataSource.setUsername(properties.getProperty("username"));
        dataSource.setPassword(properties.getProperty("password"));

        this.dataSource = dataSource;
    }

    @Override
    public void run(SourceContext<DataSource> sourceContext) throws Exception {
        sourceContext.collect(dataSource);
    }

    @Override
    public void cancel() {
        // no-op
    }
}
