import org.apache.ibatis.session.SqlSessionFactory;

import javax.sql.DataSource;

public class MyBatisPlusSink<T> extends RichSinkFunction<T> {

    private static final String UPDATE = "update";
    private static final String UPDATE_CHAIN = "update-chain";
    private static final String DELETE = "delete";
    private static final String RETRACT = "retract";

    private MybatisPlusMapper<T> mapper;
    private transient SqlSession sqlSession;

    private final String operation;

    public MyBatisPlusSink(MybatisPlusMapper<T> mapper, String operation) {
        this.mapper = mapper;
        this.operation = operation;
    }

    @Override
    public void open(Configuration parameters) throws Exception {
        // 需要将DataSource对象临时注册到Configuration中
        Environment environment = new Environment("flink", new JdbcTransactionFactory(), dataSource);
        Configuration configuration = new Configuration(environment);
        SqlSessionFactory sqlSessionFactory = new SqlSessionFactoryBuilder().build(configuration);
        sqlSession = sqlSessionFactory.openSession();
        mapper.setSqlSession(sqlSession);
    }

    @Override
    public void close() throws Exception {
        super.close();
        sqlSession.commit();
        sqlSession.close();
    }

    @Override
    public void invoke(T value, Context context) throws Exception {
        switch (operation) {
            case UPDATE:
                mapper.update(new UpdateWrapper<>(value));
                break;
            case UPDATE_CHAIN:
                mapper.update(new UpdateChainWrapper<>(value));
                break;
            case DELETE:
                mapper.delete(new QueryWrapper<>(value));
                break;
            case RETRACT:
                mapper.insertOrUpdate(value);
                break;
        }
    }
}
