    }

    async start(): Promise<string> {
        this.isExecuted = false;
        this.isPaused = false;
        this.startTime = Date.now();
        this.requestAnimationFrameLoop();
        this.setTimeoutFallback();

        return new Promise<string>((resolve) => {
            this.resolvePromise = resolve;
        });
    }

    pause() {
