        this.isExecuted = true;
        if (this.resolvePromise) {
            this.resolvePromise('stopped');
        }
    }

    resume() {
        if (this.isExecuted && !this.looping) {
            return;
        }
        this.isPaused = false;
        this.elapsed = this.elapsed / DelayedMethod.speed;
        this.startTime = Date.now() - this.elapsed;
        this.requestAnimationFrameLoop();
        this.setTimeoutFallback();
    }

    private requestAnimationFrameLoop() {
        if (!this.isPaused) {
            this.elapsed = (Date.now() - (this.startTime ?? 0)) * DelayedMethod.speed;
            const remaining = this.delay - this.elapsed;

            if (remaining <= 0) {
                this.method();
                this.isExecuted = true;
                if (this.looping) {
                    this.elapsed = 0;
                    this.startTime = Date.now();
                } else {
                    if (this.resolvePromise) {
                        this.resolvePromise('finished');
                    }
                    return;
                }
            }
            this.requestId = requestAnimationFrame(this.requestAnimationFrameLoop.bind(this));
        }
    }

    private setTimeoutFallback() {
        if (!this.isPaused) {
            this.elapsed = (Date.now() - (this.startTime ?? 0)) * DelayedMethod.speed;
            const remaining = this.delay - this.elapsed;

            if (remaining <= 0) {
                this.method();
                this.isExecuted = true;
                if (this.looping) {
                    this.elapsed = 0;
                    this.startTime = Date.now();
                } else {
                    return;
                }
            }
            const nextTick = Math.max(remaining, 16) / DelayedMethod.speed;
            this.timeoutId = setTimeout(this.setTimeoutFallback.bind(this), nextTick);
        }
    }
}
