                            .flatMap(tuple -> tuple.getT1().setTags(tuple.getT2()).then())
                            .subscribeOn(Schedulers.boundedElastic());
                    return setTagsMono.thenReturn(blobItem);
                })
                .subscribeOn(Schedulers.boundedElastic())
                .publishOn(Schedulers.boundedElastic()));
    }
