#include <vector>
#include <cmath>
struct Signal {
  double power; //dbm
  double frequency;
  double bandwidth;
};

class WidebandSpectrumGenerator {
public:
  // Constructor
  WidebandSpectrumGenerator(double startFreq, double endFreq, double sampleRate, double noiseFloor, double snr, std::vector<Signal> signals) :
    m_startFreq(startFreq), m_endFreq(endFreq), m_sampleRate(sampleRate), m_noiseFloor(noiseFloor), m_snr(snr), m_signals(signals) {}

  // Generate the power spectrum for the given frequency range
  std::vector<double> generate() {
    // Set up the frequency domain vector
    double freqStep = m_sampleRate / m_spectrumSize;
    std::vector<double> freqs(m_spectrumSize);
    for (size_t i = 0; i < freqs.size(); ++i) {
      freqs[i] = m_startFreq + i * freqStep;
    }

    // Generate noise floor
    std::vector<double> noiseFloor = generateNoiseFloor(freqs);

    // Generate signals
    for (const Signal& signal : m_signals) {
      std::vector<double> signalSpectrum = generateSignalSpectrum(signal, freqs);
      // Add signal spectrum to overall spectrum
      for (size_t i = 0; i < m_spectrumSize; ++i) {
        m_powerSpectrum[i] += signalSpectrum[i];
      }
    }

    // Add noise floor to overall spectrum
    for (size_t i = 0; i < m_spectrumSize; ++i) {
      m_powerSpectrum[i] += noiseFloor[i];
    }

    // Return the resulting power spectrum
    return m_powerSpectrum;
  }

private:
  double m_startFreq; // Start frequency of spectrum range
  double m_endFreq; // End frequency of spectrum range
  double m_sampleRate; // Sample rate
  double m_noiseFloor; // Noise floor in dBm
  double m_snr; // Signal-to-noise ratio in dBm
  std::vector<Signal> m_signals; // List of signals to generate
  size_t m_spectrumSize = 1024; // Size of the power spectrum vector
  std::vector<double> m_powerSpectrum = std::vector<double>(m_spectrumSize, m_noiseFloor); // Initialize spectrum with noise floor

  // Generate the power spectrum for a single signal
  std::vector<double> generateSignalSpectrum(const Signal& signal, const std::vector<double>& freqs) {
    std::vector<double> signalSpectrum(m_spectrumSize);
    for (size_t i = 0; i < m_spectrumSize; ++i) {
      double freq = freqs[i];
      if (freq >= signal.frequency - signal.bandwidth / 2 && freq <= signal.frequency + signal.bandwidth / 2) {
        // Signal is in range
        double signalPower = dBmToW(signal.power);
        double noisePower = signalPower / dBToRatio(m_snr);

        // Generate complex spectrum for signal
        std::complex<double> signalComplex = generateSignalComplex(signalPower, freq);

        // Add noise to signal
        std::complex<double> noiseComplex = generateNoiseComplex(noisePower);
        std::complex<double> noisySignalComplex = signalComplex + noiseComplex;

        // Calculate power of noisy signal
        double noisySignalPower = std::abs(noisySignalComplex);
        double noisySignalPowerDbm = WToDbm(noisySignalPower);

        // Convert power to power spectral density
        double psd = WToDbm(noisySignalPower / m_sampleRate) - 30;

        // Assign power spectral density to frequency bin
        signalSpectrum[i] = psd;
      }
    }
    return signalSpectrum;
  }

  // Generate the noise floor for the given frequency range
  std::vector<double> generateNoiseFloor(const std::vector<double>& freqs) {
    std::vector<double> noiseFloor(m_spectrumSize);
    double noisePower = dBmToW(m_noiseFloor);
    for (size_t i = 0; i < m_spectrumSize; ++i) {
      double noise = generateNoisePower(noisePower);
      double psd = WToDbm(noise / m_sampleRate) - 30;
      noiseFloor[i] = psd;
    }
    return noiseFloor;
  }

  // Generate the power of noise for a given power
  double generateNoisePower(double power) {
    std::normal_distribution<double> dist(0, std::sqrt(power));
    double real = dist(m_rng);
    double imag = dist(m_rng);
    std::complex<double> noiseComplex(real, imag);
    return std::norm(noiseComplex);
  }

  // Generate a complex value for a signal with the given power and frequency
  std::complex<double> generateSignalComplex(double power, double frequency) {
    double phase = m_dist(m_rng) * 2.0 * M_PI;
    double amplitude = std::sqrt(dBmToW(power));
    double real = amplitude * std::cos(2.0 * M_PI * frequency / m_sampleRate + phase);
    double imag = amplitude * std::sin(2.0 * M_PI * frequency / m_sampleRate + phase);
    return std::complex<double>(real, imag);
  }

  // Generate a complex value for noise with the given power
  std::complex<double> generateNoiseComplex(double power) {
    std::normal_distribution<double> dist(0, std::sqrt(dBmToW(power)));
    double real = dist(m_rng);
    double imag = dist(m_rng);
    return std::complex<double>(real, imag);
  }

  // Convert dBm to watt
  double dBmToW(double dbm) {
    return std::pow(10.0, dbm / 10.0 - 3.0);
  }

  // Convert watt to dBm
  double WToDbm(double w) {
    return 10.0 * std::log10(w * 1000.0);
  }

  // Convert dB to ratio
  double dBToRatio(double db) {
    return std::pow(10.0, db / 10.0);
  }

  std::mt19937 m_rng; // Random number generator for signal generation
  std::uniform_real_distribution<double> m_dist{0.0, 1.0}; // Uniform distribution for signal phase
};
