        for (double freq = m_startFreq; freq <= m_endFreq; freq += m_sampleRate) {
            int index = static_cast<int>(freq - m_startFreq);
            spectrum[index] += m_noiseStdDev * randNormal();
        }
        // generate signals
        for (const Signal& signal : m_signals) {
            double powerDbm = signal.power;
            double powerW = dbmToWatt(powerDbm);
            double freq = signal.frequency;
            double bandwidth = signal.bandwidth;
            double sigma = std::sqrt(bandwidth / (2 * M_PI));
            // calculate complex spectrum
            std::vector<std::complex<double>> complexSpectrum(m_endFreq - m_startFreq + 1);
            for (double f = m_startFreq; f <= m_endFreq; f += m_sampleRate) {
                std::complex<double> value(powerW * std::exp(-std::pow(f - freq, 2) / (2 * std::pow(sigma, 2))), 0);
                complexSpectrum[static_cast<int>(f - m_startFreq)] = value;
            }
            // calculate power spectrum
            std::vector<double> powerSpectrum(m_endFreq - m_startFreq + 1);
            for (int i = 0; i < complexSpectrum.size(); ++i) {
                double mag = std::abs(complexSpectrum[i]);
                powerSpectrum[i] = wattToDbm(mag * mag);
            }
            // add signal spectrum to total spectrum
            for (int i = 0; i < spectrum.size(); ++i) {
                double freq = m_startFreq + i * m_sampleRate;
                double deltaFreq = std::abs(freq - signal.frequency);
                if (deltaFreq < signal.bandwidth / 2) {
                    spectrum[i] += powerSpectrum[i] - m_noiseFloorDbm;
                }
            }
        }
        return spectrum;
    }

private:
    double m_startFreq;
    double m_endFreq;
    double m_sampleRate;
    double m_noiseFloorDbm;
    double m_noiseStdDev;
    std::vector<Signal> m_signals;

    double randNormal() const {
        // generate normal random number with mean 0 and std deviation 1
        double u1 = static_cast<double>(rand()) / RAND_MAX;
        double u2 = static_cast<double>(rand()) / RAND_MAX;
        double z = std::sqrt(-2 * std::log(u1)) * std::cos(2 * M_PI * u2);
        return z;
    }

    double dbmToWatt(double dbm) const {
        return std::pow(10, dbm / 10);
    }

    double wattToDbm(double watt) const {
        return 10 * std::log10(watt);
    }
};
```

