#include <stdint.h>
#include <stdbool.h>
#include "sx1276.h"
#include "sx1276_registers.h"

// Set the frequency to be used (in Hz)
#define LORA_FREQUENCY 915000000

// Set the output power (in dBm)
#define LORA_OUTPUT_POWER 14

/*
 * Set the Continuous Wave mode configurations
 */
void sx1276_set_cw_mode(void) {
    // Set LoRa mode to FSK
    sx1276_write_reg(SX1276_REG_OPMODE, SX1276_FSK_OPMODE_SLEEP);

    // Start the crystal oscillator
    sx1276_write_reg(SX1276_REG_OPMODE, SX1276_FSK_OPMODE_STANDBY);

    // Set FSK mode
    sx1276_write_reg(SX1276_REG_OPMODE, SX1276_FSK_OPMODE_STANDBY_FSK);

    // Set the frequency
    uint32_t frequency = ((uint32_t)((double)LORA_FREQUENCY / SX1276_FXOSC) * (1 << 19));
    sx1276_write_reg(SX1276_REG_FRF_MSB, (uint8_t)(frequency >> 16));
    sx1276_write_reg(SX1276_REG_FRF_MID, (uint8_t)(frequency >> 8));
    sx1276_write_reg(SX1276_REG_FRF_LSB, (uint8_t)(frequency));

    // Set output power
    sx1276_write_reg(SX1276_REG_PACONFIG, (uint8_t)(LORA_OUTPUT_POWER & 0x0F));

    // Set continuous wave mode
    sx1276_write_reg(SX1276_REG_PACKETCONFIG2, SX1276_PACKETCONFIG2_CONTINUOUS_MODE);

    // Enable continuous wave transmission
    sx1276_write_reg(SX1276_REG_OPMODE, SX1276_FSK_OPMODE_TRANSMITTER);
}

int main(void) {
    // Initialize the SX1276 LoRa module
    sx1276_init();

    // Set continuous wave mode
    sx1276_set_cw_mode();

    // The module is now in continuous wave mode, transmitting at the set frequency and power

    while (true) {
        // Do something, or sleep
    }

    return 0;
}
