import android.os.AsyncTask;
import android.os.Bundle;
import android.view.View;
import android.widget.Button;
import android.widget.EditText;

import androidx.appcompat.app.AppCompatActivity;

public class MainActivity extends AppCompatActivity {

    Button btnUp, btnDown;
    EditText txtAddress;

    static final String wifiModuleIp = "192.168.1.100";
    static final int wifiModulePort = 22;
    static final String CMD = "python /path/to/script.py";

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_main);

        btnUp = findViewById(R.id.btnUp);
        btnDown = findViewById(R.id.btnDown);

        txtAddress = findViewById(R.id.ipAddress);

        btnUp.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View v) {
                // Execute the command on the Raspberry Pi using SSH
                Soket_AsyncTask task = new Soket_AsyncTask();
                task.execute(CMD);
            }
        });
    }

    private static class Soket_AsyncTask extends AsyncTask<String, Void, Void> {
        @Override
        protected Void doInBackground(String... params) {
            try {
                // Connect to the Raspberry Pi using SSH
                JSch jsch = new JSch();
                Session session = jsch.getSession("username", wifiModuleIp, wifiModulePort);
                session.setPassword("password");

                // Set HostKey
                session.setConfig("StrictHostKeyChecking", "no");

                // Establish the connection
                session.connect();

                // Execute the command
                ChannelExec channel = (ChannelExec) session.openChannel("exec");
                channel.setCommand(params[0]);
                channel.connect();

                // Wait for the command to finish executing
                while (!channel.isClosed()) {
                    try {
                        Thread.sleep(100);
                    } catch (InterruptedException e) {
                        e.printStackTrace();
                    }
                }

                // Disconnect the SSH channel and session
                channel.disconnect();
                session.disconnect();

            } catch (JSchException e) {
                e.printStackTrace();
            }
            return null;
        }
    }
}
