use std::time::{Duration, Instant};

fn exponential_backoff(retries: u32, max_retries: u32, base_interval: u64) -> Option<Duration> {
    if retries >= max_retries {
        return None;
    }

    let backoff_interval = 2u64.pow(retries) * base_interval;
    let wait_duration = Duration::from_millis(backoff_interval);

    Some(wait_duration)
}

