        {
            int startPosition = Math.Abs(key.GetHashCode()) % this.Table.Length;

            for (int i = 0; i < this.Capacity; i++)
            {
                int bucket = (startPosition + i) % this.Capacity;

                if (this.Table[bucket] == null || this.Table[bucket].Key.Equals(key))
                {
