            {
                if (entry.Key.Equals(key))
                {
                    V oldValue = entry.Value;
                    entry.Value = value;

                    return oldValue;
                }
            }

            Entry<K, V> newEntry = new Entry<K, V>(key, value);
            newEntry.Next = this.Table[bucket];
            this.Table[bucket] = newEntry;
            this.size++;

            return default(V);
