To create a p5.js script that visualizes a video with an animated face, you'll first need a video file, which you can host online or include in your project. For this example, I'll use a sample video from the p5.js website.

```javascript
let video;
let faceSize = 20;

function setup() {
  createCanvas(640, 360);
  video = createVideo(['https://p5js.org/assets/examples/lucky_color.mov']); // Use any video URL
  video.hide();
}

function draw() {
  image(video, 0, 0, width, height); // Display the video on the canvas

  faceSize += random(-1, 1); // Add animation to the face size
  faceSize = constrain(faceSize, 10, 50);

  // Find the center of the video
  const centerX = width / 2;
  const centerY = height / 2;

  // Draw the animated face
  drawFace(centerX, centerY);
}

function drawFace(x, y) {
  // Draw the face circle
  fill(255, 0, 0, 120);
  circle(x, y, faceSize * 2);

  // Draw the eyes
  fill(255);
  circle(x - faceSize / 2, y - faceSize / 2, faceSize / 2);
  circle(x + faceSize / 2, y - faceSize / 2, faceSize / 2);

  // Draw the pupils
  fill(0);
  circle(x - faceSize / 2, y - faceSize / 2, faceSize / 4);
  circle(x + faceSize / 2, y - faceSize / 2, faceSize / 4);

  // Draw the mouth
  stroke(255);
  strokeWeight(3);
  arc(x, y + faceSize / 3, faceSize, faceSize / 2, 0, PI);
  noStroke();
}

function mouseClicked() {
  video.loop(); // Toggle the video between playing and pausing
}
```

This script displays a video on the canvas and adds an animated face on top of it. The face size changes randomly to create the animation effect. When clicking on the video, it will start playing and loop.

