Here is a sample code to get the average of 60 EMG (electromyography) and GSR (galvanic skin response) data from sensors using Arduino UNO:

```cpp
#include <Wire.h>

const int numReadings = 60;
int emgReadings[numReadings];
int gsrReadings[numReadings];
int emgTotal = 0;
int gsrTotal = 0;
int emgIndex = 0;
int gsrIndex = 0;
int emgAverage = 0;
int gsrAverage = 0;

const int emgPin = A0; // Analog pin for EMG sensor
const int gsrPin = A1; // Analog pin for GSR sensor

void setup() {
  Serial.begin(9600);

  // Initialize the arrays
  for (int i = 0; i < numReadings; i++) {
    emgReadings[i] = 0;
    gsrReadings[i] = 0;
  }
}

void loop() {
  // Read sensor values
  int emgSensorValue = analogRead(emgPin);
  int gsrSensorValue = analogRead(gsrPin);

  // Subtract the last reading from the total
  emgTotal = emgTotal - emgReadings[emgIndex];
  gsrTotal = gsrTotal - gsrReadings[gsrIndex];

  // Add the new reading to the total
  emgReadings[emgIndex] = emgSensorValue;
  gsrReadings[gsrIndex] = gsrSensorValue;
  emgTotal = emgTotal + emgSensorValue;
  gsrTotal = gsrTotal + gsrSensorValue;

  // Increment the index
  emgIndex = (emgIndex + 1) % numReadings;
  gsrIndex = (gsrIndex + 1) % numReadings;

  // Calculate the averages
  emgAverage = emgTotal / numReadings;
  gsrAverage = gsrTotal / numReadings;

  // Print the average values
  Serial.print("EMG average: ");
  Serial.println(emgAverage);
  Serial.print("GSR average: ");
  Serial.println(gsrAverage);

  delay(1000); // Wait for a second before taking the next reading
}

```

This code will read data from EMG and GSR sensor connected to A0 and A1 pins, respectively. It will store and update these values in two separate arrays, and then calculate and print the average of 60 readings for each sensor.

