    WorkspaceShare firstUnsyncShare = userGroupShares.stream()
            .filter(ws -> !ws.getSyncDisplayField())
            .findFirst()
            .orElse(null);

    if (firstUnsyncShare != null) {
        userRole.setSyncWithUserId(firstUnsyncShare.getRealSenderId());
        userRole.setSyncDisplayField(false);
    } else {
        setUserRoleSyncConfig(userRole, userGroupShares.get(0), allWorkspaceShares);
    }
}
