private BufferedImage binarizeImage(BufferedImage image, int threshold1, int threshold2) {
		int width = image.getWidth();
		int height = image.getHeight();
		BufferedImage binarizedImage = new BufferedImage(width, height, BufferedImage.TYPE_BYTE_BINARY);
		Graphics2D g = binarizedImage.createGraphics();
		g.drawImage(image, 0, 0, null);
		Raster raster = binarizedImage.getRaster();
		for (int i = 0; i < width; i++) {
			for (int j = 0; j < height; j++) {
				int[] pixel = raster.getPixel(i, j, (int[]) null);
				int red = pixel[0];
				int green = pixel[1];
				int blue = pixel[2];
				int brightness = (int) (0.2126 * red + 0.7152 * green + 0.0722 * blue);
				if (brightness >= threshold1 && brightness <= threshold2) {
					raster.setSample(i, j, 0, 0);
				} else {
					raster.setSample(i, j, 0, 1);
				}
			}
		}
		return binarizedImage;
	}
