private BufferedImage binarizeImage(BufferedImage image, int threshold) {
    int width = image.getWidth();
    int height = image.getHeight();
    BufferedImage binarizedImage = new BufferedImage(width, height, BufferedImage.TYPE_BYTE_BINARY);
    Graphics2D g = binarizedImage.createGraphics();
    g.drawImage(image, 0, 0, null);
    WritableRaster raster = binarizedImage.getRaster();
    int numBands = raster.getNumBands();
    for (int i = 0; i < width; i++) {
        for (int j = 0; j < height; j++) {
            int[] pixel = raster.getPixel(i, j, new int[numBands]);
            int brightness = 0;
            if (numBands == 1) {
                brightness = pixel[0];
            } else {
                int red = pixel[0];
                int green = pixel[1];
                int blue = pixel[2];
                brightness = (int) (0.2126 * red + 0.7152 * green + 0.0722 * blue);
            }
            if (brightness >= threshold) {
                raster.setSample(i, j, 0, 0);
            } else {
                raster.setSample(i, j, 0, 1);
            }
        }
    }
    return binarizedImage;
}

