```
import androidx.compose.foundation.lazy.LazyColumn
import androidx.compose.foundation.lazy.items
import androidx.compose.runtime.*
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.launch
import kotlinx.coroutines.withContext

data class User(val name: String, val age: Int, val city: String)

@Composable
fun UsersList() {
    var users by remember { mutableStateOf(emptyList<User>()) }

    LaunchedEffect(true) {
        users = withContext(Dispatchers.IO) {
            getUsersFromDatabase() // coroutine function to retrieve rows
        }
    }

    LazyColumn {
        items(users) { user ->
            // display each user in a separate item in the LazyColumn
            UserItem(user)
        }
    }
}

@Composable
fun UserItem(user: User) {
    // display a user's name, age, and city
}

suspend fun getUsersFromDatabase(): List<User> {
    // coroutine function to retrieve rows from database and create User objects
}
```

In this example, we use a `var` with `mutableStateOf` to hold the list of users that we retrieve from the database. We use a `LaunchedEffect` that runs when the `UsersList` is first composable to retrieve the users from the database in a coroutine function called `getUsersFromDatabase()`. Once we have the users, we pass them as the argument to the `items` function of `LazyColumn`, which will display each user in a separate item using the `UserItem` composable. 

Note that we use `withContext(Dispatchers.IO)` to run the `getUsersFromDatabase()` function on a background thread, since it performs IO operations. We also mark the `getUsersFromDatabase()` function with `suspend` so that it can be called from a coroutine.

