```csharp
private void SecondWorker_DoWork(object sender, DoWorkEventArgs e)
{
    int n = 0;

    while (n < sourceListBox.Items.Count)
    {
        var work = workers.FirstOrDefault(f => f.IsBusy == false);

        if (work != null)
        {
            Bitmap image = new Bitmap(openFileDialog.FileNames[n]);
            List<int> dpis = new List<int> { 1, 2, 4, 8, 16, 32, 64, 128 };

            foreach (int dpiMultiplier in dpis)
            {
                Bitmap resizedImage = new Bitmap(image, new Size(image.Width * dpiMultiplier, image.Height * dpiMultiplier));
                resizedImage.SetResolution(image.HorizontalResolution * dpiMultiplier, image.VerticalResolution * dpiMultiplier);
                List<object> arguments = new List<object>();
                arguments.Add(resizedImage);
                arguments.Add(openFileDialog.FileNames[n] + $"_{dpiMultiplier}");
                work.RunWorkerAsync(arguments);
            }

            n++;
        }
    }
}
