        set { _email = value; }
    }

    public string Address
    {
        get { return _address; }
        set { _address = value; }
    }

    public static void SaveCustomers(List<Customer> customers, string fileName)
    {
        IFormatter formatter = new BinaryFormatter();
        using (Stream stream = new FileStream(fileName, FileMode.Create, FileAccess.Write, FileShare.None))
        {
            formatter.Serialize(stream, customers);
        }
    }

    public static List<Customer> LoadCustomers(string fileName)
    {
        List<Customer> customers;
        IFormatter formatter = new BinaryFormatter();
        using (Stream stream = new FileStream(fileName, FileMode.Open, FileAccess.Read, FileShare.Read))
        {
            customers = (List<Customer>)formatter.Deserialize(stream);
        }
        return customers;
    }
}
