To achieve this, you can create a `CustomerManager` class that handles the serialization and deserialization of the `Customer` objects to and from a file (acting as a mock database). Here's an example implementation:

```csharp
using System;
using System.IO;
using System.Collections.Generic;
using System.Runtime.Serialization.Formatters.Binary;

public class CustomerManager
{
    private List<Customer> _customers;
    private string _filePath;

    public CustomerManager(string filePath)
    {
        _filePath = filePath;
        LoadData();
    }

    public void LoadData()
    {
        if (!File.Exists(_filePath))
        {
            _customers = new List<Customer>();
        }
        else
        {
            using (var stream = File.OpenRead(_filePath))
            {
                try
                {
                    BinaryFormatter formatter = new BinaryFormatter();
                    _customers = (List<Customer>)formatter.Deserialize(stream);
                }
                catch
                {
                    _customers = new List<Customer>();
                }
            }
        }
    }

    public void SaveData()
    {
        using (var stream = File.OpenWrite(_filePath))
        {
            BinaryFormatter formatter = new BinaryFormatter();
            formatter.Serialize(stream, _customers);
        }
    }

    public void AddCustomer(Customer customer)
    {
        _customers.Add(customer);
        SaveData();
    }

    public void RemoveCustomer(Customer customer)
    {
        _customers.Remove(customer);
        SaveData();
    }

    public IReadOnlyList<Customer> GetAllCustomers()
    {
        return _customers.AsReadOnly();
    }
}
```

Then, you can use the `CustomerManager` class to create, store, and load `Customer` objects. For example:

```csharp
public class Program
{
    public static void Main(string[] args)
    {
        // Initialize CustomerManager and create some customers
        CustomerManager manager = new CustomerManager("customer_data.bin");

        Customer customer1 = new Customer("user1", "pass1", "Full Name", "email1@example.com", "Address 1");
        Customer customer2 = new Customer("user2", "pass2", "Full Name", "email2@example.com", "Address 2");

        // Add customers to "database"
        manager.AddCustomer(customer1);
        manager.AddCustomer(customer2);

        // Load customers from "database"
        IReadOnlyList<Customer> customers = manager.GetAllCustomers();
        foreach (Customer customer in customers)
        {
            Console.WriteLine($"UserName: {customer.UserName}\nFullName: {customer.FullName}");
        }
    }
}
```

This implementation serializes the entire list of customers every time a new customer is added, and deserializes the list every time the application starts. This is fine for a small-scale application, but if you're working with a large number of customers, you may want to consider using a proper database system, such as SQLite or SQL Server.

