public List<Customer> LoadCustomersFromDatabase()
{
    List<Customer> loadedCustomers = new List<Customer>();

    using (OleDbConnection connection = new OleDbConnection(connectionString))
    {
        connection.Open();
        using (OleDbCommand cmd = new OleDbCommand("SELECT * FROM tbl_users WHERE [User Type]='Customer'", connection))
        using (OleDbDataReader reader = cmd.ExecuteReader())
        {
            while (reader.Read())
            {
