            printWelcome(vName, vPass, vGender, vEmail, vPhoneNumber, out);

            if ("on".equalsIgnoreCase(rememberMe)) {
                Cookie usernameC = new Cookie("username", vName);
                usernameC.setMaxAge(60 * 60 * 24);
                resp.addCookie(usernameC);

                Cookie passwordC = new Cookie("password", vPass);
                passwordC.setMaxAge(60 * 60 * 24);
                resp.addCookie(passwordC);

                Cookie remember = new Cookie("rememberMe", rememberMe);
                remember.setMaxAge(60 * 60 * 24);
                resp.addCookie(remember);
            }
        } else {
            Cookie[] cookies = req.getCookies();
            String savedUsername = "";
            String savedPassword = "";
            String savedRememberMe = "";

            if (cookies != null) {
                for (Cookie cookie : cookies) {
                    if ("username".equals(cookie.getName())) {
                        savedUsername = cookie.getValue();
                    } else if ("password".equals(cookie.getName())) {
                        savedPassword = cookie.getValue();
                    } else if ("rememberMe".equals(cookie.getName())) {
                        savedRememberMe = cookie.getValue();
                    }
                }
            }

            if ("on".equalsIgnoreCase(savedRememberMe) && vName != null && vPass != null && vName.equals(savedUsername) && vPass.equals(savedPassword)) {
                printWelcome(savedUsername, savedPassword, vGender, vEmail, vPhoneNumber, out);
            } else {
                out.println("<html><body>");
                out.println("<p>Invalid username and/or password</p>");
                out.println("</body></html>");
            }
        }

        out.println("</body></html>");
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp) throws ServletException, IOException {
        doGet(req, resp);
    }
}
```

This version of the code should better handle cookie creation, reading, and user validation. Please note that storing sensitive data like username and password in plain text cookies is not recommended for security reasons. This code should be used for demonstration purposes only, and not in a production environment.

