export const bindingThroughBasket = ({ orders, params }) => async (dispatch) => {
  dispatch(lockMain);

  const checkErrors = ({ errors, sum }) => {
    const errorsResult = getErrorsFromBasket(errors);
    const isPayed = !sum.to_pay;
