      const changeErrors = checkErrors(orderData);
      await dispatch(apiBasket('save', {}, true));
      const saveErrors = getErrorsFromBasket(orderData.errors);
      const errorsResult = [...paramsErrors, ...changeErrors, ...saveErrors];
      if (errorsResult.length > 0) {
        throw new Error('Calculated errors occur.');
      }
    } catch (error) {
      console.error(error);
    }
  });

