1. Import the required libraries and styles in your component file.

```html
<script setup>
import { ref } from 'vue';
import { VueDraggable } from '@shopify/draggable';

const draggable = ref(null);
const items = ref([
  { id: 1, name: 'Card 1' },
  { id: 2, name: 'Card 2' },
  { id: 3, name: 'Card 3' },
  { id: 4, name: 'Card 4' },
]);

onMounted(() => {
  draggable.value = new VueDraggable(document.querySelector('.cards-container'), {
    draggable: '.card',
  });

  // Update items order after drag ends
  draggable.value.on('drag:stop', () => {
    const newItems = [...items.value];
    const { newIndex, oldIndex } = draggable.value.getDragEvent();
    const movedItem = newItems.splice(oldIndex, 1)[0];
    newItems.splice(newIndex, 0, movedItem);
    items.value = newItems;
  });
});
</script>
```

