def bounding_box_location(image_width, image_height, bounding_box):
    x_min, y_min, x_max, y_max = bounding_box
    midpoint_x = (x_min + x_max) / 2
    midpoint_y = (y_min + y_max) / 2
    image_midpoint_x = image_width / 2
    image_midpoint_y = image_height / 2

    # Determine the quadrant
    if midpoint_x < image_midpoint_x:
        if midpoint_y < image_midpoint_y:
            position = "top-left"
        else:
            position = "bottom-left"
    else:
        if midpoint_y < image_midpoint_y:
            position = "top-right"
        else:
            position = "bottom-right"

    # Determine the side
    if position in ("top-left", "bottom-left"):
        side = "left"
    elif position in ("bottom-left", "bottom-right"):
        side = "down"
    elif position in ("top-left", "top-right"):
        side = "up"
    else:
        side = "right"

    return position, side

# Example usage
