def bounding_box_side(image_width, image_height, bounding_box):
    xmin, ymin, width, height = bounding_box
    xmax = xmin + width
    ymax = ymin + height
    cx = image_width // 2
    cy = image_height // 2

    if ymax < cy:
        if xmax < cx:
            return "top-left", 0.25
        elif xmin > cx:
            return "top-right", 0.25
        else:
            return "top", 0.5

    if ymin > cy:
        if xmax < cx:
            return "bottom-left", 0.25
        elif xmin > cx:
            return "bottom-right", 0.25
        else:
            return "bottom", 0.5

    if xmax < cx:
        return "left", 0.5
    elif xmin > cx:
        return "right", 0.5
    else:
        return "centered", 1.0

