2. Disable gravity for the Rigidbody component (if you don't want your character to be affected by gravity), by unchecking the "Use Gravity" checkbox in the Inspector panel.

3. Create a new C# script named "CharacterControllerWithInertia" by navigating to Assets > Create > C# Script. Double-click the script file in the Project panel to open it in your script editor.

4. Replace the default code with the following script:

```csharp
using System.Collections;
using System.Collections.Generic;
using UnityEngine;

public class CharacterControllerWithInertia : MonoBehaviour
{
    public float moveSpeed = 10f;
    public float inertia = 0.9f;
    private Rigidbody rb;

    void Start()
    {
        rb = GetComponent<Rigidbody>();
    }

    void FixedUpdate()
    {
        float horizontal = Input.GetAxis("Horizontal");
        float vertical = Input.GetAxis("Vertical");

        Vector3 moveDirection = new Vector3(horizontal, 0, vertical);

