To detect rectangles and squares in an image, you can use an OpenCV library with the p5.js JavaScript library in OpenProcessing.

First, you need to add the OpenCV.js library to your sketch by clicking on the 'gear' icon in the OpenProcessing editor, selecting 'Add External lib.' and pasting the following link:
`https://docs.opencv.org/master/opencv.js`

Here is an example of using OpenCV.js in p5.js to detect rectangles and squares:

```javascript
let img;
let cvImage;
let src;
let gray;
let contours;
let hierarchy;

function preload() {
  img = loadImage("test_image.jpg"); // load your image here
}

function setup() {
  createCanvas(img.width, img.height);
  img.loadPixels();
  cvImage = new cv.Mat(img.height, img.width, cv.CV_8UC4);
  src = new cv.Mat(img.height, img.width, cv.CV_8UC4);
  gray = new cv.Mat();
  contours = new cv.MatVector();
  hierarchy = new cv.Mat();
}

function detectRectangles() {
  for (let i = 0; i < contours.size(); ++i) {
    let cnt = contours.get(i);
    let approx = new cv.Mat();
    let perimeter = cv.arcLength(cnt, true);
    cv.approxPolyDP(cnt, approx, 0.02 * perimeter, true);
    let area = cv.contourArea(cnt);
    let boundingRect = cv.boundingRect(cnt);

    if (approx.rows === 4 && area > 1000) {
      let x = boundingRect.x;
      let y = boundingRect.y;
      let w = boundingRect.width;
      let h = boundingRect.height;
      let aspectRatio = Math.max(w, h) / Math.min(w, h)

      if (aspectRatio < 1.2) { // aspect ratio threshold for squares
        fill(255, 0, 0);
        rect(x, y, w, h);
      } else {
        fill(0, 255, 0);
        rect(x, y, w, h);
      }
    }
    approx.delete();
    cnt.delete();
  }
}

function draw() {
  cvImage.data.set(img.pixels);
  cv.cvtColor(cvImage, src, cv.COLOR_RGBA2RGB);
  cv.cvtColor(src, gray, cv.COLOR_RGB2GRAY);

  cv.Canny(gray, gray, 100, 200);
  cv.findContours(gray, contours, hierarchy, cv.RETR_EXTERNAL, cv.CHAIN_APPROX_SIMPLE);

  background(0);
  detectRectangles();

  src.delete();
  gray.delete();
  contours.delete();
  hierarchy.delete();
}
```

Replace "test_image.jpg" with the URL or file path of your target image. This code uses OpenCV.js to preprocess the image, detect contours, and approximate the contour shape. If a contour has 4 vertices and a sufficient area, the code will draw a rectangle around the detected shape. The aspect ratio threshold determines whether the shape is considered square or rectangular.

