Here's the Java code to detect rectangles and squares in a still image (JPG) using the Processing IDE:

```java
import gab.opencv.*;
import processing.core.PImage;
import java.awt.Rectangle;

PImage inputImage;
OpenCV opencv;

void setup() {
  inputImage = loadImage("test_image.jpg"); // Load your image here

  size(inputImage.width, inputImage.height);
  opencv = new OpenCV(this, inputImage);
  opencv.gray();
  opencv.threshold(0); //Set threshold to detect edges
  opencv.findContours();
}

void draw() {
  image(inputImage, 0, 0);
  noFill();
  strokeWeight(2);

  for (Contour contour : opencv.findContours()) {
    Rectangle box = contour.getBoundingBox();
    float aspectRatio = (float) Math.max(box.width, box.height) / Math.min(box.width, box.height);

    if (aspectRatio < 1.2) { // aspect ratio threshold for squares
      stroke(255, 0, 0); // red
    } else {
      stroke(0, 255, 0); // green
    }
    rect(box.x, box.y, box.width, box.height);
