import gab.opencv.*;
import processing.core.PImage;
import java.awt.Rectangle;

PImage inputImage;
OpenCV opencv;

void setup() {
  inputImage = loadImage("test_image.jpg"); // Load your image here

  size(inputImage.width, inputImage.height);
  opencv = new OpenCV(this, inputImage);
  opencv.gray();
  opencv.threshold(0); //Set threshold to detect edges
  opencv.findContours();
}

void draw() {
