  noFill();
  strokeWeight(2);

  for (Contour contour : opencv.findContours()) {
    Rectangle box = contour.getBoundingBox();
    float aspectRatio = (float) Math.max(box.width, box.height) / Math.min(box.width, box.height);

    if (aspectRatio < 1.2) { // aspect ratio threshold for squares
