AVCodec* hevc_decoder = avcodec_find_decoder(AV_CODEC_ID_HEVC);
AVCodecContext* hevc_decoder_ctx = avcodec_alloc_context3(hevc_decoder);
avcodec_open2(hevc_decoder_ctx, hevc_decoder, NULL);

