using UnityEngine;

public class CarController : MonoBehaviour {

	public float moveSpeed = 5.0f;  // The movement speed of the car
	public float maxSpeed = 20.0f;  // The maximum speed the car can reach
	public float accelRate = 10.0f;  // The rate at which the car accelerates
	public float decelRate = 20.0f;  // The rate at which the car decelerates
	public float turnSpeed = 100.0f;  // The speed at which the car turns

    private float currentSpeed = 0.0f;  // The current speed of the car
	private Rigidbody rigidBody;  // The car's rigidbody component

	void Start () {
		rigidBody = GetComponent<Rigidbody>();  // Get the car's rigidbody component
	}

	void FixedUpdate () {

		float acceleration = Input.GetAxis("Accelerate");  // Get the input for acceleration
		float braking = Input.GetAxis("Brake");  // Get the input for braking
		float turning = Input.GetAxis("Horizontal");  // Get the input for turning

		if (acceleration > 0.0f && currentSpeed < maxSpeed) {  // Accelerate if the car's speed is less than the max speed
			currentSpeed += Mathf.Lerp(0.0f, accelRate, acceleration);  // Increase the car's speed based on the input
		} else if (braking > 0.0f) {  // Decelerate if the brake input is given
			currentSpeed -= Mathf.Lerp(0.0f, decelRate, braking);  // Decrease the car's speed based on the input
		} else {
			currentSpeed = Mathf.Lerp(currentSpeed, 0.0f, decelRate * Time.deltaTime);  // Decelerate smoothly when no input is given
		}

		Vector3 movement = transform.forward * currentSpeed * Time.deltaTime;  // Calculate the car's movement based on current speed
		movement.y = rigidBody.velocity.y;  // Preserve the y-axis velocity

		rigidBody.velocity = movement;  // Apply the movement to the car's rigidbody

		float turnAngle = turning * turnSpeed * Time.deltaTime;  // Calculate turning angle based on input and turning speed

		transform.Rotate(0.0f, turnAngle, 0.0f);  // Apply turning to the car's transform
	}

	void OnCollisionEnter(Collision collision) {
		Debug.Log("Collided with " + collision.gameObject.name);  // Log collision event
	}
