           dataSource.setDriverClassName(properties.getProperty("driverClassName"));
           dataSource.setUrl(properties.getProperty("jdbcUrl"));
           dataSource.setUsername(properties.getProperty("username"));
           dataSource.setPassword(properties.getProperty("password"));
           conf.setString("sql-env.jdbc.url", "jdbc:mysql://localhost:3306/flink_test?characterEncoding=utf8");
           conf.setString("sql-env.jdbc.username", "root");
           conf.setString("sql-env.jdbc.password", "root");

           conf.setString("sql.env.default-database", "flink_test");
           conf.setString("sql-env.lookup.cache.max-rows", "1000000");
           StreamTableEnvironment tEnv = StreamTableEnvironment.create(
                   env,
                   EnvironmentSettings.newInstance().useBlinkPlanner().inStreamingMode().build(),
                   new TableConfig()
                           .setSubsectionOptimization(true)
                           .setIdleStateRetentionTime(Time.hours(72), Time.hours(96))
           );
           tEnv.getConfig().setSqlDialect(SqlDialect.DEFAULT);
           tEnv.getConfig().getConfiguration().addAll(conf);

           VariableSubstitutor substitutor = new TestVariableSubstitutor();
           tEnv.getCatalog(tEnv.getCurrentCatalog()).get().getFactory().createCatalogFunction("substituteVariables", substitutor);
           tEnv.registerFunction("substituteVariables", new ScalarFunction() {
               private static final long serialVersionUID = -4174732384694994715L;
               @DataTypeHint(DataType.STRING)
