}

func parseDailyResult(result *redis.StringCmd) (float64, error) {
	str, err := result.Result() // Changed to Result() to get the raw string
	if errors.Is(err, redis.Nil) {
		return 0, nil
	} else if err != nil {
		return 0, fmt.Errorf("failed getting daily result string: %w", err)
	}

