          const listIndex = list.findIndex(({ ol }) => Boolean(ol));

          if (listIndex > 1) {
            newList.push(...list.slice(0, listIndex - 1));
          }

          const previousItem = list[listIndex - 1];
          const item = list[listIndex];

          newList.push({ stack: [previousItem, ParserHelper.fixOlListsHelper(item)] });

          const listRest = list.slice(listIndex + 1);

          test = listRest.some(({ ol }) => Boolean(ol));
          list = listRest;

          if (!test) newList.push(...listRest);
        }

        return { ol: newList, ...options };
      }
    }

    // Parser

    class BBCodeParser {
      constructor() {
        this.functions = [
          this.prepareContent,
          this.breakLineTagsHandler,
          this.horizontalRuleTagHandler,
          this.horizontalRuleTagParser,
          this.outsiderStylesParser,
          this.insiderStylesParser,
          this.fixOlLists,
        ].map((fn) => fn.bind(this));

        this.tags = new Tags();
      }

      prepareContent(contents = '') {
        if (!contents || typeof contents !== 'string') {

          return '';

        }

        const tags = [...this.tags.getBreakLineTags(), 'li'];

        const beforeTags = Patterns.getBreakLineBeforeTag(['ul', 'ol', 'li'], 'g');
        const afterTags = Patterns.getBreakLineAfterTag(tags, 'g');

        contents = contents.replace(/\[ml\]/g, '');
        contents = contents.replace(/\[\/ml\]/g, '\n');

        contents = contents.replace(/\n\[\/(center|justify|right|code)\]/g, (match, tag) => `[/${tag}]\n`);

        contents = contents.replace(/\[\/quote\]/g, (match) => match + '\n');

        contents = contents.replace(afterTags, '');
        contents = contents.replace(beforeTags, (match, tag) => {
          if (tags.includes(tag)) return match;

          return match.replace(/\n/, '');
        });

        return contents;
      }

      breakLineTagsHandler(contents) {
        if (!contents) return [];

        const breakLineTags = this.tags.getBreakLineTags('hr');
        const openingTagPattern = Patterns.getOpeningTag(breakLineTags);

        const result = contents.chopString(openingTagPattern);

        if (typeof result === 'string') return [result];

        return result;
      }

      horizontalRuleTagHandler(contents) {
        const openingTagPattern = Patterns.getOpeningTag(['hr']);

        return contents.map((line) => line.chopString(openingTagPattern, false)).flat();
      }

      horizontalRuleTagParser(contents) {
        return contents.map((line) => {
          if (line !== '[hr]') return line;
          return { canvas: [{ type: 'line', x1: 0, y1: 0, x2: 515, y2: 0, lineWidth: 1 }] };
        });
      }

      outsiderStylesParser(contents) {
        const tags = this.tags.getAllTags('hr');
        const pattern = Patterns.getFullTag(tags, 's');

        return contents.map((line) => ParserHelper.getOutsiderLineStyles(line, pattern));
      }

      insiderStylesParser(contents) {
        const tags = this.tags.getAllTags('hr');

        const openingTagPattern = Patterns.getOpeningTag(tags);
        const outsiderTagPattern = Patterns.getFullTag(tags, 's');

        return contents.map((line) => ParserHelper.getInsiderLineStyles(line, openingTagPattern, outsiderTagPattern));
      }

      fixOlLists(contents) {
        return contents.map(ParserHelper.fixOlListsHelper);
      }

      getParsedText(text) {
        return ParserHelper.pipe(this.functions, text);
      }
    }

    return new BBCodeParser();
  }

The output of the BBcode parser when it encounters a [code] tag is a table with its layout set to codeLayout, which has a default value of { fillColor: () => '#23241f', vLineWidth: () => 0, hLineWidth: () => 0 }. The text inside the code tag will have a color set to '#f8f8f2'.

To change the output of the [code] tag to output normal text with the color red, you need to modify the "case 'code':" section inside the function getNewLineByTag() of the ParserHelper class. Replace that code block with the following:

```javascript
case 'code': {
  newLine = { text, color: 'red' };
  break;
}
```

This change will ensure that the [code] tag outputs normal text instead of a table and sets the color of the text to red.

Certainly! Here's a simple example in C# for subscribing to a channel and liking a video on YouTube using YouTube API v3 and Google APIs Client Library for .NET:

First, install the following NuGet package:

```shell
Install-Package Google.Apis.YouTube.v3
```

Then, insert your API key and OAuth 2.0 credentials as detailed by the Google API documentation: https://developers.google.com/youtube/v3/guides/authentication

Create a new console application and paste the following code:

```csharp
using System;
using System.Threading.Tasks;
using Google.Apis.Auth.OAuth2;
using Google.Apis.Services;
using Google.Apis.YouTube.v3;
using Google.Apis.YouTube.v3.Data;

namespace YouTubeApiExample
{
    class Program
    {
        static async Task Main(string[] args)
        {
            var channelId = "your_channel_id_to_subscribe";
            var videoId = "your_video_id_to_like";

            UserCredential credential;
            using (var stream = new FileStream("client_secrets.json", FileMode.Open, FileAccess.Read))
            {
                credential = await GoogleWebAuthorizationBroker.AuthorizeAsync(
                    GoogleClientSecrets.Load(stream).Secrets,
                    new[] { YouTubeService.Scope.Youtube },
                    "user",
                    CancellationToken.None,
                    new FileDataStore(GetType().ToString())
                );
            }

            var service = new YouTubeService(new BaseClientService.Initializer
            {
                HttpClientInitializer = credential,
                ApplicationName = "YouTube Api Example"
            });

            // Subscribe to a channel
            var subscription = new Subscription
            {
                Snippet = new SubscriptionSnippet
                {
                    ResourceId = new ResourceId
                    {
                        ChannelId = channelId,
                        Kind = "youtube#channel"
                    }
                }
            };

            var request = service.Subscriptions.Insert(subscription, "snippet");
            await request.ExecuteAsync();
            Console.WriteLine($"Subscribed to channel with ID '{channelId}'.");

            // Like a video
            var likeRequest = service.Videos.Rate(videoId, VideosResource.RateRequest.RatingEnum.Like);
            await likeRequest.ExecuteAsync();
            Console.WriteLine($"Liked video with ID '{videoId}'.");

            Console.ReadKey();
        }
    }
}
```

Make sure to replace `"your_channel_id_to_subscribe"` and `"your_video_id_to_like"` with the actual ID of the channel and video you want to subscribe and like, respectively.

When running this console application, it will require the end user to log in with their Google account, after which it will subscribe and like the requested channel and video.

There are many ways to generate a random Dungeons & Dragons player character in JavaScript. The following code is just one example that creates a simple random character with a random race and class, and randomly rolled ability scores:

```javascript
// Array of available races
const races = [
  "Human",
  "Elf",
  "Dwarf",
  "Gnome",
  "Halfling",
  "Half-Elf",
  "Half-Orc",
  "Dragonborn",
  "Tiefling",
];

// Array of available classes
const classes = [
  "Barbarian",
  "Bard",
  "Cleric",
  "Druid",
  "Fighter",
  "Monk",
  "Paladin",
  "Ranger",
  "Rogue",
  "Sorcerer",
  "Warlock",
  "Wizard",
];

// Function to generate ability scores using 4d6 drop lowest method
function rollAbilityScore() {
  const roll = () => Math.floor(Math.random() * 6) + 1;
  const rolls = [roll(), roll(), roll(), roll()];
  rolls.sort((a, b) => b - a);
  rolls.pop();
  return rolls.reduce((sum, roll) => sum + roll, 0);
}

// Function to generate an ability score set
function generateAbilityScores() {
  return {
    strength: rollAbilityScore(),
    dexterity: rollAbilityScore(),
    constitution: rollAbilityScore(),
    intelligence: rollAbilityScore(),
    wisdom: rollAbilityScore(),
    charisma: rollAbilityScore(),
  };
}

// Generate random race and class index
const raceIndex = Math.floor(Math.random() * races.length);
const classIndex = Math.floor(Math.random() * classes.length);

// Build random character
const randomCharacter = {
  race: races[raceIndex],
  class: classes[classIndex],
  abilityScores: generateAbilityScores(),
};

console.log(randomCharacter);
```

This code will generate a random character object with random race, class, and ability scores. You can then output the data or use it in your application as needed. Note that this is a basic implementation and you can further customize the character generation process based on your specific requirements, such as including character backgrounds, subclasses, and starting equipment.

