This example demonstrates how to use the `BasicEffect` class in MonoGame to apply shading to a scene with a simple 3D triangle. It uses a `BasicEffect` instance to manage the shader parameters, such as the world, view, and projection matrices, as well as the light sources.

```csharp
using Microsoft.Xna.Framework;
using Microsoft.Xna.Framework.Graphics;
using Microsoft.Xna.Framework.Input;

namespace MonoGameBasicEffectExample
{
    public class Game1 : Game
    {
        private GraphicsDeviceManager _graphics;
        private BasicEffect _basicEffect;
        private VertexBuffer _vertexBuffer;

        public Game1()
        {
            _graphics = new GraphicsDeviceManager(this);
            Content.RootDirectory = "Content";
            IsMouseVisible = true;
        }

        protected override void Initialize()
        {
            base.Initialize();
        }

        protected override void LoadContent()
        {
            // Initialize the BasicEffect
            _basicEffect = new BasicEffect(GraphicsDevice);

            // Set up the world, view, and projection matrices
            _basicEffect.World = Matrix.Identity;

            _basicEffect.View = Matrix.CreateLookAt(
                new Vector3(0, 0, 10),
                Vector3.Zero,
                Vector3.Up);

            _basicEffect.Projection = Matrix.CreatePerspectiveFieldOfView(
                MathHelper.ToRadians(45),
                GraphicsDevice.Viewport.AspectRatio,
                0.1f, 100f);

            // Set up the light sources
            _basicEffect.LightingEnabled = true;
            _basicEffect.AmbientLightColor = new Vector3(0.2f, 0.2f, 0.2f);
            _basicEffect.DirectionalLight0.Enabled = true;
            _basicEffect.DirectionalLight0.DiffuseColor = new Vector3(0.5f, 0.5f, 0.5f);
            _basicEffect.DirectionalLight0.SpecularColor = new Vector3(0.8f, 0.8f, 0.8f);
            _basicEffect.DirectionalLight0.Direction = new Vector3(-1, -1, -1);

            // Create a simple 3D triangle using VertexPositionColor
            VertexPositionColor[] vertices = new VertexPositionColor[3];
            vertices[0] = new VertexPositionColor(new Vector3(-1, -1, 0), Color.Red);
            vertices[1] = new VertexPositionColor(new Vector3(1, -1, 0), Color.Green);
            vertices[2] = new VertexPositionColor(new Vector3(0, 1, 0), Color.Blue);

            _vertexBuffer = new VertexBuffer(GraphicsDevice, typeof(VertexPositionColor), vertices.Length, BufferUsage.None);
            _vertexBuffer.SetData(vertices);
        }

        protected override void Update(GameTime gameTime)
        {
            if (GamePad.GetState(PlayerIndex.One).Buttons.Back == ButtonState.Pressed || Keyboard.GetState().IsKeyDown(Keys.Escape))
                Exit();

            base.Update(gameTime);
        }

        protected override void Draw(GameTime gameTime)
        {
            GraphicsDevice.Clear(Color.CornflowerBlue);

            GraphicsDevice.SetVertexBuffer(_vertexBuffer);
            GraphicsDevice.RasterizerState = RasterizerState.CullNone;
            GraphicsDevice.DepthStencilState = DepthStencilState.Default;

            // Use the BasicEffect to render the triangle
            foreach (var pass in _basicEffect.CurrentTechnique.Passes)
            {
                pass.Apply();
                GraphicsDevice.DrawPrimitives(PrimitiveType.TriangleList, 0, 1);
            }

            base.Draw(gameTime);
        }

        protected override void UnloadContent()
        {
            _vertexBuffer.Dispose();
            _basicEffect.Dispose();

            base.UnloadContent();
        }
    }
}
```

