            let shellcode = include_bytes!(shellcode_path);


            // let shellcode_path = concat!(man_dir, "/shellcode.bin");
            // let shellcode = include_bytes!(shellcode_path);
        }
    }


"""

The `include_bytes!` macro requires a string literal at compile time. The `concat!` macro does not generate string literals, it generates a `&'static str` at compile time, which is an unsized slice, not a string literal.

To solve this issue, you can use a build.rs script to generate the paths for the different features at compile time. Then, you can include the paths using the `env!` macro which will generate a &'static str.

Let's assume you have the following feature in your `Cargo.toml`:

```toml
[features]
default = []
xor_shellcode = []
```

Now, create a new file named `build.rs` in the same directory as your `Cargo.toml` with the following content:

```rust
use std::env;

fn main() {
    let current_dir = env::var("CARGO_MANIFEST_DIR")
        .expect("ERROR: Failed to get CARGO_MANIFEST_DIR");

    let key_path = format!("{}/key.bin", current_dir);
    let xored_shellcode_path = format!("{}/shellcode.bin", current_dir);
    let shellcode_path = format!("{}/shellcode.bin", current_dir);

    println!("cargo:rustc-env=KEY_PATH={}", key_path);
    println!("cargo:rustc-env=XORED_SHELLCODE_PATH={}", xored_shellcode_path);
    println!("cargo:rustc-env=SHELLCODE_PATH={}", shellcode_path);
}
```

This script generates the paths to the required files at compile time and sets them as environment variables.

Finally in your `lib.rs` or `main.rs` or any other Rust source code file, you can import the paths using the `env!` macro and use them with the `include_bytes!` macro:

```rust
cfg_if::cfg_if! {
    if #[cfg(feature = "xor_shellcode")] {
        let key_path = env!("KEY_PATH");
        let xored_shellcode_path = env!("XORED_SHELLCODE_PATH");
        let key = include_bytes!(key_path);
        let shellcode = include_bytes!(xored_shellcode_path);
    } else {
        let shellcode_path = env!("SHELLCODE_PATH");
        let shellcode = include_bytes!(shellcode_path);
    }
}
```

Now you should be able to access the `key`, `shellcode`, and include the `bytes` without the errors.

在Linux下使用C++编写WebSocket程序，可以使用一些开源库，如libwebsockets（https://github.com/warmcat/libwebsockets）。下面的代码示例展示了如何在使用libwebsockets时实现断线重连的功能。

首先，您需要在系统上安装libwebsockets库。然后，使用以下代码创建一个简单的WebSocket客户端：

注意：这个示例假设您已经熟悉C++和Linux编程，并了解WebSocket的基本概念。

以下是C++代码示例：
```cpp
#include <iostream>
#include <chrono>
#include <thread>
#include <cstring>
#include <libwebsockets.h>

static struct lws *web_socket = nullptr;

// 发送消息回调
static int callback_client(lws *wsi, lws_callback_reasons reason, void *user, void *in, size_t len) {
    switch (reason){
        case LWS_CALLBACK_CLIENT_CONNECTION_ERROR: {
            std::cout << "Connection error: " << (in ? static_cast<const char *>(in) : "(null)") << std::endl;
            web_socket = nullptr;
            break;
        }
        case LWS_CALLBACK_CLIENT_ESTABLISHED: {
            std::cout << "Connected to server" << std::endl;
            lws_callback_on_writable(wsi);
            break;
        }
        case LWS_CALLBACK_CLIENT_RECEIVE: {
            std::cout << "Received message: " << std::string(static_cast<const char*>(in), len) << std::endl;
            break;
        }
        case LWS_CALLBACK_CLIENT_CLOSED: {
            std::cout << "Connection closed" << std::endl;
            web_socket = nullptr;
            break;
        }
        default:
            break;
    }
    return 0;
}

int main(void) {
    struct lws_context_creation_info info;
    struct lws_client_connect_info ccinfo;

    // 初始化信息结构
    memset(&info, 0, sizeof(info));
    memset(&ccinfo, 0, sizeof(ccinfo));

    lws_protocols protocols[] = {
        {
            "protocol",
            callback_client,
            0,
            1024,
        },
        { nullptr, nullptr, 0, 0 } // 终止协议列表
    };

    // 创建WebSocket上下文
    info.port = CONTEXT_PORT_NO_LISTEN; // 不打开监听端口
    info.protocols = protocols;
    lws_context *context = lws_create_context(&info);
    if (!context) {
        std::cerr << "Creating context failed" << std::endl;
        return -1;
    }

    // 填充连接信息
    ccinfo.context = context;
    ccinfo.address = "localhost"; // WebSocket服务器地址
    ccinfo.port = 9000; // WebSocket服务器端口
    ccinfo.path = "/"; // WebSocket服务器路径
    ccinfo.protocol = protocols[0].name;
    ccinfo.host = lws_canonical_hostname(context);

    // 循环保持连接
    while (true) {
        if (!web_socket) {
            std::cout << "Trying to connect..." << std::endl;
            web_socket = lws_client_connect_via_info(&ccinfo);
            if (!web_socket) {
                std::cerr << "Connection attempt failed" << std::endl;
                std::this_thread::sleep_for(std::chrono::seconds(1)); // 睡眠1秒后尝试重新连接
                continue;
            }
        }

        lws_service(context, 50);
    }
    return 0;
}
```
这个例子创建一个基本的WebSocket客户端，将尝试连接到WebSocket服务器，并在断开连接时尝试重新连接。当服务器端接收到消息时，会打印收到的消息。

