using Comet;
using Comet.Handlers;

namespace <%= namespaceName %>
{
    [XamlCompilation(XamlCompilationOptions.Compile)]
    public record CounterState(int Count);

    public class MainPage : ContentPage, IServiceProvider
    {
        IServiceProvider IServiceProvider.GetService(Type serviceType)
        {
            using var serviceScope = new Maui.Controls.HandlerServiceBuilder(new ServiceCollection()).Build().Services.CreateScope();
            return serviceScope.ServiceProvider.GetService(serviceType);
        }
