```cpp
#include <GL/glew.h>
#include <GLFW/glfw3.h>
#include <glm/glm.hpp>
#include <glm/gtc/matrix_transform.hpp>
#include <glm/gtc/type_ptr.hpp>
#include <iostream>

float vertices[] = {
    // body
    0.0f, 0.0f, 0.0f,
    0.1f, 0.2f, 0.0f,
    -0.1f, 0.2f, 0.0f,
    -0.05f, 0.0f, 0.0f,
    -0.1f, -0.2f, 0.0f,
