    $menHaircut = Service::where('name', 'Men Haircut')->first();
    $womenHaircut = Service::where('name', 'Women Haircut')->first();

    $startDate = Carbon::today();
    $endDate = $startDate->copy()->addDays(7);

    for ($date = $startDate; $date->lte($endDate); $date->addDay()) {

        // Exclude Sunday
        if ($date->dayOfWeek != Carbon::SUNDAY) {

            // Men Haircut Slots
            $this->createSlots($date, $menHaircut, '08:00', '20:00', 5, 10, 5, '12:00', '13:00', '15:00', '16:00');

            // Women Haircut Slots
            $this->createSlots($date, $womenHaircut, '08:00', '20:00', 5, 60, 10, '12:00', '13:00', '15:00', '16:00');

            // Saturday Slots
            if ($date->dayOfWeek == Carbon::SATURDAY) {
                $this->createSlots($date, $menHaircut, '10:00', '22:00', 5, 10, 5, '12:00', '13:00', '15:00', '16:00');
            }
        }
    }
}

private function createSlots($date, $service, $startHour, $endHour, $maxClients, $duration, $cleanup, $break1Start, $break1End, $break2Start, $break2End)
{
    $startTime = $date->copy()->setTimeFromTimeString($startHour);
    $endTime = $date->copy()->setTimeFromTimeString($endHour);

    for ($time = $startTime; $time->lt($endTime); $time->addMinutes($duration)->addMinutes($cleanup)) {
        if ($time->between($date->copy()->setTimeFromTimeString($break1Start), $date->copy()->setTimeFromTimeString($break1End))) {
            continue;
        }

        if ($time->between($date->copy()->setTimeFromTimeString($break2Start), $date->copy()->setTimeFromTimeString($break2End))) {
            continue;
        }

        Slot::create([
            'service_id' => $service->id,
            'start_time' => $time->copy(),
            'end_time' => $time->copy()->addMinutes($duration),
            'max_clients' => $maxClients,
        ]);
    }
}
