public float headbobSpeed = 1.5f;   // The speed at which headbob animation happens
```

2. Create a coroutine for the headbob animation:

```csharp
private IEnumerator HeadbobCoroutine()
{
    float timer = 0.0f;

    Vector3 initialPosition = playerCamera.transform.localPosition;

    while (timer < Mathf.PI)
    {
        float moveAmount = Mathf.Sin(timer) * headbobAmount;

        playerCamera.transform.localPosition = initialPosition + new Vector3(0, moveAmount, 0);

        timer += headbobSpeed * Time.deltaTime;

        yield return null;
    }

    // Reset the camera position to its initial position after the headbob
    playerCamera.transform.localPosition = initialPosition;
}
```

