Now, if you want to create collapsible headers in any custom Editor script, you can simply call the `EditorUtilities.DrawCollapsibleHeader` method. This makes it easier to handle multiple headers and keep your code organized.

You can create collapsible headers using custom attributes in Unity. This will allow you to group variables together under a header and make them collapsible in the Inspector window.

First, create a new script called "FoldoutAttribute" and paste the following code:

```csharp
using UnityEngine;
using System;

[AttributeUsage(AttributeTargets.Field, Inherited = true, AllowMultiple = false)]
public class FoldoutAttribute : PropertyAttribute
{
    public readonly string title;
    public readonly bool showLabel;
    public FoldoutAttribute(string title, bool showLabel = true)
    {
        this.title = title;
        this.showLabel = showLabel;
    }
}
```

Next, create another script called "FoldoutDrawer" and paste the following code:

```csharp
using UnityEngine;
using UnityEditor;

[CustomPropertyDrawer(typeof(FoldoutAttribute))]
public class FoldoutDrawer : PropertyDrawer
{
    public override void OnGUI(Rect position, SerializedProperty property, GUIContent label)
    {
        FoldoutAttribute foldoutAttribute = attribute as FoldoutAttribute;
        bool foldout = EditorPrefs.GetBool(foldoutAttribute.title, false);

        position.height = EditorGUIUtility.singleLineHeight;
        foldout = EditorGUI.Foldout(position, foldout, foldoutAttribute.title, true);
        label.text = foldoutAttribute.showLabel ? label.text : "";

        if (foldout)
        {
            EditorGUI.indentLevel++;
            position.y += EditorGUIUtility.singleLineHeight + EditorGUIUtility.standardVerticalSpacing;
            EditorGUI.PropertyField(position, property, label, property.isExpanded);
            EditorGUI.indentLevel--;
        }

        EditorPrefs.SetBool(foldoutAttribute.title, foldout);
    }

    public override float GetPropertyHeight(SerializedProperty property, GUIContent label)
    {
        FoldoutAttribute foldoutAttribute = attribute as FoldoutAttribute;
        bool foldout = EditorPrefs.GetBool(foldoutAttribute.title, false);

        return foldout ? EditorGUI.GetPropertyHeight(property) + EditorGUIUtility.singleLineHeight + EditorGUIUtility.standardVerticalSpacing : EditorGUIUtility.singleLineHeight;
    }
}
```

