    document.body.appendChild(t);

    var a = document.getElementsByClassName('adsbox')[0];

    if (a.offsetHeight === 0 || a.clientHeight === 0) {
      e = true;
    }

    var d;

    if ((d = window.getComputedStyle(a, null))) {
      if (d.getPropertyValue('display') === 'none' || d.getPropertyValue('visibility') === 'hidden') {
        e = true;
