from flask import Flask, render_template, request, jsonify
import cv2
import numpy as np

app = Flask(__name__)

ASCII_CHARS = ["@", "#", "S", "%", "?", "*", "+", ";", ":", ",", "."]

def video_to_frames(filename):
    video = cv2.VideoCapture(filename)
    frames = []

    while True:
        ret, frame = video.read()
        if not ret:
            break

        gray_frame = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
        frames.append(gray_frame)

    video.release()
    return frames

def pixel_to_ascii(value):
    return ASCII_CHARS[int(value / 256 * len(ASCII_CHARS))]

def frame_to_ascii(frame, width):
    height, w = frame.shape
    h = int(width / w * height)
    resized_frame = cv2.resize(frame, (width, h), interpolation=cv2.INTER_AREA)
    ascii_frame = np.vectorize(pixel_to_ascii)(resized_frame)
    return "\n".join("".join(row) for row in ascii_frame)

@app.route("/")
def index():
    return render_template("index.html")

