def convert():
    video_file = request.files["video"]
    video_file.save("input_video.mp4")

    frames = video_to_frames("input_video.mp4")
    width = int(request.form["width"])
    ascii_frames = [frame_to_ascii(frame, width) for frame in frames]

    return jsonify(ascii_frames)

