const snyk = require('snyk');

async function checkPackage(packageName, packageVersion) {
  try {
    const vulnResults = await snyk.test(`${packageName}@${packageVersion}`);
    if (vulnResults.vulnerabilities.length > 0) {
      console.log(`Vulnerabilities found in ${packageName}@${packageVersion}`);
      console.log(vulnResults.vulnerabilities);
    } else {
      console.log(`No vulnerabilities found in ${packageName}@${packageVersion}`);
    }

    const compatResults = await snyk.test(`${packageName}@${packageVersion}`, { dev: true });
    if (compatResults.package.dependencyCheckResults.incompatibilities.length > 0) {
      console.log(`Compatibility issues found with ${packageName}@${packageVersion}`);
      console.log(compatResults.package.dependencyCheckResults.incompatibilities);
    } else {
      console.log(`No compatibility issues found with ${packageName}@${packageVersion}`);
    }
  } catch (error) {
    console.error(error);
  }
}

