                "Yearly" -> (it.second.time - firstYearStartDate.time) / (365 * 24 * 60 * 60 * 1000) + 1
                else -> 0
            }
        }, { it.first })
        .forEach { weekNumber, values ->
            values.sum().let { expenseSum ->
                val weekLabel = when (timeFrame) {
                    "Weekly" -> "Week ${weekNumber + 2}"
                    "Monthly" -> "Month ${weekNumber + 1}"
                    "Yearly" -> "Year ${weekNumber + 1}"
                    else -> ""
                }
                expensesMap[weekLabel] = expensesMap.getOrDefault(weekLabel, 0f) + expenseSum
            }
        }

        chartEntries.value =
            entriesOf(*expensesMap.entries.mapIndexed { index, (_, expense) -> index.toFloat() to expense }
                .toTypedArray())
    }
}
