class Solution {
    public int maxFrequency(int[] nums, int k) {
        int ans = 0;

        int max = 0;
        for(int i : nums) max = Math.max(max, i);
        int[] map = new int[max+1];
        for(int i : nums) map[i]++;

        int j = 0;
        int prev = -1;
        int req = 0;
        int count = 0;
        for(int i = 0; i < map.length;i++){
            if (map[i] == 0) continue;

            req += count*(i-prev);
            while(req - k > 0){
                if (map[j] == 0) {
                    j++;
                    continue;
                }
                int surplus = req - k;
                int cost = (i-j);
                int n = map[j];
                if (cost * n <= surplus){
                    req -= cost*n;
                    count-= n;
                    map[j] = 0;
                } else{
                    int reduceBy = Math.min((surplus/cost)+1, n);
                    req -= cost*(reduceBy);
                    map[j] -= reduceBy;
                    count-=reduceBy;
                }
            }

            prev = i;
            count += map[i];
            ans = Math.max(ans, count);
        }

        return ans;
    }
}

