function createCanvasFromElement(element) {
  let canvas = document.createElement('canvas');
  let ctx = canvas.getContext('2d');

  // Set canvas size to match the element's size
  canvas.width = element.offsetWidth;
  canvas.height = element.offsetHeight;

  // Draw the element's background image
  let bgImage = new Image();
  bgImage.src = element.querySelector('.text-div img').src;
  ctx.drawImage(bgImage, 0, 0, canvas.width, canvas.height);

  // Draw the element's text
  let textElem = element.querySelector('.post-data-preview');
  let textStyle = window.getComputedStyle(textElem);
  let lineHeight = parseFloat(textStyle.lineHeight);
  ctx.font = textStyle.fontSize + ' ' + textStyle.fontFamily;
  ctx.fillStyle = textStyle.color;

  // Split text into lines and draw accordingly
  let lines = textElem.textContent.split('\n');
  let x = parseInt(textStyle.paddingLeft);
  let y = canvas.height - parseInt(textStyle.marginBottom);

  for (let i = 0; i < lines.length; i++) {
    ctx.fillText(lines[i].trim(), x, y);
    y += lineHeight;
  }

  return canvas;
}

