To scan local drive and store local directory structure metadata into sqlite, you can use the following C++ code using the boost::filesystem library and the sqlite3 library. This code demonstrates basic operations of adding and removing files, directories, getting file size and directory size, and removing files under a directory.
Make sure you have the following dependencies installed:

1. Boost Filesystem Library: https://www.boost.org/doc/libs/1_77_0/libs/filesystem/doc/index.htm
2. SQLite3 Library: https://www.sqlite.org/download.html

```cpp
#include <iostream>
#include <boost/filesystem.hpp>
#include <sqlite3.h>

class LocalDriveScanner {
  private:
    sqlite3 *db;

  public:
    LocalDriveScanner() {
      int rc = sqlite3_open("file_metadata.db", &db);
      if (rc) {
        std::cerr << "Cannot open database" << std::endl;
        exit(1);
      }

      // Create the table for storing file metadata
      char *errorMessage = nullptr;
      rc = sqlite3_exec(db,
                        "CREATE TABLE IF NOT EXISTS file_metadata (id INTEGER "
                        "PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, "
                        "path TEXT NOT NULL, size INTEGER NOT NULL, type TEXT NOT NULL);",
                        NULL, 0, &errorMessage);

      if (rc != SQLITE_OK) {
        std::cerr << "Cannot create table: " << errorMessage << std::endl;
        exit(1);
      }
    }

    ~LocalDriveScanner()
    {
      sqlite3_close(db);
    }

    void add_directory(const std::string &path) {
      boost::filesystem::path p(path);

      if (!boost::filesystem::exists(p) || !boost::filesystem::is_directory(p)) {
        std::cerr << "Invalid directory path" << std::endl;
        return;
      }

      int64_t directory_size = 0;
      for (boost::filesystem::recursive_directory_iterator itr(p);
           itr != boost::filesystem::recursive_directory_iterator(); ++itr) {
        if (boost::filesystem::is_regular_file(itr->path())) {
          int64_t file_size = boost::filesystem::file_size(itr->path());
          directory_size += file_size;
          add_file_to_metadata(itr->path().filename().string(),
                               itr->path().string(), file_size);
        }
      }

      add_file_to_metadata(p.filename().string(), p.string(), directory_size,
                           "directory");
    }

    void add_file(const std::string &filepath)
    {
      boost::filesystem::path p(filepath);

      if (!boost::filesystem::exists(p) || !boost::filesystem::is_regular_file(p)) {
        std::cerr << "Invalid file path" << std::endl;
        return;
      }

      int64_t file_size = boost::filesystem::file_size(p);
      add_file_to_metadata(p.filename().string(), p.string(), file_size,
                            "file");
    }

   // Functions for removing files, directories, updating file size, etc.
