  private:
    static int callback(void *NotUsed, int argc, char **argv, char **azColName) {
      for (int i = 0; i < argc; i++) {
        std::cout << azColName[i] << ": " << (argv[i] ? argv[i] : "NULL") << std::endl;
      }
      return 0;
    }

    void add_file_to_metadata(const std::string &name, const std::string &path,
                              int64_t size, const std::string &type = "file") {
      std::string sql =
          "INSERT INTO file_metadata (name, path, size, type) VALUES ('" + name +
          "', '" + path + "', " + std::to_string(size) + ", '" + type + "');";
      execute_sql(sql);
    }

    void execute_sql(const std::string &sql) {
      char *errorMessage = nullptr;
      int rc = sqlite3_exec(db, sql.c_str(), callback, 0, &errorMessage);
      if (rc != SQLITE_OK) {
        std::cerr << "SQL error: " << errorMessage << std::endl;
      } else {
        std::cout << "Operation succeeded" << std::endl;
      }
    }
};

