To store a local directory structure in a SQLite database using C++, you can use the "sqlite3" C/C++ API to interact with SQLite. First, you have to design your database schema in a way that can represent files, directories, and their size.

You can create the following table to store your directory structure:

1. `fs_entry`: To store files and directories, with columns:
    - `id`: The unique identifier of the file or directory.
    - `parent_id`: The unique identifier of the parent directory.
    - `name`: The name of the file or directory.
    - `type`: The type of entry: 'file' or 'directory'.
    - `size`: The size of the file or directory.

Here is a step-by-step process to implement the stated functionality:

1. Create an SQLite database and table:
```cpp
#include <iostream>
#include <sqlite3.h>

static int callback(void* not_used, int argc, char** argv, char** col_name) {
  for (int i = 0; i < argc; i++) {
    printf("%s = %s\n", col_name[i], argv[i] ? argv[i] : "NULL");
  }
  printf("\n");
  return 0;
}

int main() {
  sqlite3 *db;
  char *error_message = 0;

  sqlite3_open("directory_structure.db", &db);

  std::string sql = "CREATE TABLE IF NOT EXISTS fs_entry ("\
                    "id INTEGER PRIMARY KEY AUTOINCREMENT,"\
                    "parent_id INTEGER,"\
                    "name TEXT NOT NULL,"\
                    "type TEXT NOT NULL,"\
                    "size INTEGER,"\
                    "FOREIGN KEY (parent_id) REFERENCES fs_entry (id)"\
                    ");";

  int rc = sqlite3_exec(db, sql.c_str(), callback, 0, &error_message);

  if (rc != SQLITE_OK) {
    fprintf(stderr, "SQL error: %s\n", error_message);
    sqlite3_free(error_message);
  }

  sqlite3_close(db);

  return 0;
}
```

2. Create functions for adding and removing files and directories, getting size of files and directories:
```cpp
#include <iostream>
#include <sstream>
#include <sqlite3.h>
#include <string>

class FileSystem {
  private:
    sqlite3 *db;

  public:
    FileSystem() {
      sqlite3_open("directory_structure.db", &db);
    }

    ~FileSystem() {
      sqlite3_close(db);
    }

    // Inserts a new record into the fs_entry table.
    int insert_fs_entry(int parent_id, const std::string& name, const std::string& entry_type, int size) {
      std::ostringstream sql;
      char* error_message = 0;

      sql << "INSERT INTO fs_entry (parent_id, name, type, size) VALUES "
          << "(" << parent_id << ", '" << name << "', '" << entry_type
          << "', " << size << ");";

      int rc = sqlite3_exec(db, sql.str().c_str(), 0, 0, &error_message);

      if (rc != SQLITE_OK) {
        sqlite3_free(error_message);
        return -1;
      }

      return sqlite3_last_insert_rowid(db);
    }

    // Removes a record from the fs_entry table.
    void remove_fs_entry(int id) {
      std::ostringstream sql;
      char* error_message = 0;

      sql << "DELETE FROM fs_entry WHERE id = " << id << ";";

      sqlite3_exec(db, sql.str().c_str(), 0, 0, &error_message);
      sqlite3_free(error_message);
    }

    // Adds a file.
    void add_file(int parent_id, const std::string& file_name, int size) {
      insert_fs_entry(parent_id, file_name, "file", size);
    }

    // Removes a file.
    void remove_file(int id) {
      remove_fs_entry(id);
    }

    // Adds a directory.
    int add_directory(int parent_id, const std::string& directory_name) {
      return insert_fs_entry(parent_id, directory_name, "directory", 0);
