```python
from flask import Flask, render_template
from flask_socketio import SocketIO, emit
import itertools

app = Flask(__name__)
app.config['SECRET_KEY'] = 'secret_key'
socketio = SocketIO(app, cors_allowed_origins="*")

board = [None] * 9
players = itertools.cycle(['X', 'O'])
current_player = next(players)
connections = 0

def winning_move(board, move):
    winning_combinations = [
        [0, 1, 2], [3, 4, 5], [6, 7, 8],  # horizontal
        [0, 3, 6], [1, 4, 7], [2, 5, 8],  # vertical
        [0, 4, 8], [2, 4, 6]  # diagonal
    ]

    for combo in winning_combinations:
        if all(board[i] == move for i in combo):
            return True

    return False

def is_draw(board):
    return all(cell is not None for cell in board)

@app.route("/")
def index():
    return render_template('index.html')

@socketio.on('connect')
def connect():
    global connections, current_player
    connections += 1
    if connections == 1 or connections == 2:
        emit('player', current_player)
        current_player = next(players)

@socketio.on('make_move')
def make_move(data):
    global current_player, board
    board[data['index']] = data['player']
    emit('move_made', data, broadcast=True)

    if winning_move(board, data['player']):
        emit('game_over', data['player'], broadcast=True)
        board = [None] * 9
        connections = 0
    elif is_draw(board):
        emit('game_over', None, broadcast=True)
        board = [None] * 9
        connections = 0
    else:
        current_player = next(players)

if __name__ == '__main__':
    socketio.run(app, debug=True)
```

