    for (int k = 0; k < sizeof(MeanQueryGenTime) / sizeof(MeanQueryGenTime[0]); k++) {
        for (int l = 0; l < sizeof(MeanUpdateArrivalTime) / sizeof(MeanUpdateArrivalTime[0]); l++) {

            // Initialize cache
            init_cache();

            // Generate update arrival process
            create("update_process");
            hold(100); // remove cold state
            generate_update(MeanUpdateArrivalTime[l]);

            // Generate queries for each client
            for (i = 0; i < NUM_CLIENTS; i++) {
                create("client");
                hold(expntl(MeanQueryGenTime[k]));
                generate_query(i, MeanQueryGenTime[k]);
            }

            // Run simulation
            csim(); // run the simulation with the specified processes

            // Collect results and output graphs for cache hit ratio and query delay
            // ...
        }
    }

    // End simulation
    csim_end();
}
