Here's some example code for creating a simple program that does the following:

1. Create a SQLite database.
2. Create a table for storing the directory structure.
3. Scan a given directory (in this case, the C drive) and store metadata in the SQLite database.
4. Query and display the contents of the table.

```cpp
#include <iostream>
#include <string>
#include <filesystem>
#include <windows.h>
#include "sqlite3.h"

using namespace std;
namespace fs = std::filesystem;

// Function to execute the query
static int callback(void *NotUsed, int argc, char **argv, char **azColName) {
    for (int i = 0; i < argc; i++) {
        cout << azColName[i] << " = " << (argv[i] ? argv[i] : "NULL") << '\n';
    }

    cout << '\n';
    return 0;
}

// Function to insert the file or directory info into the database
void insert_data(sqlite3 *db, int id, const string &name, int parent_id, int level, bool is_dir, uintmax_t size) {
    char *zErrMsg = 0;
    string sql = "INSERT INTO files_or_dirs (id, name, parent_id, level, is_dir, size) VALUES (" +
                  to_string(id) + ", '" + name + "', " + to_string(parent_id) + ", " + to_string(level) + ", " +
                  to_string(is_dir) + ", " + to_string(size) + ");";

    if (sqlite3_exec(db, sql.c_str(), callback, 0, &zErrMsg) != SQLITE_OK) {
        cout << "SQL error: " << zErrMsg << '\n';
        sqlite3_free(zErrMsg);
    }
}

// Function to recursively scan the directory and store info in the database
int scan_directory(const string &path, sqlite3 *db, int parent_id, int level) {
    static int id = 0;

    try {
        for (const auto &entry : fs::directory_iterator(path)) {
            id++;
            uintmax_t size = 0;
            bool is_dir = false;

            if (entry.is_regular_file()) {
                size = entry.file_size();
            } else if (entry.is_directory()) {
                is_dir = true;
                size = scan_directory(entry.path().string(), db, id, level + 1);
            }

            insert_data(db, id, entry.path().filename().string(), parent_id, level, is_dir, size);
        }
    } catch (...) {
        cerr << "Error scanning directory: " << path << '\n';
    }

    return id;
}

int main() {
    sqlite3 *db = nullptr;
    sqlite3_open("files_and_dirs.db", &db);

    string sql = "CREATE TABLE files_or_dirs ("
                 "id         INTEGER PRIMARY KEY,"
                 "name       TEXT NOT NULL,"
                 "parent_id  INTEGER,"
                 "level      INTEGER NOT NULL,"
                 "is_dir     BOOLEAN NOT NULL,"
                 "size       INTEGER NOT NULL);";

    if (sqlite3_exec(db, sql.c_str(), callback, 0, nullptr) != SQLITE_OK) {
        cout << "Cannot create table." << endl;
        sqlite3_close(db);
        return 1;
    }

    scan_directory("C:/", db, 0, 0);

    // Display the results
    string query = "SELECT * FROM files_or_dirs;";
    char *zErrMsg = 0;

    if (sqlite3_exec(db, query.c_str(), callback, 0, &zErrMsg) != SQLITE_OK) {
        cout << "SQL error: " << zErrMsg << endl;
        sqlite3_free(zErrMsg);
    } else {
        cout << "Query executed successfully." << endl;
    }

    sqlite3_close(db);
    return 0;
}
```

