#include <iostream>
#include <vector>
#include <dirent.h>

using namespace std;

vector<string> get_folders_in_directory(const string& path) {
    vector<string> folders;
    DIR* dir = opendir(path.c_str());
    struct dirent* ent;

    // Check if directory exists
    if (dir == nullptr) {
        cerr << "Error: Directory \"" << path << "\" not found." << endl;
        return folders;
    }

    // Loop through directory entries
    while ((ent = readdir(dir)) != nullptr) {
        // Check if entry is directory and not "." or ".."
        if ((ent->d_type == DT_DIR) && (string(ent->d_name) != ".") && (string(ent->d_name) != "..")) {
            // Add entry to vector
            folders.push_back(string(ent->d_name));
        }
    }

    closedir(dir);
    return folders;
}
