func splitPolyline(polyline: MKPolyline) -> [MKPolyline] {
    var result: [MKPolyline] = []

    guard polyline.pointCount > 2 else {
        result.append(polyline)
        return result
    }

    var coordinates = polyline.coordinates

    for i in 0 ..< polyline.pointCount - 1 {
        let startCoordinate = coordinates[i]
        let endCoordinate = coordinates[i + 1]
        let segment = [startCoordinate, endCoordinate]
        var intersects = false

        for j in i + 2 ..< polyline.pointCount - 1 {
            let otherStartCoordinate = coordinates[j]
            let otherEndCoordinate = coordinates[j + 1]
            let otherSegment = [otherStartCoordinate, otherEndCoordinate]
            if let intersection = MKGeometry.lineSegmentIntersection(segment, otherSegment),
                intersection != startCoordinate && intersection != endCoordinate {
                intersects = true
                let start = CLLocationCoordinate2D(latitude: startCoordinate.latitude, longitude: startCoordinate.longitude)
                let intersection = CLLocationCoordinate2D(latitude: intersection.latitude, longitude: intersection.longitude)
                result.append(MKPolyline(coordinates: [start, intersection], count: 2))
                coordinates.remove(at: j)
                coordinates.insert(intersection, at: j)
                break
            }
        }

        if !intersects {
            result.append(MKPolyline(coordinates: segment, count: 2))
        }
    }

    return result
}
```

Этот код разбивает каждую линию на отрезки в точках пересечения и возвращает массив новых линий без пересечений.

