Create functions to get file size and directory size:

```cpp
int64_t get_file_size(const std::string& db_path, int file_id)
{
    int64_t size = 0;
    sqlite3* db;

    if (sqlite3_open(db_path.c_str(), &db))
    {
        std::cerr << "Cannot open database: " << sqlite3_errmsg(db) << std::endl;
        return -1;
    }

    std::string query_sql = "SELECT size FROM files WHERE id = ?;";
    sqlite3_stmt* stmt;

    sqlite3_prepare_v2(db, query_sql.c_str(), query_sql.size(), &stmt, nullptr);
    sqlite3_bind_int(stmt, 1, file_id);

    if (sqlite3_step(stmt) == SQLITE_ROW)
    {
        size = sqlite3_column_int64(stmt, 0);
    }

    sqlite3_finalize(stmt);
    sqlite3_close(db);
    return size;
}

int get_directory_size_callback(void* data, int argc, char** argv, char** azColName)
{
    int64_t* total_size = static_cast<int64_t*>(data);
    *total_size += strtoll(argv[0], nullptr, 10);
    return 0;
}

int64_t get_directory_size(const std::string& db_path, int dir_id)
{
    int64_t total_size = 0;
    sqlite3* db;

    if (sqlite3_open(db_path.c_str(), &db))
    {
        std::cerr << "Cannot open database: " << sqlite3_errmsg(db) << std::endl;
        return -1;
    }

    std::string query_sql = "WITH RECURSIVE subdir(id) AS ("
                            "SELECT id FROM directories WHERE id = ? "
                            "UNION ALL "
                            "SELECT d.id FROM directories AS d JOIN subdir ON d.parent_directory = subdir.id) "
                            "SELECT SUM(size) FROM files WHERE parent_directory IN subdir;";
    sqlite3_stmt* stmt;

    sqlite3_prepare_v2(db, query_sql.c_str(), -1, &stmt, nullptr);
    sqlite3_bind_int(stmt, 1, dir_id);

    if (sqlite3_step(stmt) == SQLITE_ROW)
    {
        total_size = sqlite3_column_int64(stmt, 0);
    }

    sqlite3_finalize(stmt);
    sqlite3_close(db);
    return total_size;
}
