To automatically handle parent directory IDs, we can add an extra function to get the parent directory ID by its name from the SQLite database. This function retrieves the parent directory ID based on its name and its parent directory ID (to avoid confusion between directories with the same name but in different locations).

Add a new function called `get_directory_id`:

```cpp
int get_directory_id(const std::string& db_path, const std::string& dir_name, int parent_directory)
{
    int id = -1;
    sqlite3* db;

    if (sqlite3_open(db_path.c_str(), &db))
    {
        std::cerr << "Cannot open database: " << sqlite3_errmsg(db) << std::endl;
        return id;
    }

    std::string query_sql = "SELECT id FROM directories WHERE name = ? AND parent_directory = ?;";
    sqlite3_stmt* stmt;

    sqlite3_prepare_v2(db, query_sql.c_str(), -1, &stmt, nullptr);
    sqlite3_bind_text(stmt, 1, dir_name.c_str(), dir_name.size(), SQLITE_TRANSIENT);
    sqlite3_bind_int(stmt, 2, parent_directory);

    if (sqlite3_step(stmt) == SQLITE_ROW)
    {
        id = sqlite3_column_int(stmt, 0);
    }

    sqlite3_finalize(stmt);
    sqlite3_close(db);
    return id;
}
```

