Create a function to traverse directories and store their structure in the SQLite database:

```cpp
void store_directory_structure(const std::string& db_path, const std::filesystem::path& dir_path, int parent_id)
{
    for (const auto& entry : std::filesystem::directory_iterator{ dir_path })
    {
        if (entry.is_directory())
        {
            std::string dir_name = entry.path().filename().string();
            add_directory(db_path, dir_name, parent_id);
            int new_parent_id = get_directory_id(db_path, dir_name, parent_id);
            store_directory_structure(db_path, entry.path(), new_parent_id);
        }
