To automatically handle file and directory IDs and ensure that deleting a directory also deletes all its subdirectories and files, we can use some modifications to the existing code.

First, let's add a function to delete a directory and its contents recursively:

```cpp
void delete_directory_recursively(const std::string& db_path, int dir_id)
{
    // Delete all subdirectories recursively
    std::string subdirectories_sql = "SELECT id FROM directories WHERE parent_directory = ?;";
    sqlite3* db;
    if (sqlite3_open(db_path.c_str(), &db))
    {
        std::cerr << "Cannot open database: " << sqlite3_errmsg(db) << std::endl;
        return;
    }
    sqlite3_stmt* stmt;

    sqlite3_prepare_v2(db, subdirectories_sql.c_str(), -1, &stmt, nullptr);
    sqlite3_bind_int(stmt, 1, dir_id);

    while (sqlite3_step(stmt) == SQLITE_ROW)
    {
        int subdir_id = sqlite3_column_int(stmt, 0);
        delete_directory_recursively(db_path, subdir_id);
    }

    sqlite3_finalize(stmt);

    // Remove all files in the directory
    std::string delete_files_sql = "DELETE FROM files WHERE parent_directory = ?;";
    sqlite3_prepare_v2(db, delete_files_sql.c_str(), delete_files_sql.size(), &stmt, nullptr);
    sqlite3_bind_int(stmt, 1, dir_id);
    sqlite3_step(stmt);

    sqlite3_finalize(stmt);

    // Remove the directory
    std::string delete_dir_sql = "DELETE FROM directories WHERE id = ?;";
    sqlite3_prepare_v2(db, delete_dir_sql.c_str(), delete_dir_sql.size(), &stmt, nullptr);
    sqlite3_bind_int(stmt, 1, dir_id);
    sqlite3_step(stmt);

    sqlite3_finalize(stmt);
    sqlite3_close(db);
}
```

Now, we'll modify the `store_directory_structure` and `monitor_directory` functions to work incrementally:

1. Compare the new file structure received from the monitoring process with the existing file structure in the database.
2. Update the database with the changes.

Here's the improved `store_directory_structure` function:

```cpp
void store_directory_structure_incrementally(const std::string& db_path, const std::filesystem::path& dir_path, int parent_id)
{
    for (const auto& entry : std::filesystem::directory_iterator{ dir_path })
    {
        std::string name = entry.path().filename().string();
        int existing_dir_id = get_directory_id(db_path, name, parent_id);

        if (entry.is_directory())
        {
            if (existing_dir_id == -1)
            {
                add_directory(db_path, name, parent_id);
                existing_dir_id = get_directory_id(db_path, name, parent_id);
            }

            store_directory_structure_incrementally(db_path, entry.path(), existing_dir_id);
        }
        else
        {
            std::string file_name = entry.path().filename().string();

            // Check if the file already exists in the database
            bool file_exists = false;
            std::string check_query = "SELECT 1 FROM files WHERE name = ? AND parent_directory = ?;";
            sqlite3* db;
            sqlite3_stmt* stmt;

            if (sqlite3_open(db_path.c_str(), &db))
            {
                std::cerr << "Cannot open database: " << sqlite3_errmsg(db) << std::endl;
                return;
            }

            sqlite3_prepare_v2(db, check_query.c_str(), -1, &stmt, nullptr);
            sqlite3_bind_text(stmt, 1, name.c_str(), name.size(), SQLITE_TRANSIENT);
            sqlite3_bind_int(stmt, 2, parent_id);

            if (sqlite3_step(stmt) == SQLITE_ROW)
            {
                file_exists = true;
            }

            sqlite3_finalize(stmt);
            sqlite3_close(db);

            if (!file_exists)
            {
                add_file(db_path, file_name, parent_id);
            }
        }
    }
}
```

