#include <stdio.h>
#include <stdlib.h>
#include "csim.h"

// Cache struct
typedef struct {
    int id;
    int timestamp;
} CacheEntry;

void add_random_data_item_to_cache(CsSet *cache, int next_cache_id);

CS_EVENT_ROUTINE(query_event) {
    CsSet *cache = (CsSet *)user_data;
    int next_cache_id = rand() % 500;
    if (cs_set_is_empty(cache)) {
        printf("Cache is empty!\n");
        return 0;
    }

    int random_id = rand() % 500;
    CsEntity *data_item = cs_set_remove_nodestroy(cache);
    CacheEntry *entry = (CacheEntry *)data_item->attribute_queue->userdata;
    if (entry->id == random_id) {
        printf("Cache hit!\n");
        // Cache hit; do something
    } else {
        printf("Cache miss!\n");
        // Cache miss; request data from server

        // Replace a random cache entry with new data
        add_random_data_item_to_cache(cache, next_cache_id);
    }
    return 0;
}

void add_random_data_item_to_cache(CsSet *cache, int next_cache_id) {
    // Add a new data_item to cache
    CsEntity *new_data_item = cs_entity_new();
    cs_attribute_add(new_data_item, "cache_entry");
    CacheEntry *new_entry = (CacheEntry *)malloc(sizeof(CacheEntry));
    new_entry->id = next_cache_id;
    new_entry->timestamp = NOW;
    new_data_item->attribute_queue->userdata = (void *)new_entry;
    cs_set_file(cache, new_data_item);
}

int main() {
    cs_init();

    CsEvent *query_event = cs_event_new(query_event);
    int num_clients = 5;
    int cache_size = 100;

    for (int client = 0; client < num_clients; client++) {
        // Initialize cache for each client
        CsSet *cache = cs_set_new(FIFO);

        for (int i = 0; i < cache_size; i++) {
            int next_cache_id = rand() % 500;
            add_random_data_item_to_cache(cache, next_cache_id);
        }

        cs_event_schedule(query_event, rand() % 100, cache);
    }

    cs_start_simulation();
    return 0;
