        Matcher matcher = pattern.matcher(value);

        if (matcher.find()) {
            return new PointCoordinate(Double.parseDouble(matcher.group(2)), Double.parseDouble(matcher.group(1)));
        } else {
            return null;
        }
    }

    @Override
    public String toString() {
        return "(" + lat + "," + lon + ")";
    }
