  const isAssignable = typeChecker2.isTypeAssignableToType(
    classSymbol2.getType(),
    classSymbol1.getType(),
  )

  if (!isAssignable) {
    console.log(`Error: Class ${className} in file 2 is not assignable to class ${className} in file 1.`)
  }
})
```

