// GET endpoint that sends a response to the client and a message over WebSocket
app.get('/my-endpoint', (req, res) => {
  // Send response to client
  res.send('Hello World!');

  // Send message to WebSocket clients
  wss.clients.forEach((client) => {
    if (client.readyState === WebSocket.OPEN) {
      client.send('A client connected to /my-endpoint');
    }
  });
});

// WebSocket connection handling
wss.on('connection', (ws) => {
  console.log('A client connected to WebSocket');

  // Send message to the connected WebSocket client
  ws.send('Welcome to WebSocket server');
});

// Start server
server.listen(3000, () => {
  console.log('Server started on http://localhost:3000');
});
