class Codec {
public:
    // Function to serialize a binary tree into a string
    string serialize(TreeNode* root) 
    {
        if (root == nullptr)
            return "";

        string s;
        queue<TreeNode*> q;

        // Use BFS to traverse the tree and construct the string
        q.push(root);
        while (!q.empty())
        {
            TreeNode* current = q.front();
            q.pop();

            if (current == nullptr)
                s.append("#,");
            else
                s.append(to_string(current->val) + ',');

            if (current != nullptr)
            {
                q.push(current->left);
                q.push(current->right);
            }    
        }

        return s;
    }

    // Function to deserialize a string back into a binary tree
    TreeNode* deserialize(string data) 
    {
        if (data.empty())
            return nullptr;

        stringstream ss(data);
        string str;
        getline(ss, str, ',');

        TreeNode* root = new TreeNode(stoi(str));
        queue<TreeNode*> q;

        // Use BFS to traverse the string and reconstruct the tree
        q.push(root);
        while (!q.empty())
        {
            TreeNode* current = q.front();
            q.pop();

            getline(ss, str, ',');

            if (str == "#")
                current->left = nullptr;
            else
            {
                TreeNode* leftNode = new TreeNode(stoi(str));
                current->left = leftNode;
                q.push(leftNode);
            }

            getline(ss, str, ',');

            if (str == "#")
                current->right = nullptr;
            else
            {
                TreeNode* rightNode = new TreeNode(stoi(str));
                current->right = rightNode;
                q.push(rightNode);
            }
        }

        return root;
    }
