```javascript
let angle = 0;

function setup() {
  createCanvas(600, 400, WEBGL);
}

function draw() {
  background(200);
  rotateX(angle);
  rotateY(angle * 0.3);
  rotateZ(angle * 0.2);
  angle += 0.01;

  // Set colors for the shape
  ambientMaterial(50, 50, 255);

