You can modify the cylinder as a custom 3D shape using `beginShape()` and `endShape()` functions to make it wider at the top than at the bottom. Here's an example:

```javascript
function setup() {
  createCanvas(500, 500, WEBGL);
}

function draw() {
  background(200);
  rotateX(HALF_PI);
  scale(1, -1, 1);
  translate(0, 0, -75);

  // Set the light source
  pointLight(255, 255, 255, 200, 0, 200);

  // Set the material properties
  ambientMaterial(255, 0, 0);
  specularMaterial(200, 0, 0);

  // Draw the base
  push();
  translate(0, 180, 0);
  scale(2, 0.2, 2);
  cylinder(50, 180);
  pop();

  // Draw the wider upper part
  push();
  translate(0, 100, 0);
  scale(2, 1, 2);
  cylinder(100, 1);
  pop();

  // Draw the cup
  drawCup(50, 180, 70);
}

function drawCup(bottomRadius, cupHeight, topRadius) {
  let sides = 32;

  for (let i = 0; i < sides; i++) {
    let startAngle = (TWO_PI / sides) * i;
    let endAngle = (TWO_PI / sides) * (i + 1);

    let x1 = cos(startAngle) * bottomRadius;
    let z1 = sin(startAngle) * bottomRadius;
    let x2 = cos(endAngle) * bottomRadius;
    let z2 = sin(endAngle) * bottomRadius;

    let x3 = cos(startAngle) * topRadius;
    let z3 = sin(startAngle) * topRadius;
    let x4 = cos(endAngle) * topRadius;
    let z4 = sin(endAngle) * topRadius;

    beginShape();

    vertex(x1, 0, z1);
    vertex(x2, 0, z2);
    vertex(x4, -cupHeight, z4);
    vertex(x3, -cupHeight, z3);

    endShape(CLOSE);
  }
}
```

In this code, I've created a separate function, `drawCup()` that takes the bottom radius, cup height, and top radius as input. Then, it draws a custom 3D shape with the specified dimensions using `beginShape()` and `endShape()` functions. This way, you have more control over the cup's shape, and it will appear wider at the top than the bottom.

