const int switchPins[] = {2, 3, 4, 5};
byte sensorData[6];
byte outputData = 0;

void setup() {
  Ethernet.begin(mac, ip);
  server1.begin();
  server2.begin();
  for (int i = 0; i < 6; i++) {
    pinMode(ledPins[i], OUTPUT);
  }
  for (int i = 0; i < 4; i++) {
    pinMode(switchPins[i], INPUT_PULLUP);
  }
}

void loop() {
  receiveSensorData();
  displaySensorData();
  readSwitches();
  sendOutputData();
  delay(100); // Add delay to avoid swamping the network with data
}

void receiveSensorData() {
  EthernetClient client = server1.available();
  if (client) {
    for (int i = 0; i < 6; i++) {
      sensorData[i] = client.read();
    }
  }
}

void displaySensorData() {
  for (int i = 0; i < 6; i++) {
    digitalWrite(ledPins[i], sensorData[i]);
  }
}

void readSwitches() {
  for (int i = 0; i < 4; i++) {
    bitWrite(outputData, i, !digitalRead(switchPins[i]));
  }
}

void sendOutputData() {
  EthernetClient client = server2.available();
  if (client) {
    client.write(outputData);
  }
}
