  const updatedCrops = HarvestedCrops.map((crop: Crop) => {
    if (crop.Decay >= 100) {
      return null;
    }

    return {
      ...crop,
      Decay: crop.Decay + ecoPrices.DecayRate * 6,
    };
  }).filter((crop: Crop) => crop !== null);

