    const combinedData: ReferrerIncomesStatistics = {
      open_link: [],
      registration: [],
      order_pay: [],
      subscription_pay: [],
    };

    results.forEach((result) => {
      if (result) {
        combinedData.open_link.push(...result.data.open_link);
        combinedData.registration.push(...result.data.registration);
        combinedData.order_pay.push(...result.data.order_pay);
        combinedData.subscription_pay.push(...result.data.subscription_pay);
      }
    });

    // Set the combined data in state
    setCombinedData(combinedData);
  });
}, [referralId]);
