3. Create a function to update the cached data item based on the LRU policy.

```c
void update_cache(node *n, int data_item) {
    int min_age_index = 0;

    for (int i = 0; i < CACHE_SIZE; i++) {
        if (n->cache[i] == -1) { // Empty cache slot found
            n->cache[i] = data_item;
            n->cache_age[i] = 1;
            return;
        }

        if (n->cache_age[i] < n->cache_age[min_age_index]) {
            min_age_index = i;
        }
    }

    // Replace the least recently used item in the cache
    n->cache[min_age_index] = data_item;
    n->cache_age[min_age_index] = 1;
}
```

4. Update the `is_item_in_cache` function to increase the age of each item in the cache by 1, except the one found, and reset the age of the found item to 1.

```c
int is_item_in_cache(node *n, int item) {
    int item_found = 0;
    for (int i = 0; i < CACHE_SIZE; i++) {
        if (n->cache[i] == item) {
            n->cache_age[i] = 1;
            item_found = 1;
        } else {
            n->cache_age[i]++;
        }
    }
    return item_found;
}
```

