This is a C program that reads an arithmetic expression written in postfix notation as well as the values of the expression's operands and returns the evaluation value of that expression:

#include <stdio.h>
#include <stdlib.h>
#include "TADs_pilha_fila_aloc_enc.h"

#define MAX_STACK_SIZE 1000

typedef struct {
    double items[MAX_STACK_SIZE];
    int top;
} Stack;

void push(Stack *s, double item) {
    s->items[++(s->top)] = item;
}

double pop(Stack *s) {
    return s->items[(s->top)--];
}

double ler_e_avalia_expressao(char *expressao) {
    Stack s = { .top = -1 };
    char *token = expressao;

    while (*token) {
        if (isdigit(*token)) {
            push(&s, atof(token));
            while (isdigit(*token) || *token == '.') token++;
        } else if (*token == '+' || *token == '-' || *token == '*' || *token == '/') {
            double operand2 = pop(&s);
            double operand1 = pop(&s);
            double result;

            switch (*token) {
                case '+': result = operand1 + operand2; break;
                case '-': result = operand1 - operand2; break;
                case '*': result = operand1 * operand2; break;
                case '/': result = operand1 / operand2; break;
            }

            push(&s, result);
            token++;
        } else {
            token++;
        }
    }

    return pop(&s);
    }

int main() {
    char expressao[1000];

    printf("Insira uma expressao de notacao pos-fixa: ");
    fgets(expressao, 1000, stdin);

    double resultado = ler_e_avalia_expressao(expressao);

    printf("Result = %lf\n", resultado);

    return 0;
}

