            var candles = client.Spot.Market.GetKlines(symbol, Binance.Net.Enums.KlineInterval.OneDay).Data;

            // Calculate moving average
            List<decimal> movingAverage = CalculateMovingAverage(candles, movingAverageLength);

            // Apply trading strategy
            List<string> signals = ApplyTradingStrategy(candles, movingAverage, riskPercentage, riskRewardRatio);

            // Print strategy results
            for (int i = 0; i < candles.Count; i++)
            {
                Console.WriteLine($"{candles[i].CloseTime}, {candles[i].Close}, {movingAverage[i]}, {signals[i]}");
            }
        }

        private static List<decimal> CalculateMovingAverage(List<BinanceKline> candles, int length)
        {
            List<decimal> movingAverage = new List<decimal>();
            decimal sum = 0;

            for (int i = 0; i < candles.Count; i++)
            {
                sum += candles[i].Close;

                if (i >= length)
                {
                    sum -= candles[i - length].Close;
                    movingAverage.Add(sum / length);
                }
                else
                {
                    movingAverage.Add(0);
                }
            }

            return movingAverage;
        }

        private static List<string> ApplyTradingStrategy(List<BinanceKline> candles, List<decimal> movingAverage, decimal riskPercentage, decimal riskRewardRatio)
        {
            List<string> signals = new List<string>();
            bool inPosition = false;
            decimal stopLoss = 0;
            decimal takeProfit = 0;

            for (int i = 0; i < candles.Count; i++)
            {
                if (!inPosition && candles[i].Close > movingAverage[i])
                {
                    signals.Add("Buy");
                    inPosition = true;
                    stopLoss = candles[i].Close * (1 - riskPercentage);
                    takeProfit = candles[i].Close * (1 + riskPercentage * riskRewardRatio);
                }
                else if (inPosition &&
                         (candles[i].Close <= movingAverage[i] || candles[i].Close <= stopLoss || candles[i].Close >= takeProfit))
                {
                    signals.Add("Sell");
                    inPosition = false;
                    stopLoss = 0;
                    takeProfit = 0;
                }
                else
                {
                    signals.Add("Hold");
                }
            }

            return signals;
        }
    }
}
```

Replace `YOUR_API_KEY` and `YOUR_API_SECRET` with your actual API key and secret in the provided code.

