5. Combining Components

Lastly, we combine all these components in a main class that runs the trading algorithm:

```csharp
public class StockAutoTrader
{
    private readonly IDataProvider _dataProvider;
    private readonly ITradingStrategy _tradingStrategy;
    private readonly PerformanceTracker _performanceTracker;
    private readonly IBroker _broker;
    private readonly string _symbol;
    private readonly TimeSpan _tradingInterval;

    public StockAutoTrader(
        IDataProvider dataProvider,
        ITradingStrategy tradingStrategy,
        PerformanceTracker performanceTracker,
        IBroker broker,
        string symbol,
        TimeSpan tradingInterval)
    {
        _dataProvider = dataProvider;
        _tradingStrategy = tradingStrategy;
        _performanceTracker = performanceTracker;
        _broker = broker;
        _symbol = symbol;
        _tradingInterval = tradingInterval;
    }

    public async void StartTrading()
    {
        while (true)
        {
            var stockData = await _dataProvider.GetStockDataAsync(_symbol);
            var decision = _tradingStrategy.Decide(stockData);

            if (decision != TradingDecision.Hold)
            {
                var trade = new Trade(_symbol, decision);
                var success = await _broker.SubmitOrderAsync(trade);

                if (success)
                {
                    _performanceTracker.RecordTrade(trade);
                }
            }

            _performanceTracker.CalculateRisk();

            await Task.Delay(_tradingInterval);
        }
    }
}
