Implement a program in C that uses a binary search tree as a basic data structure for the purpose of transmitting data. Thus, as packets arrive at their destination, they are inserted into a binary search tree, considering the packet identification number as key. This same insertion operation will ensure that duplicate packets cannot be inserted into the tree. Once all the packages are inserted in the tree, to reconstruct the information flow, it is enough to remove the packages from the tree in ascending order according to their keys. Detailed instructions are as follows:

1 - ask the user to enter a message to be
transmitted over the network;

2 - print the message;

3 - fragment the message so that each character represents a packet to be transmitted, remembering that each packet must be associated with an identification number;

4 - for each packet, generate a random integer number between 1 and 10, which will determine the number of times the packet must be replicated;

5 - generate a new sequence of packets in which both the packets of the original message and the replicated packets are scrambled;

6 - print the new packet sequence;

7 - build the binary search tree from the new sequence of packages;

8 - print the tree;

9 - reconstruct the original message from the binary tree of
search.

10 - print the message.

```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>

// Define a binary search tree node
typedef struct Node {
    int key;
    char data;
    struct Node *left;
    struct Node *right;
} Node;

// Function to create and initialize a new node
Node* newNode(int key, char data) {
    Node* temp = (Node*)malloc(sizeof(Node));
    temp->key = key;
    temp->data = data;
    temp->left = NULL;
    temp->right = NULL;
    return temp;
}

// Function to insert a new node to the binary search tree
Node* insert(Node* root, int key, char data) {
    if (root == NULL)
        return newNode(key, data);

    if (key != root->key) {
      if (key < root->key)
          root->left = insert(root->left, key, data);
      else
          root->right = insert(root->right, key, data);
    }

    return root;
}

// Function to do inorder traversal of BST and reconstruct the message
void inorder(Node *root, char* message, int *index) {
    if (root != NULL) {
        inorder(root->left, message, index);
        message[*index] = root->data;
        (*index)++;
        inorder(root->right, message, index);
    }
}

// Function to display the tree in a 2D array
void displayTree(Node *root, int space) {
  if (root == NULL)
    return;

  space += 10;

  displayTree(root->right, space);

  printf("\n");
  for (int i = 10; i < space; i++)
    printf(" ");
  printf("(%d, %c)\n", root->key, root->data);

  displayTree(root->left, space);
}

int main() {
    char message[100], new_packet_sequence[1000];
    int i, j, k, random, total_packets = 0;
    Node *root = NULL;

    printf("Enter a message to be transmitted: ");
    scanf("%[^\n]%*c", message);
    printf("\nOriginal message: %s\n", message);

    srand(time(0));

    // Fragment the message into packets and replicate them
    for (i = 0; i < strlen(message); i++) {
        random = rand() % 10 + 1;

        for (j = 0; j < random; j++) {
          root = insert(root, i+1, message[i]);
        }
        total_packets += random;
    }

    printf("\nRandomized packet sequence: ");

    inorder(root, new_packet_sequence, &total_packets);
    printf("%s\n", new_packet_sequence);

    char reconstructed_message[100];
    int index = 0;

    printf("\nBinary search tree:\n");
    displayTree(root, 0);

    printf("\nReconstructed message: ");
    inorder(root, reconstructed_message, &index);
    reconstructed_message[index] = '\0';
    printf("%s\n", reconstructed_message);

    return 0;
}
```

