    // Game loop variables
    bool quit = false;
    SDL_Event event;

    // Game loop
    while (!quit)
    {
        // Handle events
        while (SDL_PollEvent(&event) != 0)
        {
            if (event.type == SDL_QUIT)
            {
                quit = true;
            }
