#include <iostream>
#include <vector>
#include <set>

int main() {
    std::vector<int> A = {1, 2, 3, 4};
    int N = A.size();
    std::vector<int> result(N, 0);

    for (int i = 0; i < N; ++i) {
        std::set<int> xor_values;
        int curr_xor = 0;

        for (int j = i; j >= 0; --j) {
            curr_xor ^= A[j];
            xor_values.insert(curr_xor);

            // Store the result for the subarray ending at i
            result[i] = xor_values.size();
        }
    }

    // Print the result
    for (int i = 0; i < N; ++i) {
        std::cout << result[i] << (i == (N - 1) ? '\n' : ' ');
    }

    return 0;
}
