import java.util.HashMap;
import java.util.Map;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

public class PreAuthPayment {

    private final String API_KEY = "your_api_key";
    private final String API_SECRET = "your_api_secret";

    public void createPreAuthPayment(String payKey, String amount) {
        String endpoint = "https://api.paypal.com/nvp";

        // Construct request parameters
        Map<String, String> params = new HashMap<>();
        params.put("METHOD", "Pay");
        params.put("ACTION", "CREATE");
        params.put("PAYMENTREQUEST_0_PAYMENTACTION", "Authorization");
        params.put("PAYMENTREQUEST_0_AMT", amount);
        params.put("PAYMENTREQUEST_0_CURRENCYCODE", "USD");
        params.put("RETURNURL", "https://yourwebsite.com/success");
        params.put("CANCELURL", "https://yourwebsite.com/cancel");
        params.put("PAYMENTREQUEST_0_ITEMAMT", amount);
        params.put("L_PAYMENTREQUEST_0_NAME0", "Your Product");
        params.put("L_PAYMENTREQUEST_0_AMT0", amount);
        params.put("L_PAYMENTREQUEST_0_QTY0", "1");
        params.put("PAYKEY", payKey);

        // Generate signature
        String signature = generateSignature(params);

        // Add signature to request parameters
        params.put("SIGNATURE", signature);
        params.put("VERSION", "204");

        // Send request to PayPal API
        String response = sendRequest(endpoint, params);
        System.out.println(response);
    }

    private String generateSignature(Map<String, String> params) {
        StringBuilder sb = new StringBuilder();
        sb.append("METHOD=" + params.get("METHOD") + "&");
        sb.append("VERSION=" + params.get("VERSION") + "&");
        sb.append("PWD=" + API_SECRET + "&");
        sb.append("USER=" + API_KEY + "&");
        sb.append("SIGNATURE=" + API_SECRET + "&");

        // Add request parameters to signature
        for (Map.Entry<String, String> entry : params.entrySet()) {
            sb.append(entry.getKey() + "=" + entry.getValue() + "&");
        }
        // Remove trailing '&' character
        sb.setLength(sb.length() - 1);

        // Generate SHA-256 hash of signature
        MessageDigest md = null;
        try {
            md = MessageDigest.getInstance("SHA-256");
        } catch (NoSuchAlgorithmException e) {
            e.printStackTrace();
        }
        byte[] hash = md.digest(sb.toString().getBytes());
        String signature = bytesToHex(hash);
        return signature;
    }

    private String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }

    private String sendRequest(String endpoint, Map<String, String> params) {
        // Implement your HTTP request code here (e.g. using HttpURLConnection)
        return "";
    }
}
```

