                sendto(udp_sockfd, buffer, data_read, 0,
                       (sockaddr *)&client_address, client_addrlength);
            } else if (events[i].events & EPOLLIN) {
                char buffer[BUFFER_SIZE];
                memset(buffer, '\0', BUFFER_SIZE);
                int data_read = recv(sockfd, buffer, BUFFER_SIZE, 0);
                if (data_read < 0) {
                    if (errno == EAGAIN || errno == EWOULDBLOCK) {
                        std::cout << "Read later" << std::endl;
                        continue;
                    }

                    close(sockfd);
                    clients_list.remove(sockfd);
                    std::cout << "A TCP client left" << std::endl;
                } else if (data_read == 0) {
                    close(sockfd);
                    clients_list.remove(sockfd);
                    std::cout << "A TCP client left" << std::endl;
                } else {
                    // Handle the data
                    std::cout << "Received TCP data: " << buffer << std::endl;

                    // Send the same data back to the client
                    send(sockfd, buffer, data_read, 0);
                }
            } else {
                std::cout << "Unhandled epoll event" << std::endl;
            }
        }
    }

    close(tcp_listenfd); // Close the TCP socket
    close(udp_sockfd);   // Close the UDP socket
    return 0;
}
```

This example demonstrates how to create a high-concurrent server using edge-triggered epoll for both TCP and UDP connections.

