```

6. In `js/app.js`, add code to close the NUI when the close button is clicked:

```js
window.addEventListener('DOMContentLoaded', () => {
    const closeBtn = document.getElementById('closeBtn');

    closeBtn.addEventListener('click', () => {
        fetch('http://my_nui_example/close', { method: 'post' });
    });
});
```

7. Inside the `my_nui_example` folder, create a file called `client.lua` with the following Lua code:

```lua
-- Function to show the NUI
function showNUI(visible)
    SetNuiFocus(visible, visible)
    SendNUIMessage({
        type = "APP_SHOW",
        show = visible
    })
end

-- Register an event to open the UI
RegisterNetEvent('my_nui_example:open')
AddEventHandler('my_nui_example:open', function()
