typedef struct {
    unsigned short SOI;
    unsigned short APP0;
    unsigned short DQT;
    unsigned short SOF0;
    unsigned short DHT;
    unsigned short SOS;
    unsigned short EOI;
    unsigned short COM;
} JPEGMarkers;

void read_header(FILE *file);
void decode_image(FILE *file);
void process_image();

int main() {
    FILE *file;

    file = fopen(filename, "rb");
    if (!file) {
        fprintf(stderr, "Failed to open file: %s\n", filename);
        exit(1);
    }

    read_header(file);
    decode_image(file);
