```c++
#include <iostream>
#include <fstream>
#include <memory>
#include <cstring>
#include <chrono>
#include "tensorflow/lite/interpreter.h"
#include "tensorflow/lite/model.h"
#include "tensorflow/lite/kernels/register.h"

// Распечатать ошибки в консоли
void error_reporter(const char* fmt, va_list args) {
  vfprintf(stderr, fmt, args);
}

// Функция для чтения содержимого файла
std::unique_ptr<char[]> read_file(const char* filename) {
  std::ifstream file(filename, std::ios::in | std::ios::binary | std::ios::ate);

  if (!file.is_open()) {
    std::cerr << "Не удалось открыть файл: " << filename << std::endl;
    throw std::runtime_error("Не удалось открыть файл");
  }

  std::streamsize size = file.tellg();
  auto buffer = std::make_unique<char[]>(size);
  file.seekg(0, std::ios::beg);
  if (!file.read(buffer.get(), size)) {
    std::cerr << "Не удалось прочитать файл: " << filename << std::endl;
    throw std::runtime_error("Не удалось прочитать файл");
  }

  return buffer;
}

int main(int argc, char* argv[]) {
  // Загрузить модель
  auto model_data = read_file(argv[1]);
  auto model = tflite::FlatBufferModel::BuildFromBuffer(model_data.get(), model_data.size());
  if (!model) {
    std::cerr << "Не удалось загрузить модель" << std::endl;
    return -1;
  }

  // Создать интерпретатор
  tflite::ops::builtin::BuiltinOpResolver resolver;
  tflite::InterpreterBuilder builder(*model, resolver);
  std::unique_ptr<tflite::Interpreter> interpreter;
  builder(&interpreter);
  if (!interpreter) {
    std::cerr << "Не удалось создать интерпретатор" << std::endl;
    return -1;
  }

  // Настроить интерпретатор
  interpreter->UseNNAPI(false);
  interpreter->SetNumThreads(1);

  // Получить информацию о входном и выходном тензорах
  const auto input = interpreter->tensor(interpreter->inputs()[0]);
  const auto output = interpreter->tensor(interpreter->outputs()[0]);
  const auto input_name = interpreter->GetInputName(0);
  const auto output_name = interpreter->GetOutputName(0);

  // Открыть аудио вход и сконфигурировать размер входного тензора
  const int sampling_rate = 16000;
  const int audio_clip_duration_samples = 16000;
  const int audio_clip_duration_ms = audio_clip_duration_samples * 1000 / sampling_rate;
  std::vector<int16_t> audio_buffer(audio_clip_duration_samples);

  while (true) {
    // Считать данные из аудио входа
    memset(audio_buffer.data(), 0, audio_clip_duration_samples * sizeof(int16_t));
    std::cin.read(reinterpret_cast<char*>(audio_buffer.data()), audio_clip_duration_samples * sizeof(int16_t));

    const auto t1 = std::chrono::high_resolution_clock::now();

    // Загрузить данные во входной тензор и выполнить интерпретацию
    memcpy(input->data.int16, audio_buffer.data(), audio_buffer.size() * sizeof(int16_t));
    if (interpreter->Invoke() != kTfLiteOk) {
      std::cerr << "Ошибка при выполнении интерпретации" << std::endl;
      return -1;
    }

    // Извлечь выходной тензор и проверить результат
    const float detect_threshold = 0.5f;
    const float* output_data = output->data.f;
    if (output_data[0] > detect_threshold) {
      std::cout << "WakeWord Detection: Включить голосовое управление" << std::endl;
    }

    const auto t2 = std::chrono::high_resolution_clock::now();
    const auto duration = std::chrono::duration_cast<std::chrono::milliseconds>(t2 - t1).count();
    std::cerr << "Время выполнения: " << duration << " мс" << std::endl;
  }

  return 0;
}
```

В этом примере загружается Tensorflow Lite-модель, которая была предварительно обучена на выбранных данных в Formant. Затем создается интерпретатор из полученной модели. Далее в каждой итерации считываются данные из аудио входа, которые затем загружаются в тензор. После этого происходит выполнение интерпретации, и в случае успешного завершения извлекается выходной тензор. Если значение выходного тензора больше порогового значения, то выводится сообщение о том, что слово-команда была распознана. Кроме того, для каждой итерации измеряется время выполнения.

