```javascript
loadGLTFModel(url) {
  // Check if file exists locally
  const localFile = `./static/models/gltf/${url}`;
  const fileExists = fs.existsSync(localFile);

  // Instantiate a loader
  let loader;
  const ext = url.split('.').pop();

  if (ext === 'glb' || !fileExists) {
    // Load remote file
    const remoteURL = `https://example.com/models/${url}`;
    loader = new GLTFLoader().setPath(remoteURL);
  } else if (ext === 'fbx') {
    // Load local file
    loader = new FBXLoader().setPath('/static/models/fbx/');
  }

  // Check if model has been loaded before
  if (this.models[url]) {
    // Model already loaded, use cached version
    this.setTheObject(this.models[url].clone());
    return;
  }

  // Progress callback
  const onProgress = xhr => {
    this.isLoading = true;
    this.progress = Math.round((xhr.loaded / xhr.total) * 100);
    console.log(`Loading ${url}: ${this.progress}%`);
  };

  // Success callback
  const onSuccess = gltf => {
    console.log(`${url} loaded successfully!`);

    let theObject = gltf.scene;
    theObject.name = 'theObject';

    // Set texture and material settings for each mesh in object
    theObject.traverse(obj => {
      if (obj.type === 'Mesh') {
        const mat = obj.material;

        if (mat.map) {
          mat.map.encoding = THREE.sRGBEncoding;
          mat.map.anisotropy = 16;
          mat.map.wrapS = THREE.RepeatWrapping;
          mat.map.wrapT = THREE.RepeatWrapping;
          mat.map.minFilter = THREE.LinearFilter;
          mat.map.magFilter = THREE.LinearFilter;

          if (mat.normalMap) {
            mat.normalMap.encoding = THREE.sRGBEncoding;
            mat.normalMap.type = THREE.TangentSpaceNormalMap;
          }
        }
      }
    });

    // Save model to cache
    this.models[url] = theObject.clone();

    // If file is remote, save to cache
    if (ext === 'glb') {
      const cacheDirectory = 'D:/huache/';
      const cacheFile = `${cacheDirectory}${url}`;

      if (!fs.existsSync(cacheDirectory)) {
        fs.mkdirSync(cacheDirectory);
      }

      fs.copyFileSync(remoteURL, cacheFile);
      console.log(`Cached ${url} successfully!`);
    }

    // Add model to scene
    this.setTheObject(theObject);

    // Adjust size and position of object
    this.setCenter(theObject);

    this.isLoading = false;
  };

  // Error callback
  const onError = error => {
    console.error(`An error occurred while loading ${url}: ${error}`);
    this.isLoading = false;
  };

  // Load model
  if (fileExists) {
    this.loaderGLTF.load(localFile, onSuccess, onProgress, onError);
  } else {
    loader.load(`${url}`, onSuccess, onProgress, onError);
  }
}
```

