Below is a Java program utilizing Hadoop MapReduce to perform sentiment analysis on a given text input. It demonstrates the core components, Mapper, Reducer, and the driver.

Assumptions:
1. You have already set up Hadoop on your machine.
2. You have required input files with positive and negative words.
3. In the input text file, each line is considered as a separate review/comment.
4. For simplicity, only word-level analysis will be implemented.

**PositiveWords.txt**
```
good
happy
excellent
great
nice
```

**NegativeWords.txt**
```
bad
sad
awful
poor
terrible
```

**InputText.txt**
```
This product is just amazing, great quality
Not at all happy with the purchase, waste of money
```

```
import org.apache.hadoop.conf.Configuration;
import org.apache.hadoop.conf.Configured;
import org.apache.hadoop.fs.Path;
import org.apache.hadoop.io.IntWritable;
import org.apache.hadoop.io.LongWritable;
import org.apache.hadoop.io.Text;
import org.apache.hadoop.mapreduce.Job;
import org.apache.hadoop.mapreduce.Mapper;
import org.apache.hadoop.mapreduce.Reducer;
import org.apache.hadoop.mapreduce.lib.input.FileInputFormat;
import org.apache.hadoop.mapreduce.lib.output.FileOutputFormat;
import org.apache.hadoop.util.Tool;
import org.apache.hadoop.util.ToolRunner;
import org.apache.hadoop.filecache.DistributedCache;

import java.io.BufferedReader;
import java.io.FileReader;
import java.io.IOException;
import java.net.URI;
import java.util.HashSet;
import java.util.Set;
import java.util.StringTokenizer;

public class SentimentAnalysis extends Configured implements Tool{

    public static class SentimentMapper extends Mapper<LongWritable, Text, Text, IntWritable> {

        private Set<String> positiveWords = new HashSet<>();
        private Set<String> negativeWords = new HashSet<>();
        private final static IntWritable one = new IntWritable(1);
        private final static IntWritable minusOne = new IntWritable(-1);
        private Text sentiment = new Text();

        @Override
        protected void setup(Context context) throws IOException, InterruptedException {
            URI[] files = DistributedCache.getCacheFiles(context.getConfiguration());
            if (files != null && files.length == 2) {
                readFile(files[0].getPath(), positiveWords);
                readFile(files[1].getPath(), negativeWords);
            }
        }

        private void readFile(String filePath, Set<String> wordSet) throws IOException {
            try (BufferedReader reader = new BufferedReader(new FileReader(filePath))) {
                String line = reader.readLine();
                while (line != null) {
                    StringTokenizer tokenizer = new StringTokenizer(line);
                    while (tokenizer.hasMoreTokens()) {
                        wordSet.add(tokenizer.nextToken());
                    }
                    line = reader.readLine();
                }
            }
        }

        @Override
        protected void map(LongWritable key, Text value, Context context) throws IOException, InterruptedException {
            StringTokenizer tokenizer = new StringTokenizer(value.toString());
            while (tokenizer.hasMoreTokens()) {
                String token = tokenizer.nextToken();
                if (positiveWords.contains(token)) {
                    sentiment.set("positive");
                    context.write(sentiment, one);
                } else if (negativeWords.contains(token)) {
                    sentiment.set("negative");
                    context.write(sentiment, minusOne);
                }
            }
        }
    }

    public static class SentimentReducer extends Reducer<Text, IntWritable, Text, IntWritable> {
        private IntWritable result = new IntWritable();

        @Override
        protected void reduce(Text key, Iterable<IntWritable> values, Context context) throws IOException, InterruptedException {
            int sum = 0;
            for (IntWritable val : values) {
                sum += val.get();
            }
            result.set(sum);
            context.write(key, result);
        }
    }

    @Override
    public int run(String[] args) throws Exception {
        Configuration conf = getConf();
        Job job = Job.getInstance(conf, "Sentiment Analysis");
        job.setJarByClass(SentimentAnalysis.class);

        job.setMapperClass(SentimentMapper.class);
        job.setCombinerClass(SentimentReducer.class);
        job.setReducerClass(SentimentReducer.class);
        job.setOutputKeyClass(Text.class);
        job.setOutputValueClass(IntWritable.class);

        FileInputFormat.addInputPath(job, new Path(args[0]));
        FileOutputFormat.setOutputPath(job, new Path(args[1]));

        // Add the positive and negative words files to the distributed cache
        DistributedCache.addCacheFile(new URI(args[2]), conf);
        DistributedCache.addCacheFile(new URI(args[3]), conf);

        return job.waitForCompletion(true) ? 0 : 1;
    }

    public static void main(String[] args) throws Exception {
        int res = ToolRunner.run(new Configuration(), new SentimentAnalysis(), args);
        System.exit(res);
    }
}
```

