import org.apache.hadoop.fs.Path;
import org.apache.hadoop.io.IntWritable;
import org.apache.hadoop.io.Text;
import org.apache.hadoop.mapreduce.Job;
import org.apache.hadoop.mapreduce.Mapper;
import org.apache.hadoop.mapreduce.Reducer;
import org.apache.hadoop.mapreduce.lib.input.FileInputFormat;
import org.apache.hadoop.mapreduce.lib.output.FileOutputFormat;
import org.apache.hadoop.mapreduce.lib.output.MultipleOutputs;
import org.apache.hadoop.mapreduce.lib.output.TextOutputFormat;
import org.apache.hadoop.util.Tool;
import org.apache.hadoop.util.ToolRunner;

import java.io.IOException;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import java.util.StringTokenizer;

public class SentimentAnalysisMultipleOutputs extends Configured implements Tool {

    public static class SentimentMapper extends Mapper<Object, Text, Text, IntWritable> {

        private Map<String, String> sentimentWords = new HashMap<>();
        private final static IntWritable one = new IntWritable(1);
        private Text word = new Text();

        @Override
        protected void setup(Context context) {
            // Positive words (use a separate file in real applications)
            Set<String> positiveWords = new HashSet<>();
            positiveWords.add("good");
            positiveWords.add("happy");
            positiveWords.add("excellent");
            positiveWords.add("great");
            positiveWords.add("nice");

            // Negative words (use a separate file in real applications)
            Set<String> negativeWords = new HashSet<>();
            negativeWords.add("bad");
            negativeWords.add("sad");
            negativeWords.add("awful");
            negativeWords.add("poor");
            negativeWords.add("terrible");

            for (String positiveWord : positiveWords) {
                sentimentWords.put(positiveWord, "positive");
            }

            for (String negativeWord : negativeWords) {
                sentimentWords.put(negativeWord, "negative");
            }
        }

        @Override
        protected void map(Object key, Text value, Context context) throws IOException, InterruptedException {
            StringTokenizer tokenizer = new StringTokenizer(value.toString());
            while (tokenizer.hasMoreTokens()) {
                String token = tokenizer.nextToken().toLowerCase();
                if (sentimentWords.containsKey(token)) {
                    word.set(token);
                    context.write(word, one);
                }
            }
        }
    }

    public static class SentimentReducer extends Reducer<Text, IntWritable, Text, IntWritable> {
        private IntWritable result = new IntWritable();
        private MultipleOutputs<Text, IntWritable> multipleOutputs;

        @Override
        protected void setup(Context context) {
            multipleOutputs = new MultipleOutputs<>(context);
        }

        @Override
        protected void reduce(Text key, Iterable<IntWritable> values, Context context)  {
            int sum = 0;
            for (IntWritable val : values) {
                sum += val.get();
            }
            result.set(sum);
            String baseOutputPath = "positive".equalsIgnoreCase(context.getConfiguration().get(key.toString())) ? "positiveWords" : "negativeWords";
            multipleOutputs.write(key, result, baseOutputPath);
        }

        @Override
        protected void cleanup(Context context) throws IOException, InterruptedException {
            multipleOutputs.close();
        }
    }

    @Override
    public int run(String[] args) throws Exception {
        if (args.length != 2) {
            System.err.println("Usage: SentimentAnalysisMultipleOutputs <input-path> <output-path>");
            System.exit(-1);
        }

        Configuration conf = new Configuration();
        Job job = Job.getInstance(conf, "Sentiment Analysis");
        job.setJarByClass(SentimentAnalysisMultipleOutputs.class);
        FileInputFormat.addInputPath(job, new Path(args[0]));
        FileOutputFormat.setOutputPath(job, new Path(args[1]));

        job.setMapperClass(SentimentMapper.class);
        job.setReducerClass(SentimentReducer.class);

        job.setOutputKeyClass(Text.class);
        job.setOutputValueClass(IntWritable.class);

        job.setOutputFormatClass(TextOutputFormat.class);

        return job.waitForCompletion(true) ? 0 : 1;
    }

    public static void main(String[] args) throws Exception {
        int res = ToolRunner.run(new Configuration(), new SentimentAnalysisMultipleOutputs(), args);
        System.exit(res);
    }
}
```

