using namespace std;

// Named constants
const int NUM_CLUSTERS = 4;
const int NUM_ENTRIES = 6;
const int NUM_SONGS = 10;
const string CLEAR_SCREEN = "clear"; // Use "cls" for Windows, "clear" for Linux/Unix/Mac

// Function prototypes
