    int radio[NUM_CLUSTERS][NUM_ENTRIES] = {
        {88, 89, 90, 91, 92, 93},
        {94, 95, 96, 97, 98, 99},
        {530, 540, 550, 560, 570, 580},
        {1, 2, 3, 4, 5, 6}
    };

    // Variables for user interaction
    int clusterIndex = 0;
    char userChoice;

    do {
        displayRadio(radio, clusterIndex);

        cout << "Enter 'c' to change station, 's' to save station, 'n' to switch radio cluster, 'x' to exit: ";
        cin >> userChoice;
        cout << endl;

        switch (tolower(userChoice)) {
            case 'c':
                changeStation(radio, clusterIndex);
                break;
            case 's':
                saveStation(radio, clusterIndex);
                break;
            case 'n':
                clusterIndex = (clusterIndex + 1) % NUM_CLUSTERS;
                break;
            case 'x':
                break;
            default:
                cout << "Invalid input. Please try again." << endl;
                break;
        }
        system(CLEAR_SCREEN.c_str());

    } while (tolower(userChoice) != 'x');

    return 0;
}

void changeStation(int radio[][NUM_ENTRIES], int clusterIndex) {
    int newStation;
    cout << "Enter new station: ";
    cin >> newStation;
    radio[clusterIndex][0] = newStation;
}

void saveStation(int radio[][NUM_ENTRIES], int clusterIndex) {
    int stationIndex;
    cout << "Enter the station number (1-6) to save current station: ";
    cin >> stationIndex;

    if (stationIndex >= 1 && stationIndex <= 6) {
        radio[clusterIndex][stationIndex - 1] = radio[clusterIndex][0];
        cout << "Station saved." << endl;
    } else {
        cout << "Invalid station number. Please try again." << endl;
    }
}

void displayRadio(int radio[][NUM_ENTRIES], int clusterIndex) {
    string clusterName;

    if (clusterIndex == 0) {
        clusterName = "FM1";
    } else if (clusterIndex == 1) {
        clusterName = "FM2";
    } else if (clusterIndex == 2) {
        clusterName = "AM";
    } else {
        clusterName = "CD/MP3";
    }

    cout << "Radio Cluster: " << clusterName << endl;
    cout << "Current Station: " << radio[clusterIndex][0] << endl;

    cout << "Saved Stations: ";
    for (int i = 1; i < NUM_ENTRIES; ++i) {
        cout << radio[clusterIndex][i] << " ";
    }
    cout << endl;
}
