Based on your description, I have created a basic example of a packet transmission project. It consists of three classes: `Packet`, `TCPPacketServer`, and `TCPPacketClient`.

Class 1: Packet.java
```
import java.io.Serializable;

public class Packet implements Serializable {
    private int serialNo;
    private String data;

    public Packet(int serialNo, String data) {
        this.serialNo = serialNo;
        this.data = data;
    }

    public int getSerialNo() {
        return serialNo;
    }

    public String getData() {
        return data;
    }
}
```

Class 2: TCPPacketServer.java
```
import java.net.ServerSocket;
import java.net.Socket;
import java.io.ObjectInputStream;
import java.io.ObjectOutputStream;

public class TCPPacketServer {
    public static final int PORT = 1024;

    public static void main(String[] args) {
        try (ServerSocket serverSocket = new ServerSocket(PORT)) {
            System.out.println("Server is running on port " + PORT);

            while (true) {
                Socket clientSocket = serverSocket.accept();
                handleClient(clientSocket);
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    public static void handleClient(Socket clientSocket) {
        try (
            ObjectOutputStream outputStream = new ObjectOutputStream(clientSocket.getOutputStream());
            ObjectInputStream inputStream = new ObjectInputStream(clientSocket.getInputStream())
        ) {
            Packet packet = (Packet) inputStream.readObject();
            System.out.println("Received packet with serial number: " + packet.getSerialNo() + " and data: " + packet.getData());

            if (packet.getData().equals("CLOSE")) {
                inputStream.close();
                outputStream.close();
                clientSocket.close();
                return;
            }

            String data = packet.getData().toUpperCase();
            outputStream.writeObject(new Packet(packet.getSerialNo(), data));
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
```

Class 3: TCPPacketClient.java
```
import java.net.Socket;
import java.io.ObjectInputStream;
import java.io.ObjectOutputStream;
import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;

public class TCPPacketClient {
    public static final String HOST = "localhost";
    public static final int PORT = 1024;

    public static void main(String[] args) {
        try (
            Socket socket = new Socket(HOST, PORT);
            ObjectOutputStream outputStream = new ObjectOutputStream(socket.getOutputStream());
            ObjectInputStream inputStream = new ObjectInputStream(socket.getInputStream());
            BufferedReader keyboard = new BufferedReader(new InputStreamReader(System.in))
        ) {
            System.out.println("Connected to server");

            int serialNo = 1;
            while (true) {
                System.out.print("Enter the packet data: ");
                String data = keyboard.readLine();

                outputStream.writeObject(new Packet(serialNo, data));
                if (data.equals("CLOSE")) {
                    break;
                }

                Packet receivedPacket = (Packet) inputStream.readObject();
                System.out.println("Received packet with serial number: " + receivedPacket.getSerialNo() + " and data: " + receivedPacket.getData());

                serialNo++;
            }
        } catch (IOException | ClassNotFoundException e) {
            e.printStackTrace();
        }
    }
}
```

