请注意，程序中使用了 `M_PI` 常量代表圆周率π，需要在文件头文件中添加 `#define _USE_MATH_DEFINES` 宏定义，或者手动定义 `M_PI` 常量。

行波测距（Time Domain Reflectometry，TDR）是一种常用的测量线路长度、定位故障位置的技术，其原理是利用行波在传输线上的反射来确定线路长度或故障位置。以下是一个简单的TDR算法，用于确定一对接线的长度或查找线路上的开路或短路等故障：

```c
#include <stdio.h>
#include <stdlib.h>

#define MIN(a, b) ((a) < (b) ? (a) : (b))

double TDR(double *voltage, int length, double step_size)
{
    double rise_time = 0.0;
    double thresh = 0.1 * voltage[0]; /* 设置电压阈值为最大电压的10% */
    int i;

    for (i = 0; i < length; i++) {
        if (abs(voltage[i]) >= thresh) {
            rise_time = step_size * i; /* 记录上升沿时间 */
            break;
        }
    }

    if (rise_time == 0.0) {
        printf("Error: No signal detected!\n");
        return -1.0;
    }

    double start_time = rise_time; /* 初始化起始测量时间为上升沿时间 */
    double time_diff;
    double prev_diff;
    int overshoot;
    double length_sum = 0.0;

    for (i = 1; i < length; i++) {
        time_diff = step_size * i - start_time;
        overshoot = voltage[i] > 0.0;

        if (overshoot && voltage[i] < voltage[i-1]) { /* 判断波峰是否结束 */
            double prop_time = time_diff * MIN(voltage[i], thresh) /
                (voltage[i] - voltage[i-1]); /* 计算峰值到达时间 */
            length_sum += prop_time / 2.0; /* 加载到当前位置的校准总长度 */
            start_time = step_size * i - prop_time / 2.0; /* 更新起始时间 */
            prev_diff = time_diff - prop_time; /* 更新前一阶段的时间差 */
        } else {
            length_sum += (time_diff + prev_diff) / 2.0; /* 加载到当前位置的校准总长度 */
            prev_diff = time_diff; /* 更新前一阶段的时间差 */
        }

        if (abs(voltage[i]) >= thresh) { /* 如果发现新的上升沿 */
            length_sum += prev_diff / 2.0; /* 加载到当前位置的校准总长度 */
            start_time = step_size * i - prev_diff / 2.0; /* 更新起始时间 */
            thresh = 0.1 * voltage[i]; /* 更新电压阈值为最大电压的10% */
            prev_diff = overshoot ? rise_time - start_time : time_diff; /* 更新前一阶段的时间差 */
        }
    }

    return length_sum;
}

int main()
{
    const int length = 1000;
    double voltage[length];
    double step_size = 1.0e-9; /* 采样时间间隔 */
    double length_corr;

    /* 在第500个采样点处加入一个50ps宽的模拟脉冲，并设置一对接线 */
    for (int i = 0; i < length; i++) {
        voltage[i] = -0.5 + 0.5 * ((double)i < 500 || (double)i >= 550);
    }
    voltage[500] += 0.1;
    voltage[550] -= 0.1;

    length_corr = TDR(voltage, length, step_size);

    if (length_corr >= 0.0) {
        printf("校验总长度为：%lf米\n", length_corr);
    }

    return 0;
}
```

该计算TDR采用C语言实现，并使用一个简单的测试输入，在第500个采样点处加入一个50ps宽的模拟脉冲，并设置一对接线。程序中 `TDR()` 函数模拟了TDR算法，首先检测上升沿，然后根据电压间断点和时间间隔计算校准长度。最后，程序输出了经过校准后的测量长度。请注意，该示例程序仅用于说明该算法的基本原理，并且假定已知电压阈值和传播速度等参数。在实践中，您可能需要根据实际情况进行更多的优化和校准。

