```cpp
#include <iostream>
#include <string>
#include <vector>
#include <memory> // for smart pointers

using namespace std;

class Flight;
class Luggage;

class Luggage {
    string id;
    string status;

public:
    Luggage(string id, string status) : id(id), status(status) {}

    string getId() const {
        return id;
    }

    string getStatus() const {
        return status;
    }
};

class Passenger {
    string name;
    string email;
    string phone;
    vector<Luggage> luggage;

public:
    Passenger(string name, string email, string phone) : name(name), email(email), phone(phone) {}

    string getName() const {
        return name;
    }

    string getEmail() const {
        return email;
    }

    string getPhone() const {
        return phone;
    }

    void addLuggage(const Luggage& luggageItem) {
        luggage.push_back(luggageItem);
    }

    const vector<Luggage>& getLuggage() const {
        return luggage;
    }
};

class Airline {
protected:
    string name;

public:
    Airline(string name) : name(name) {}

    virtual double getTicketPrice() const = 0;

    string getName() const {
        return name;
    }
};

class EconomyAirline : public Airline {
public:
    EconomyAirline() : Airline("Economy") {}

    double getTicketPrice() const {
        return 100.00;
    }
};

class BusinessAirline : public Airline {
public:
    BusinessAirline() : Airline("Business") {}

    double getTicketPrice() const {
        return 200.00;
    }
};

class FirstClassAirline : public Airline {
public:
    FirstClassAirline() : Airline("First Class") {}

    double getTicketPrice() const {
        return 300.00;
    }
};

struct Flight {
    string flightNumber;
    string source;
    string destination;
    string date;
    string time;
    shared_ptr<Airline> airline; // using smart pointers
    vector<Passenger> passengers;

    Flight(string flightNumber, string source, string destination, string date, string time, shared_ptr<Airline> airline)
        : flightNumber(flightNumber), source(source), destination(destination), date(date), time(time), airline(airline) {}

    string getSource() const {
        return source;
    }
};

class AirportSystem {
public:
    vector<Flight> flights;

    void bookFlight(string flightNumber, string destination, string date, string time, shared_ptr<Airline> airline, Passenger passenger) {
        vector<Passenger> passengers = {passenger};
        Flight flight(flightNumber, "", destination, date, time, airline);
        flight.passengers = passengers;
        flights.push_back(flight);
        cout << "Flight " << flightNumber << " booked successfully!" << endl;
    }

    void displayFlights() const {
        for (const auto& flight : flights) {
            cout << "Flight Number: " << flight.flightNumber << endl;
            cout << "Source: " << flight.getSource() << endl;
            cout << "Destination: " << flight.destination << endl;
            cout << "Date: " << flight.date << endl;
            cout << "Time: " << flight.time << endl;
            cout << "Airline: " << flight.airline->getName() << endl;
            cout << "Ticket Price: $" << flight.airline->getTicketPrice() << endl;
            cout << "Passengers: " << endl;

            for (const auto& passenger : flight.passengers) {
                cout << "Name: " << passenger.getName() << ", Email: " << passenger.getEmail() << ", Phone: " << passenger.getPhone() << endl;
            }
            cout << endl;
        }
    }

    void trackLuggage(string luggageId) const {
        for (const auto& flight : flights) {
            for (const auto& passenger : flight.passengers) {
                for (const auto& luggage : passenger.getLuggage()) {
                    if (luggage.getId() == luggageId) {
                        cout << "Luggage " << luggageId << " is " << luggage.getStatus() << " and is associated with flight " << flight.flightNumber << endl;
                        return;
                    }
                }
            }
        }

        cout << "Luggage " << luggageId << " not found" << endl;
    }
};

int main() {
    AirportSystem airportSystem;

    Passenger passenger1("John Smith", "johnsmith@example.com", "1234567890");
    Passenger passenger2("Sarah Johnson", "sarahjohnson@example.com", "0987654321");

