Here's a simple implementation using HTML, CSS and JavaScript (specifically, the jQuery UI library). This example creates draggable nodes with inputs and outputs, and allows you to drag a connection between the output of one node to the input of another node. When a connection is made, the text "Working" is printed on the console.

HTML:

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Draggable Nodes</title>
  <link rel="stylesheet" href="https://code.jquery.com/ui/1.12.1/themes/base/jquery-ui.css">
  <style>
    .node {
      width: 100px;
      height: 50px;
      background-color: cornflowerblue;
      border: 1px solid black;
      display: flex;
      justify-content: space-between;
      align-items: center;
      padding: 10px;
    }

    .input, .output {
      width: 10px;
      height: 10px;
      border-radius: 50%;
      background-color: white;
      border: 1px solid black;
    }

    .output {
      background-color: darkblue;
    }
  </style>
</head>
<body>
  <div id="node1" class="node">
    <div class="input"></div>
    <div class="output"></div>
  </div>
  <div id="node2" class="node">
    <div class="input"></div>
    <div class="output"></div>
  </div>

  <script src="https://code.jquery.com/jquery-3.6.0.min.js"></script>
  <script src="https://code.jquery.com/ui/1.12.1/jquery-ui.js"></script>
  <script src="script.js"></script>
</body>
</html>
```

JavaScript (script.js):

```javascript
$(function() {
  $('.node').draggable();

  $('.output').draggable({
    helper: 'clone',
    revert: 'invalid',
    start: function() {
      $(this).data('connected', false);
    },
    stop: function() {
      if (!$(this).data('connected')) {
        console.log('Not connected');
      }
    }
  });

  $('.input').droppable({
    accept: '.output',
    tolerance: 'touch',
    drop: function(event, ui) {
      $(ui.draggable).data('connected', true);
      console.log('Working');
    }
  });
});
```

You can run this example by copying the HTML to an `index.html` file and the JavaScript to a `script.js` file, then open the `index.html` in your browser. To see the "Working" messages, open the browser's developer console while testing the functionality.

Keep in mind that this is a basic example, and there are many ways to improve and extend it. The code uses the jQuery library and jQuery UI due to their simplicity for demonstrations; however, for production projects, more modern frameworks and libraries are recommended.

Kansas City Standard (KCS), also known as Byte standard, is an early digital data encoding method used to store and transfer data on audio tapes. Here's a basic implementation in C code for Kansas City Standard data transmission at 1200 baud (1200 bits per second).

```c
#include <stdio.h>
#include <stdint.h>
#include <stdbool.h>

#define BAUD_RATE 1200
#define SAMPLE_RATE 44100
#define FREQ_STANDARD 1800
#define FREQ_SILENCE 2400
#define SILENCE_DURATION 10
#define BIT_DURATION (SAMPLE_RATE / BAUD_RATE)
#define FREQ_LOW 1200
#define FREQ_HIGH 2400

static const uint8_t KCS_INIT_BYTE = 0x80;
static const uint8_t KCS_STOP_BIT_MASK = 0x40;
static const uint8_t KCS_DATA_MASK = 0x1F;

int sum_of_sin(int sample_freq, int freq, int samples) {
    double sum = 0.0;

    for (int i = 0; i < samples; i++) {
        sum += sin(2.0 * 3.14159265358979323846 * i * freq / sample_freq);
    }

    return sum;
}

void emit_bit(bool bit, FILE *fout) {
    int freq = bit ? FREQ_HIGH : FREQ_LOW;
    int16_t samples[BIT_DURATION];

    for (int i = 0; i < BIT_DURATION; i++) {
        samples[i] = (int16_t)(INT16_MAX * sin(2.0 * 3.14159265358979323846 * i * freq / SAMPLE_RATE));
    }

    fwrite(samples, sizeof(int16_t), BIT_DURATION, fout);
}

void emit_byte(uint8_t byte, FILE *fout, bool first) {
    if (first) {
        byte |= KCS_INIT_BYTE;
    }

    for (int i = 0; i < 10; i++) {
        emit_bit((byte & 1) != 0, fout);
        byte >>= 1;
    }
}

void kcs_encode(const uint8_t *data, size_t size, const char *out_wav_file) {
    FILE *fout = fopen(out_wav_file, "wb");
    if (!fout) {
        perror("Error opening output file!");
        return;
    }

    // Write WAVE header
    fwrite("RIFF", 4, 1, fout);
    uint32_t temp = 36 + size * BIT_DURATION * 2;
    fwrite(&temp, 4, 1, fout);
    fwrite("WAVEfmt ", 8, 1, fout);
    temp = 16;
    fwrite(&temp, 4, 1, fout);
    temp = 1;
    fwrite(&temp, 2, 1, fout); // Audio format: PCM
    temp = 1;
    fwrite(&temp, 2, 1, fout); // Channels: mono
    fwrite(&SAMPLE_RATE, 4, 1, fout); // Sample rate
    temp = SAMPLE_RATE * 2;
    fwrite(&temp, 4, 1, fout); // Byte rate
    temp = 2;
    fwrite(&temp, 2, 1, fout); // Block align
    temp = 16;
    fwrite(&temp, 2, 1, fout); // Bits per sample
    fwrite("data", 4, 1, fout);
    temp = size * BIT_DURATION * 2;
    fwrite(&temp, 4, 1, fout);

    // Write silence before the data
    for (int i = 0; i < SILENCE_DURATION; i++) {
        emit_bid(false, fout);
    }

    // Write data bytes
    for (size_t i = 0; i < size; i++) {
        emit_byte(data[i], fout, i == 0);
    }

    fclose(fout);
}

int main() {
    uint8_t data[] = {0x48, 0x65, 0x6C, 0x6C, 0x6F, 0x2C, 0x20, 0x77, 0x6F, 0x72, 0x6C, 0x64, 0x21}; // "Hello, world!"
    size_t size = sizeof(data) / sizeof(data[0]);

    kcs_encode(data, size, "output.wav");

    return 0;
}
```

This implementation generates a wave file that contains the KCS encoded data. Note that it's only for demonstration purposes, as there are various aspects of the Kansas City Standard encoding that this code doesn't cover. It also doesn't handle decoding the KCS data.

