Вот скетч для Arduino Uno, который будет вращать шаговый мотор с изменяющейся скоростью, контролируемой потенциометром. Значение потенциометра также будет контролировать направление вращения мотора.

```cpp
#include <Stepper.h> // Подключаем библиотеку Stepper

const int stepsPerRevolution = 200; // Указываем количество шагов на оборот вашего мотора
const int stepPin1 = 8; // Подключаем пины мотора
const int stepPin2 = 9;
const int stepPin3 = 10;
const int stepPin4 = 11;
const int potPin = A0; // Подключаем пин потенциометра

Stepper stepper(stepsPerRevolution, stepPin1, stepPin2, stepPin3, stepPin4); // Инициализация мотора

void setup() {
  pinMode(potPin, INPUT); // Устанавливаем пин потенциометра как входной
  Serial.begin(9600); // Устанавливаем скорость порта на 9600
}

void loop() {
  int potValue = analogRead(potPin); // Читаем значение потенциометра

  // Преобразовываем значение потенциометра (0-1023) в скорость (число от -100 до 100)
  int mappedSpeed = map(potValue, 0, 1023, -100, 100);

  // Устанавливаем заданную скорость для мотора
  stepper.setSpeed(mappedSpeed);

  // Делаем один шаг мотора с заданной скоростью и направлением
  stepper.step(1);

  Serial.print("Potentiometer: "); // Выводим значение потенциометра
  Serial.print(potValue);
  Serial.print("  Mapped Speed: "); // Выводим скорость мотора
  Serial.println(mappedSpeed);
  delay(10); // Задержка на 10 мс
}
```

