            try {
                setDataSource(outputFilePath)

                val bufferSize = 1024
                val stepSize = 256
                val sampleRate = 44100

                val androidAudioPlayer = AndroidAudioPlayer(sampleRate, bufferSize, stepSize)
                val dispatcher = AudioDispatcherFactory.fromPipe(outputFilePath, sampleRate, bufferSize, stepSize)
                dispatcher.addAudioProcessor(androidAudioPlayer)

