                    override fun process(audioEvent: AudioEvent): Boolean {
                        // aplly your custom dsp in here
                        return true
                    }

                    override fun processingFinished() {}
                })

                Thread(dispatcher).start()

            } catch (e: IOException) {
                e.printStackTrace()
            }
        }
    }
}
