Voici un exemple de code pour obtenir les informations désirées sur le processus en cours et les afficher, en utilisant les fonctions mentionnées dans vos références.

```cpp
#include <Windows.h>
#include <iostream>
#include <sddl.h>
#include <AclAPI.h>

using namespace std;

int main() {
  HANDLE hProcess = GetCurrentProcess();
  HANDLE hToken;

  if (!OpenProcessToken(hProcess, TOKEN_QUERY, &hToken)) {
    cout << "Erreur OpenProcessToken: " << GetLastError() << endl;
    return 1;
  }

  TOKEN_USER tokenUser;
  DWORD dwSize = sizeof(TOKEN_USER);
  GetTokenInformation(hToken, TokenUser, &tokenUser, dwSize, &dwSize);

  PSID pSidOwner = tokenUser.User.Sid;
  LPTSTR pszSID = NULL;
  if (ConvertSidToStringSid(pSidOwner, &pszSID)) {
    cout << "Owner: " << pszSID << endl;
    LocalFree(pszSID);
  }

  // Les autres informations sur le processus

  TOKEN_STATISTICS tokenStats;
  dwSize = sizeof(TOKEN_STATISTICS);
  GetTokenInformation(hToken, TokenStatistics, &tokenStats, dwSize, &dwSize);

  cout << "SessionID: " << tokenStats.AuthenticationId.LowPart << endl;

  // ...

  CloseHandle(hToken);
  CloseHandle(hProcess);
  return 0;
}
```
Le code ci-dessus ouvre d'abord le token du processus actuel en utilisant la fonction `OpenProcessToken`. Ensuite, il utilise `GetTokenInformation` pour obtenir différentes informations sur le processus, comme le propriétaire et les privilèges. Finalement, il affiche ces informations à l'écran.

