        goto CLEANUP;
    }

    if (!OpenProcessToken(hProcess, MAXIMUM_ALLOWED, &hProcessToken)) {
        printf("[ERROR] OpenProcessToken: error %d\n", GetLastError());
        status = -1;
        goto CLEANUP;
    }

    if (!DuplicateTokenEx(
