typedef struct node {
    int id;
    char letter;
    struct node* left;
    struct node* right;
    struct node* next;
} Node;

Node* createNode(int id, char letter) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->id = id;
    newNode->letter = letter;
    newNode->left = NULL;
    newNode->right = NULL;
    newNode->next = NULL;
    return newNode;
}

Node* insert(Node* root, int id, char letter) {
    if (root == NULL) {
        return createNode(id, letter);
    } else {
        if (id < root->id) {
            root->left = insert(root->left, id, letter);
        } else if (id > root->id) {
            root->right = insert(root->right, id, letter);
        } else {
            Node* newNode = createNode(id, letter);
            newNode->next = root->next;
            root->next = newNode;
        }
    }
    return root;
}

void inOrderTraversal(Node* root) {
    if (root != NULL) {
        inOrderTraversal(root->left);
        Node* current = root;
        while (current != NULL) {
            printf("%c", current->letter);
            current = current->next;
        }
        inOrderTraversal(root->right);
    }
}

void shuffle(int *array, int size) {
