std::string base64_encode(std::string const& s) {
	constexpr char base64_table[] = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
	constexpr char pad = '=';

	auto len = s.size();
	std::string ret;
	ret.reserve((len / 3 + (len % 3 != 0)) * 4);
	unsigned int buf = 0;
	int buf_len = 0;
	for (char c : s) {
		int x = static_cast<unsigned char>(c);
		buf = (buf << 8) + x;
		buf_len += 8;
		while (buf_len >= 6) {
