    if (cell.textContent) return;

    let symbol = turn % 2 === 1 ? 'X' : 'O';
    cell.textContent = symbol;

    if (isGameOver()) {
        messageElement.textContent = `Player ${turn % 2 === 1 ? 1 : 2} (${symbol}) wins!`;
    } else if (isTie()) {
        messageElement.textContent = "It's a tie!";
    } else {
