        messageElement.textContent = `Player ${turn % 2 === 1 ? 1 : 2}'s turn (${symbol === 'X' ? 'O' : 'X'}).`;
    }
}

function resetGame() {
    const cells = document.querySelectorAll('.grid-item');
    cells.forEach((cell) => (cell.textContent = ''));
    turn = 1;
    messageElement.textContent = "Player 1's turn (X).";
}

function isGameOver() {
    const cells = Array.from(document.querySelectorAll('.grid-item'));
    const lines = [
        [0, 1, 2], [3, 4, 5], [6, 7, 8],
        [0, 3, 6], [1, 4, 7], [2, 5, 8],
        [0, 4, 8], [2, 4, 6]
    ];

    return lines.some((line) => {
        return line.every((index) => cells[index].textContent === cells[line[0]].textContent) && cells[line[0]].textContent !== '';
    });
}

function isTie() {
