btTriangleMesh* Mesh::CreateBulletTriangleMesh() const {
    if (m_bulletTriangleMesh) {
        return m_bulletTriangleMesh.get();
    }

    m_bulletTriangleMesh = std::make_unique<btTriangleMesh>(false, false);

    for (size_t i = 0; i < m_indices.size(); i += 3) {
        const auto& v0 = m_vertices[m_indices[i]];
        const auto& v1 = m_vertices[m_indices[i + 1]];
        const auto& v2 = m_vertices[m_indices[i + 2]];

        m_bulletTriangleMesh->addTriangle(
            btVector3(v0.position.x, v0.position.y, v0.position.z),
            btVector3(v1.position.x, v1.position.y, v1.position.z),
            btVector3(v2.position.x, v2.position.y, v2.position.z)
        );
    }

    return m_bulletTriangleMesh.get();
}
```

