        android:text="Extra Data"
        android:layout_below="@id/textView" />

</RelativeLayout>
```

2. Create a custom adapter class for your list view. This class should extend BaseAdapter and override its methods:

MyCustomAdapter.java:

```java
import android.content.Context;
import android.view.LayoutInflater;
import android.view.View;
import android.view.ViewGroup;
import android.widget.BaseAdapter;
import android.widget.Button;
import android.widget.TextView;

import java.util.List;

public class MyCustomAdapter extends BaseAdapter {

    private List<String> data;
    private Context context;

    public MyCustomAdapter(Context context, List<String> data) {
        this.context = context;
        this.data = data;
    }

    @Override
    public int getCount() {
        return data.size();
    }

    @Override
    public Object getItem(int position) {
        return data.get(position);
    }

    @Override
    public long getItemId(int position) {
        return position;
    }

    @Override
    public View getView(int position, View convertView, ViewGroup parent) {
        if (convertView == null) {
            LayoutInflater inflater = (LayoutInflater) context.getSystemService(Context.LAYOUT_INFLATER_SERVICE);
            convertView = inflater.inflate(R.layout.list_item, parent, false);
        }

        TextView textView = convertView.findViewById(R.id.textView);
        Button button = convertView.findViewById(R.id.button);
        TextView extraData = convertView.findViewById(R.id.extraData);

        textView.setText(data.get(position));
        button.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View v) {
                // Do something with button click
            }
        });
        extraData.setText("Some extra data: " + position);

        return convertView;
    }
}
```

3. Set the custom adapter for your list view in your main activity:

MainActivity.java:

```java
import androidx.appcompat.app.AppCompatActivity;
import android.os.Bundle;
import android.widget.ListView;
import java.util.ArrayList;
import java.util.List;

public class MainActivity extends AppCompatActivity {

    @Override
