Here's a simple Tetris-like game in p5.js using the given word list. The game consists of falling word blocks, which can be moved left or right to make them fall into place. The goal is to align the words horizontally to clear the line and earn points. The game increases in speed as you score more points.

Please note that this code is a starting point and can be modified and improved further. You might want to add more features, such as rotation, game over detection, etc.

```javascript
// Word list
const words = [
  "Head",
  "Face",
  "Eye",
  "Ear",
  "Nose",
  "Mouth",
  "Teeth",
  "Tongue",
  "Neck",
  "Shoulder",
];

let blockSize;
let blockSpeed;
let grid;
let currentBlock;

function setup() {
  createCanvas(800, 500);
  textSize(32);
  textAlign(CENTER, CENTER);
  blockSize = width / 10;
  blockSpeed = 1;
  initGrid();
  createNewBlock();
}

function draw() {
  background(220);

  if (frameCount % (60 - score) === 0) {
    currentBlock.y += blockSpeed;
    if (isColliding()) {
      addToGrid();
      createNewBlock();
    }
  }

  drawGrid();
  drawCurrentBlock();
  checkFullLines();
}

function keyPressed() {
  if (keyCode === LEFT_ARROW) {
    currentBlock.x -= blockSize;
    if (isColliding()) currentBlock.x += blockSize;
  }
  if (keyCode === RIGHT_ARROW) {
    currentBlock.x += blockSize;
    if (isColliding()) currentBlock.x -= blockSize;
  }
}

function initGrid() {
  grid = new Array(height / blockSize).fill(0).map(() => new Array(width / blockSize).fill(""));
}

function createNewBlock() {
  currentBlock = {
    x: (width / 2) - blockSize / 2,
    y: 0,
    word: random(words),
  };
}

function drawCurrentBlock() {
  rect(currentBlock.x, currentBlock.y, blockSize, blockSize);
  text(currentBlock.word, currentBlock.x + blockSize / 2, currentBlock.y + blockSize / 2);
}

function drawGrid() {
  for (let i = 0; i < grid.length; i++) {
    for (let j = 0; j < grid[i].length; j++) {
      if (grid[i][j] !== "") {
        rect(j * blockSize, i * blockSize, blockSize, blockSize);
        text(grid[i][j], j * blockSize + blockSize / 2, i * blockSize + blockSize / 2);
      }
    }
  }
}

function addToGrid() {
  let i = Math.round(currentBlock.y / blockSize);
  let j = Math.round(currentBlock.x / blockSize);
  grid[i][j] = currentBlock.word;
}

function isColliding() {
  let i = Math.round(currentBlock.y / blockSize);
  let j = Math.round(currentBlock.x / blockSize);
  return i + 1 >= grid.length || grid[i + 1][j] !== "";
}

function checkFullLines() {
  for (let i = 0; i < grid.length; i++) {
    let fullLine = true;
    for (let j = 0; j < grid[i].length; j++) {
      if (grid[i][j] === "") {
        fullLine = false;
        break;
      }
    }
    if (fullLine) {
      clearLine(i);
      score += 10;
    }
  }
}

function clearLine(index) {
  grid.splice(index, 1);
  grid.unshift(new Array(width / blockSize).fill(""));
}

let score = 0;
function displayScore() {
  textSize(24);
  fill(0);
  text("Score: " + score, 100, 60);
}
```

