Here is a simple priority queue implementation in C++ using a priority vector:

```cpp
#include <iostream>
#include <vector>
#include <algorithm>

class PriorityQueue {
public:
    void push(int element, int priority) {
        queue.push_back(std::make_pair(element, priority));
        std::sort(queue.begin(), queue.end(), compare);
    }

    int top() {
        if (queue.empty()) {
            throw std::out_of_range("Accessing empty queue");
        }
        return queue.back().first;
    }

    void pop() {
        if (queue.empty()) {
            throw std::out_of_range("Popping from empty queue");
        }
        queue.pop_back();
    }

    int queueSize() {
        return queue.size();
    }

private:
    std::vector<std::pair<int, int>> queue;

    static bool compare(const std::pair<int, int> &a, const std::pair<int, int> &b) {
        return a.second < b.second;
    }
};

int main() {
    PriorityQueue pq;

    pq.push(3, 10);
    pq.push(5, 15);
    pq.push(1, 5);
    pq.push(7, 25);
    pq.push(2, 2);

    while(pq.queueSize() > 0) {
        std::cout << "Top element: " << pq.top() << std::endl;
        pq.pop();
    }

    return 0;
}
```

This program defines a simple `PriorityQueue` class that stores elements and their priorities as pairs in a vector. When a new element is added, the queue is sorted according to the priorities. The `top()` function returns the element with the highest priority without removing it from the queue, while the `pop()` function removes the element with the highest priority from the queue. The example in the `main` function demonstrates how to use this priority queue.

