function addToCart(prodid) {
  // Get the cart cookie
  var cartCookie = getCookie("cart");

  // If the cart cookie is empty, create a new one
  if (cartCookie == "") {
    cartCookie = prodid + ":1";
  } else {
    // Split the cart cookie into an array of products
    var products = cartCookie.split(",");

    // Check if the product is already in the cart
    var existingProduct = false;
    for (var i = 0; i < products.length; i++) {
      var currProduct = products[i].split(":")[0];
      if (currProduct == prodid) {
