        currQuantity++;
        products[i] = prodid + ":" + currQuantity;
        existingProduct = true;
        break;
      }
    }

    // If the product is not already in the cart, add it to the array
    if (!existingProduct) {
      products.push(prodid + ":1");
    }

    // Convert the array of products back to a comma-separated string
    cartCookie = products.join(",");
  }

  // Set the cart cookie
  setCookie("cart", cartCookie, 7); // Set the cookie to expire after 7 days
}

