To convert a derivative map to a normal map in C++, you can use the following steps:

1. Load the derivative map as a texture in your code.

2. Loop through each texel in the derivative map and calculate the X and Y derivatives using the Sobel operator or any other edge detection algorithm.

3. Calculate the Z component of the normal vector using the formula:

   Z = sqrt(1.0 - X^2 - Y^2)

   where X and Y are the X and Y derivatives calculated in step 2.

4. Store the resulting RGB values (X, Y, and Z) in a new normal map texture.

5. Normalize the RGB values of each texel in the normal map texture by dividing them by the maximum absolute value. This ensures that the vector is a unit vector.

6. Optionally, apply a gamma correction to the normal map texture to adjust the perceived brightness of the normals.

Here is some sample code that demonstrates how to convert a derivative map to a normal map:

```c++
// Load the derivative map texture
Texture2D<float> derivativeMap = LoadTexture2D<float>("derivative_map.png");

// Create a new normal map texture
Texture2D<float3> normalMap(derivativeMap.width(), derivativeMap.height());

// Loop through each texel in the derivative map and calculate the normal vector
for (int y = 0; y < derivativeMap.height(); y++) {
    for (int x = 0; x < derivativeMap.width(); x++) {
        // Calculate the X and Y derivatives
        float dX = SobelX(derivativeMap, x, y);
        float dY = SobelY(derivativeMap, x, y);

        // Calculate the Z component of the normal vector
        float dZ = sqrt(1.0f - dX * dX - dY * dY);

        // Store the normal vector in the normal map texture
        normalMap(x, y) = normalize(float3(dX, dY, dZ));
    }
}

// Normalize the RGB values of each texel in the normal map texture
float maxAbs = 0.0f;
for (int y = 0; y < normalMap.height(); y++) {
    for (int x = 0; x < normalMap.width(); x++) {
        maxAbs = max(maxAbs, max(abs(normalMap(x, y).x), max(abs(normalMap(x, y).y), abs(normalMap(x, y).z))));
    }
}

for (int y = 0; y < normalMap.height(); y++) {
    for (int x = 0; x < normalMap.width(); x++) {
        normalMap(x, y) /= maxAbs;
    }
}

// Apply gamma correction to the normal map texture
float gamma = 2.2f;
for (int y = 0; y < normalMap.height(); y++) {
    for (int x = 0; x < normalMap.width(); x++) {
        normalMap(x, y) = pow(normalMap(x, y), float3(1.0f / gamma, 1.0f / gamma, 1.0f / gamma));
    }
}

// Save the normal map texture to disk
SaveTexture2D<float3>(normalMap, "normal_map.png");
```

