To use emersion/go-imap with OAuth for Office 365, you'll first need to register an application and set up authentication using Microsoft's Azure platform. You'll also need to have the relevant packages installed for the IMAP OAuth methods. Follow these steps:

1. Register an application in Azure Active Directory, obtain the relevant application credentials, and set up the required permissions as explained in the [official Microsoft documentation](https://docs.microsoft.com/en-us/azure/active-directory/develop/quickstart-register-app).

2. Install required packages:

```bash
go get github.com/emersion/go-imap
go get github.com/emersion/go-sasl
```

3. Below is an example application that uses the `emersion/go-imap` using OAuth with Office 365:

```go
package main

import (
    "context"
    "fmt"
    "log"

    "github.com/emersion/go-imap"
    "github.com/emersion/go-imap/client"
    "github.com/emersion/go-sasl"
    "golang.org/x/oauth2"
)

const (
    mailServer      = "outlook.office365.com:993"
    oauthEndpoint   = "https://login.microsoftonline.com/{DIRECTORY_(tenant)_ID}/oauth2/v2.0/token"
    tenantID        = "YOUR_TENANT_ID"
    clientID        = "YOUR_CLIENT_ID"
    clientSecret    = "YOUR_CLIENT_SECRET"
    userPrincipal   = "YOUR_USER_PRINCIPAL"
    delegatedUserID = "YOUR_DELEGATED_USER_ID"
)

func getOAuthToken() (*oauth2.Token, error) {
    ctx := context.Background()
    conf := &oauth2.Config{
        ClientID:     clientID,
        ClientSecret: clientSecret,
        Endpoint: oauth2.Endpoint{
            TokenURL: oauthEndpoint,
        },
        Scopes: []string{"https://outlook.office.com/IMAP.AccessAsUser.All"},
    }

    return conf.PasswordCredentialsToken(ctx, userPrincipal)
}

func main() {
    // Get an OAuth token
    token, err := getOAuthToken()
    if err != nil {
        log.Fatalf("Failed to get OAuth token: %v", err)
    }

    // Set up OAuth SASL-based authentication
    saslClient := sasl.NewOAuthBearer(token.AccessToken)

    // Connect to the IMAP server
    c, err := client.DialTLS(mailServer, nil)
    if err != nil {
        log.Fatalf("Failed to connect: %v", err)
    }
    defer c.Logout()

    // Authenticate the connection using our OAuth SASL client
    if err := c.Auth(saslClient); err != nil {
        log.Fatalf("Failed to authenticate: %v", err)
    }

    // Now that we're authenticated, we can use the IMAP client as usual

    // List mailboxes
    mailboxes := make(chan *imap.MailboxInfo, 10)
    done := make(chan error, 1)
    go func() {
        done <- c.List("", "*", mailboxes)
    }()

    fmt.Println("Mailboxes:")
    for m := range mailboxes {
        fmt.Println("* " + m.Name)
    }

    if err := <-done; err != nil {
        log.Fatalf("Failed to list mailboxes: %v", err)
    }
}
```

Update the constants in the example with your own tenant ID, client ID, client secret, and user principal to run the example. The example connects to Office 365 IMAP server, authenticates using Office 365 OAuth, and lists the available mailboxes.

