You can use the following player script to implement fall damage, jump, double jump, sprint with a delay, shooting, and other functionalities in Unity:

```csharp
using System.Collections;
using System.Collections.Generic;
using UnityEngine;

public class PlayerController : MonoBehaviour
{
    public CharacterController characterController;
    public float moveSpeed = 5f;
    public float jumpForce = 10f;
    public float doubleJumpForce = 15f;
    public float sprintFactor = 2f;
    public float sprintDelay = 2f;
    public float fallDamageMultiplier = 5f;
    public GameObject bulletPrefab;
    public Transform bulletSpawn;
    public float bulletSpeed = 10f;

    private bool hasDoubleJumped;
    private float originalMoveSpeed;
    private float sprintTimer;
    private float lastYposition;
    private Vector3 moveDirection;

    void Start()
    {
        characterController = GetComponent<CharacterController>();
        originalMoveSpeed = moveSpeed;
        lastYposition = transform.position.y;
    }

    void Update()
    {
        float moveX = Input.GetAxis("Horizontal") * moveSpeed;
        float moveZ = Input.GetAxis("Vertical") * moveSpeed;

        moveDirection = new Vector3(moveX, moveDirection.y, moveZ);

        if (characterController.isGrounded)
        {
            hasDoubleJumped = false;
            moveDirection.y = -1f;

            if (Input.GetButtonDown("Jump"))
            {
                moveDirection.y = jumpForce;
            }
        }
        else
        {
            if (!hasDoubleJumped && Input.GetButtonDown("Jump"))
            {
                hasDoubleJumped = true;
                moveDirection.y = doubleJumpForce;
            }
        }

        // Sprint implementation
        if (Input.GetKey(KeyCode.LeftShift))
        {
            sprintTimer += Time.deltaTime;
            if (sprintTimer < sprintDelay)
            {
                moveSpeed = originalMoveSpeed * sprintFactor;
            }
            else
            {
                moveSpeed = originalMoveSpeed; 
            }
        }
        else
        {
            moveSpeed = originalMoveSpeed;
            if (sprintTimer > 0)
            {
                sprintTimer -= Time.deltaTime;
            }
        }

        moveDirection.y += Physics.gravity.y * Time.deltaTime;
        characterController.Move(moveDirection * Time.deltaTime);

        // Fall damage implementation
        if (characterController.isGrounded && (lastYposition - transform.position.y) > 2.0f)
        {
            Debug.Log("Fall damage taken: " + (lastYposition - transform.position.y) * fallDamageMultiplier);
        }

        // Update the last y position
        lastYposition = transform.position.y;

        // Shooting
        if (Input.GetButtonDown("Fire1"))
        {
            Shoot();
        }
    }

    void Shoot()
    {
        GameObject bullet = Instantiate(bulletPrefab, bulletSpawn.position, bulletSpawn.rotation) as GameObject;
        bullet.GetComponent<Rigidbody>().velocity = bullet.transform.forward * bulletSpeed;
        Destroy(bullet, 3.0f);
    }
}
```

To use this script, first, create a "Player" game object with a CharacterController component in your Unity scene, and then attach the PlayerController script to the "Player" game object. Also, remember to set the bulletPrefab and bulletSpawn variables in the inspector to make the shooting work properly.

```csharp
using System.Collections;
using System.Collections.Generic;
using UnityEngine;

public class PlayerController : MonoBehaviour
{
    // Variables related to player movement
    public float speed = 10.0f;
    public float jumpForce = 10.0f;
    public float fallMultiplier = 2.5f;
    public float lowJumpMultiplier = 2.0f;
    public float sprintSpeed = 15.0f;
    public float sprintDuration = 5.0f;
    public float sprintDelay = 2.0f;
    public float fallDamageMultiplier = 0.5f;
    public float minFallDamageSpeed = 10.0f;

    // Variable for double jump
    private bool doubleJumpAvailable;
    private float startY;
    private float sprintStartTime;

    // Components
    private Rigidbody rb;
    private bool isGrounded;
    public Transform groundCheck;
    public LayerMask groundMask;
    public float groundDistance = 0.4f;

    // Shooting related variables
    public GameObject bulletPrefab;
    public Transform bulletSpawn;
    public float bulletSpeed = 10.0f;

    void Start()
    {
        rb = GetComponent<Rigidbody>();
        startY = transform.position.y;
        sprintStartTime = -sprintDelay;
    }

    void Update()
    {
        isGrounded = Physics.CheckSphere(groundCheck.position, groundDistance, groundMask);

        if (isGrounded && rb.velocity.y < 0)
        {
            doubleJumpAvailable = true;
            FallDamage();
        }

        Move();
        Jump();
        Shoot();
    }

    void Move()
    {
        float horizontal = Input.GetAxis("Horizontal");
        float vertical = Input.GetAxis("Vertical");

        Vector3 movement = new Vector3(horizontal, 0, vertical) * speed * Time.deltaTime;
        rb.MovePosition(rb.position + movement);

        // Sprint
        if (Input.GetKey(KeyCode.LeftShift) && Time.time - sprintStartTime > sprintDelay + sprintDuration)
        {
            speed = sprintSpeed;
            if (Time.time - sprintStartTime > sprintDuration + sprintDelay + sprintDuration)
            {
                sprintStartTime = Time.time;
            }
        }
        else
        {
            speed = 10.0f;
        }
    }

    void Jump()
    {
        if (Input.GetButtonDown("Jump"))
        {
            if (isGrounded)
            {
                startY = transform.position.y;
                rb.velocity = Vector3.up * jumpForce;
            }
            else if (doubleJumpAvailable)
            {
                doubleJumpAvailable = false;
                rb.velocity = Vector3.up * jumpForce;
            }
        }

        if (rb.velocity.y < 0)
        {
            rb.velocity += Vector3.up * Physics.gravity.y * (fallMultiplier - 1) * Time.deltaTime;
        }
        else if (rb.velocity.y > 0 && !Input.GetButton("Jump"))
        {
            rb.velocity += Vector3.up * Physics.gravity.y * (lowJumpMultiplier - 1) * Time.deltaTime;
        }
    }

    void FallDamage()
    {
        float fallSpeed = Mathf.Abs(rb.velocity.y);

        if (fallSpeed >= minFallDamageSpeed)
        {
            float damage = fallSpeed * fallDamageMultiplier;
            // Apply damage to player
            Debug.Log("Player took " + damage + " fall damage.");
        }
    }

    void Shoot()
    {
        if (Input.GetMouseButtonDown(0))
        {
            GameObject bullet = Instantiate(bulletPrefab, bulletSpawn.position, bulletSpawn.rotation);
            bullet.GetComponent<Rigidbody>().velocity = bullet.transform.forward * bulletSpeed;

            Destroy(bullet, 5.0f);
        }
    }
}
```

This script contains the following features:

1. Normal movement using the WASD keys.
2. Jump and double jump.
3. Sprint for a short duration, with a delay before it can be used again.
4. Fall damage calculated based on the character's falling speed.
5. Shooting bullets by pressing the left mouse button.

