Here's an example of using emersion/go-imap with OAuth and Office 365 without using go-sasl:

1. Install the required packages:

```sh
go get github.com/emersion/go-imap
go get golang.org/x/oauth2
```

2. Create a file called `main.go` and add the following code:

```go
package main

import (
	"fmt"
	"log"

	"github.com/emersion/go-imap"
	"github.com/emersion/go-imap/client"
	"golang.org/x/oauth2"
)

func main() {
	accessToken, err := getAccessToken() // Replace this function with your own OAuth2 flow
	if err != nil {
		log.Fatalf("Failed to get access token: %v", err)
	}

	serverName := "outlook.office365.com:993"

	tlsConfig := &tls.Config{
		InsecureSkipVerify: false,
		ServerName:         serverName,
	}

	conn, err := tls.Dial("tcp", serverName, tlsConfig)
	if err != nil {
		log.Fatalf("Failed to dial: %v", err)
	}

	client, err := client.New(conn)
	if err != nil {
		log.Fatalf("Failed to create client: %v", err)
	}

	auth := &imap.OAuth2{
		Token:       accessToken,
		AuthHandler: handleAuth,
	}

	if err := client.Auth(auth); err != nil {
		log.Fatal("Error:", err)
	}

	// Connection is now authenticated and can be used to interact with the IMAP server
	// ...
}

func getAccessToken() (string, error) {
	// Replace this dummy token with a real OAuth2 token obtained for Office 365 IMAP access
	return "your-access-token", nil
}

func handleAuth(ir *imap.Resp) (imap.Literal, error) {
	resp := ir.String()

	if resp == "USER" {
		return imap.NewLiteral("your-email@your-domain.com"), nil
	}

	return nil, fmt.Errorf("unexpected server response: %s", resp)
}
```

Note: `getAccessToken()` function should be replaced with your actual OAuth2 flow, such as using the golang.org/x/oauth2 library, to acquire an access token from Office 365.

This example authenticates to the IMAP server with the OAuth access token, which should allow connecting without using go-sasl.

Для этого вы можете создать новый `THREE.Points` материал и использовать геометрию модели, а затем удалить старую меш и добавить новую в scene. Вот обновленный код с заменой меш на точки:

```javascript
import * as THREE from 'three';
import { GLTFLoader } from 'three/examples/jsm/loaders/GLTFLoader';

const scene = new THREE.Scene();

// добавление точечного света
const pointLight = new THREE.PointLight(0xffffff);
pointLight.position.set(25, 50, 25);
scene.add(pointLight);

// добавление амбиентного света
const ambientLight = new THREE.AmbientLight(0x404040);
scene.add(ambientLight);

const camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
const renderer = new THREE.WebGLRenderer();
renderer.setSize(window.innerWidth, window.innerHeight);
document.body.appendChild(renderer.domElement);

const loader = new GLTFLoader();
const url = 'particlesThree.glb';
loader.load(url, function (gltf) {
  const model = gltf.scene;

  // Замена геометрии на точки
  model.traverse((child) => {
    if (child.isMesh) {
      const geometry = child.geometry;
      const material = new THREE.PointsMaterial({
        color: 0xffffff,
        size: 0.1
      });
      const points = new THREE.Points(geometry, material);
      child.parent.add(points);
      child.parent.remove(child);
    }
  });

  model.scale.set(0.5, 0.5, 0.5);
  model.position.set(0, 0, 0);
  scene.add(model);

  // добавление анимации
  const mixer = new THREE.AnimationMixer(model);
  gltf.animations.forEach((clip) => {
    const action = mixer.clipAction(clip);
    action.play();
    // задаем повторение анимации
    action.setLoop(THREE.LoopRepeat, Infinity);
  });

  // установка позиции камеры
  camera.position.z = 5;
  // Обработчик события колесика мыши
  let cameraZ = camera.position.z;
  window.addEventListener('wheel', (event) => {
    cameraZ += event.deltaY * 0.003;
    camera.position.z = cameraZ;
    event.preventDefault();
  }, { passive: false });

  animate();

  function animate() {
    requestAnimationFrame(animate);
    mixer.update(0.01);
    renderer.render(scene, camera);
  }
});
```

Теперь геометрия модели будет заменена на точки. Учтите, что свет отражаться не будет, потому что `THREE.Points` не поддерживает освещение. Это общая особенность `THREE.Points`.

