To make this more interactive, I've created a simple game where sentence parts are scrambled, and you can drag them to reorder and form a correct sentence. The game selects a random sentence model and displays it scrambled. You can click and drag the words to rearrange them.

```js
let words = [];
let correctSentence;
let selectedWord = null;
const scoreElement = document.getElementById("score");

class Word {
  constructor(text, x, y) {
    this.text = text;
    this.x = x;
    this.y = y;
    this.width = textWidth(text) + 20;
    this.height = 40;
    this.isSelected = false;
  }

  display() {
    if (this.isSelected) {
      fill(150);
    } else {
      fill(255);
    }
    rect(this.x, this.y, this.width, this.height);
    fill(0);
    text(this.text, this.x + 10, this.y + 27);
  }
}

function setup() {
  createCanvas(800, 400);
  generateNewSentence();
}

function draw() {
  background(220);

  for (let word of words) {
    word.display();
  }

  if (selectedWord) {
    selectedWord.x = mouseX - selectedWord.width / 2;
    selectedWord.y = mouseY - selectedWord.height / 2;
  }
}

function mousePressed() {
  for (let word of words) {
    if (
      mouseX >= word.x &&
      mouseX <= word.x + word.width &&
      mouseY >= word.y &&
      mouseY <= word.y + word.height
    ) {
      word.isSelected = true;
      selectedWord = word;
      break;
    }
  }
}

function mouseReleased() {
  if (selectedWord) {
    selectedWord.isSelected = false;
    selectedWord = null;

    // Check if sentence ordering is correct
    let isCorrect = true;
    for (let i = 0; i < words.length - 1; ++i) {
      if (words[i].x > words[i + 1].x) {
        isCorrect = false;
        break;
      }
    }
    if (isCorrect) {
      alert("Congratulations! You formed the correct sentence!");
      generateNewSentence();
    }
  }
}

function generateNewSentence() {
  background(220);

  // Remove previous sentence's words
  words = [];

  // Create randomized sentence
  let model = random(sentenceModels);
  const regex = new RegExp(Object.keys(exampleData).join("|"), "g");
  correctSentence = model.replace(regex, (match) => random(exampleData[match]));

  console.log(correctSentence);

  textSize(24);
  textAlign(LEFT, CENTER);

  // Scramble the sentence
  let scrambledSentence = correctSentence
    .split(" ")
    .sort(() => 0.5 - Math.random())
    .join(" ");

  // Assign positions to words
  let x = 20;
  for (let text of scrambledSentence.split(" ")) {
    words.push(new Word(text, x, height / 2 - 20));
    x += textWidth(text) + 40;
  }
}
```

