```csharp
using UnityEngine;

public class ColliderScaler : MonoBehaviour
{
    [SerializeField] private Transform otherObject;

    private Collider otherCollider;
    private float initialRadius;

    private void Start()
    {
        // Получаем коллайдер другого объекта
        otherCollider = otherObject.GetComponent<Collider>();

        // Получаем начальный радиус коллайдера
        initialRadius = otherCollider.radius;
    }

    private void Update()
    {
        // Получаем текущий масштаб объекта, к которому привязан скрипт
        Vector3 currentScale = transform.localScale;

        // Вычисляем новый радиус для коллайдера
        float newRadius = initialRadius * Mathf.Max(currentScale.x, Mathf.Max(currentScale.y, currentScale.z));

        // Устанавливаем новый радиус для коллайдера
        otherCollider.radius = newRadius;
    }
}
```

