const Z1 = (1 + Math.sqrt(5)) / 2;

const VERTICES = [
  [-1, Z0, 0], [1, Z0, 0], [-1, -Z0, 0], [1, -Z0, 0],
  [0, -1, Z0], [0, 1, Z0], [0, -1, -Z0], [0, 1, -Z0],
  [Z0, 0, -1], [Z0, 0, 1], [-Z0, 0, -1], [-Z0, 0, 1]
];

let collectibles = [];
let targetRadius;

function setup() {
  createCanvas(windowWidth, windowHeight, WEBGL);
  targetRadius = 100;

  // Add initial collectibles with random positions and ages
  for (let i = 0; i < 10; i++) {
    collectibles.push({pos: createVector(random(-200, 200), random(-200, 200), random(-200, 200)), age: random(100, 255)});
  }
}

function draw() {
  background(200);

  // Rotate the Megaminx
  rotateX(frameCount * 0.01);
  rotateY(frameCount * 0.01);

  // Draw Megaminx
  drawMegaminx();

  // Draw collectibles
  for (const collectible of collectibles) {
    push();
    stroke(255, 255, 0, collectible.age);
    fill(255, 255, 0, collectible.age);
    translate(collectible.pos.x, collectible.pos.y, collectible.pos.z);
    sphere(2.5);
    pop();
  }

  // Collectible life fade out
  for (let i = 0; i < collectibles.length; i++) {
    collectibles[i].age -= 1;
    if (collectibles[i].age <= 0) {
      collectibles.splice(i, 1);
      i--;
      collectibles.push({pos: createVector(random(-200, 200), random(-200, 200), random(-200, 200)), age: 255});
    }
  }

  // Draw orbiting circle
  push();
  if (mouseIsPressed) {
    targetRadius = lerp(targetRadius, 57, 0.1);
  } else {
    targetRadius = lerp(targetRadius, 100, 0.1);
  }
  translate(0, 0, targetRadius);
  stroke(0); fill(255, 0, 0);
  sphere(5);
  pop();

  // Check for collisions with collectibles
  for (let i = 0; i < collectibles.length; i++) {
    const distance = dist(0, 0, targetRadius, collectibles[i].pos.x, collectibles[i].pos.y, collectibles[i].pos.z);
    if (distance <= 7.5) { // 7.5 is the sum of the sphere radii (5 for circle and 2.5 for collectible)
      collectibles.splice(i, 1);
      i--;
      collectibles.push({pos: createVector(random(-200, 200), random(-200, 200), random(-200, 200)), age: 255});
    }
  }
}

function drawPentagon() {
  push();
  beginShape();
  vertex(0, -0.5);
  vertex(0.5, -0.5);
  vertex(0.5, 0);
  vertex(0, 0.5);
  vertex(-0.5, 0);
  endShape(CLOSE);
  pop();
}

function drawMegaminx() {
  push();

  // Draw the first face
  stroke(0); fill(200, 200, 0);
  drawPentagon();

  // Draw the remaining faces
  for (let i = 0; i < VERTICES.length; i++) {
    push();
    translate(VERTICES[i][0] * 50, VERTICES[i][1] * 50, VERTICES[i][2] * 50);
    rotateY(Math.atan2(VERTICES[i][0], VERTICES[i][2]));
    rotateZ(Math.atan2(VERTICES[i][1], VERTICES[i][2]));
    drawPentagon();
    pop();
  }

  pop();
}
```

In this game, you will see a red orbiting circle around the rotating 3D shape. Yellow 5px circles spawn randomly, and the player must collect them by moving the red circle. When the mouse button is pressed, the red circle moves closer to the shape, allowing the player to collect the yellow circles. The yellow circles fade away over time and respawn, so the player must be quick to collect them.

