template <typename T, typename... Args>
void IMF_FORMAT(std::ostringstream& stream, std::string format, T const& first, Args const&... rest)
{
    for (size_t i = 0; i < format.length(); ++i)
    {
        if (format[i] == '%' && i + 1 < format.length())
        {
            if (format[i + 1] == '%')
