            }
            offlineQcDataMap.get(menuId).add(qcData);
        }
        offlineQcDataMap.forEach((menuId, offlineQcDataDOS) -> processOfflineQC(offlineQcDataDOS, Long.parseLong(menuId)));
        pageQO.setStartRow(pageQO.getStartRow() + pageQO.getPageSize());
    } while (CollectionUtils.isNotEmpty(offlineQcData));
}

/**
 * 处理offline qc数据
 * @param offlineQcDataDOS offline qc数据
 * @param menuId 菜单id
 */
public void processOfflineQC(List<OfflineQcDataDO> offlineQcDataDOS, long menuId) {
    MenuDO menuDO = findMenuAbility.findMenuByMenuId(menuId);
    String elementType = offlineQcDataDOS.get(0).getElementType();
    List<ElementModel> elementModels = offlineQcDataDOS.stream()
            .map(this::buildElementModelDataFromOfflineQcData)
            .peek(em -> {
                em.setAuditProductId(menuId);
                em.setElementType(elementType);
            })
            .collect(Collectors.toList());
    //批量入库
    String subBizType = "QC";
    doProcessBatchQC(elementModels, elementType, subBizType, menuDO);
}
```
主要优化：
1. 使用do-while循环代替传统的for循环，避免了重复计算startRow的值。
2. 精简代码逻辑，将部分条件语句合并，并使用forEach进行遍历。
3. 使用stream()和collect()一行代码完成List转化。

