#include <stdio.h>

// Function to print the spiral
void printSpiral(int end) {
    int start = 0, i;
    int n = end + 1;
    int a[n][n];

    while (start < end) {
        // Initialize the value to be printed
        int num = start;

        // Traverse right
        for (i = start; i <= end; i++) {
            a[start][i] = num % 10;
            num--;
        }

        // Traverse down
        for (i = start + 1; i <= end; i++) {
            a[i][end] = num % 10;
            num--;
        }

        // Traverse left
        for (i = end - 1; i >= start; i--) {
            a[end][i] = num % 10;
            num--;
        }

        // Traverse up
        for (i = end - 1; i > start; i--) {
            a[i][start] = num % 10;
            num--;
        }

        // Update the start and end
        start++;
        end--;
    }

    // Print the spiral
    for (i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            printf("%d ", a[i][j]);
        }
        printf("\n");
    }
}

int main() {
    // Create a spiral from 9 to 0
    printSpiral(9);

    return 0;
}
