    }

    AVLNode* addNode(AVLNode* node, Student* student) {
        if (node == nullptr) {
            return new AVLNode(student);
        }
        else if (node->data->id < student->id) {
            node->right = addNode(node->right, student);
        }
        else if (node->data->id > student->id) {
            node->left = addNode(node->left, student);
        }
        else {
            return node;
        }

        updateHeight(node);
        int balanceFactor = getBalanceFactor(node);

        if (balanceFactor > 1) {
            if (student->id < node->left->data->id) {
                return rotateRight(node);
            }
            else {
                node->left = rotateLeft(node->left);
                return rotateRight(node);
            }
        }
        else if (balanceFactor < -1) {
            if (student->id > node->right->data->id) {
                return rotateLeft(node);
            }
            else {
                node->right = rotateRight(node->right);
                return rotateLeft(node);
            }
        }

        return node;
    }

    AVLNode* removeNode(AVLNode* node, int id) {
        if (node == nullptr) {
            return node;
        }
        else if (node->data->id < id) {
            node->right = removeNode(node->right, id);
        }
        else if (node->data->id > id) {
            node->left = removeNode(node->left, id);
        }
        else {
            if (node->left == nullptr && node->right == nullptr) {
                delete node->data;
                delete node;
                node = nullptr;
            }
            else if (node->left == nullptr) {
                AVLNode* temp = node;
                node = node->right;
                delete temp->data;
                delete temp;
            }
            else if (node->right == nullptr) {
                AVLNode* temp = node;
                node = node->left;
                delete temp->data;
                delete temp;
            }
            else {
                AVLNode* temp = findMinNode(node->right);
                node->data = new Student(temp->data->id, temp->data->name, temp->data->department, temp->data->gpa);
                node->right = removeNode(node->right, temp->data->id);
            }
        }

        if (node == nullptr) {
            return node;
        }

        updateHeight(node);
        int balanceFactor = getBalanceFactor(node);

        if (balanceFactor > 1) {
            if (getBalanceFactor(node->left) >= 0) {
                return rotateRight(node);
            }
            else {
                node->left = rotateLeft(node->left);
                return rotateRight(node);
            }
        }
        else if (balanceFactor < -1) {
            if (getBalanceFactor(node->right) <= 0) {
                return rotateLeft(node);
            }
            else {
                node->right = rotateRight(node->right);
                return rotateLeft(node);
            }
        }

        return node;
    }

    AVLNode* findMinNode(AVLNode* node) {
        if (node == nullptr) {
            return nullptr;
        }
        else if (node->left == nullptr) {
            return node;
        }
        else {
            return findMinNode(node->left);
        }
    }

    AVLNode* searchNode(AVLNode* node, int id) {
        if (node == nullptr || node->data->id == id) {
            return node;
        }
        else if (node->data->id < id) {
            return searchNode(node->right, id);
        }
        else {
            return searchNode(node->left, id);
        }
    }

    void printAllNode(AVLNode* node) {
        if (node != nullptr) {
            printAllNode(node->left);
            cout << "ID: " << node->data->id << ", Name: " << node->data->name << ", GPA: " << node->data->gpa
                << ", Department: " << node->data->department << endl;
            printAllNode(node->right);
        }
    }

    void departmentReportNode(AVLNode* node, map<string, int>& deptCount) {
        if (node != nullptr) {
            departmentReportNode(node->left, deptCount);
            deptCount[node->data->department]++;
            departmentReportNode(node->right, deptCount);
        }
    }

public:
    AVLTree() : root(nullptr) {}

    ~AVLTree() {
        destroyTree(root);
    }

    void addStudent(int id, string name, string dept, float gpa) {
        Student* student = new Student(id, name, dept, gpa);
        root = addNode(root, student);
    }

    void removeStudent(int id) {
        root = removeNode(root, id);
    }

    void searchStudent(int id) {
        AVLNode* node = searchNode(root, id);
        if (node != nullptr) {
            cout << "ID: " << node->data->id << ", Name: " << node->data->name << ", GPA: " << node->data->gpa
                << ", Department: " << node->data->department << endl;
        }
        else {
            cout << "Student not found." << endl;
        }
    }

    void printAll() {
        cout << "Printing all students sorted by ID:" << endl;
        printAllNode(root);
        cout << endl;
    }

    void departmentReport() {
        map<string, int> deptCount;
        departmentReportNode(root, deptCount);
        cout << "Department Report:" << endl;
        for (auto& [dept, count] : deptCount) {
            cout << dept << ": " << count << endl;
        }
        cout << endl;
    }
};

