```cpp
#include <iostream>
#include <fstream>
#include <string>

// Abstract base class for serializable objects
class Serializable {
public:
    virtual ~Serializable() = default;

    // Serialize the object to a file
    virtual void save(const std::string &filename) const = 0;

    // Deserialize the object from a file
    virtual void load(const std::string &filename) = 0;
};

// Example game character class
class Character : public Serializable {
public:
    Character(std::string name = "", int level = 1, int hp = 100)
        : name(std::move(name)), level(level), hp(hp) {}

    // Getters
    const std::string &getName() const { return name; }
    int getLevel() const { return level; }
    int getHP() const { return hp; }

    // Implement Serializable interface
    void save(const std::string &filename) const override {
        std::ofstream output(filename, std::ios::binary);

        if (!output) {
            throw std::runtime_error("Unable to open file for writing.");
        }

        // Write name length, name, level, and health points
        size_t nameLength = name.size();
        output.write(reinterpret_cast<const char*>(&nameLength), sizeof(nameLength));
        output.write(name.c_str(), nameLength);
        output.write(reinterpret_cast<const char*>(&level), sizeof(level));
        output.write(reinterpret_cast<const char*>(&hp), sizeof(hp));

        output.close();
    }

    void load(const std::string &filename) override {
        std::ifstream input(filename, std::ios::binary);

        if (!input) {
            throw std::runtime_error("Unable to open file for reading.");
        }

        // Read name length, name, level, and health points
        size_t nameLength;
        input.read(reinterpret_cast<char*>(&nameLength), sizeof(nameLength));
        name.resize(nameLength);
        input.read(&name[0], nameLength);
        input.read(reinterpret_cast<char*>(&level), sizeof(level));
        input.read(reinterpret_cast<char*>(&hp), sizeof(hp));

        input.close();
    }

private:
    std::string name;
    int level;
    int hp;
};

int main() {
    // Create a character and save it
    Character player1("John Doe", 5, 100);
    player1.save("player1.bin");

    // Load a character from a file
    Character player2;
    player2.load("player1.bin");

    std::cout << "Loaded character:\n";
    std::cout << "Name: " << player2.getName() << "\n";
    std::cout << "Level: " << player2.getLevel() << "\n";
    std::cout << "Health Points: " << player2.getHP() << "\n";

    return 0;
}
```

In this example, the `Serializable` class is an abstract base class that other data type classes can inherit from to implement serialization and deserialization methods. The `Character` class, for instance, later implements these methods to save and load its custom data, leveraging the abstraction provided by the base class.

You can now add more game classes that inherit from `Serializable` and implement their own `save` and `load` methods, all while following the same interface, making the code cohesive and easy to maintain.

