```C++
#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

class Graph {
    int V;
    vector<pair<int, pair<int, int> > > edges;

public:
    Graph(int V) {
        this->V = V;
    }

    void addEdge(int u, int v, int w) {
        edges.push_back(make_pair(w, make_pair(u, v)));
    }

    int find(int parent[], int i) {
        if(parent[i] == -1) {
            return i;
        }
        return find(parent, parent[i]);
    }

    void unionset(int parent[], int x, int y) {
        int xset = find(parent, x);
        int yset = find(parent, y);
        parent[xset] = yset;
    }

    void Kruskal() {
        vector<pair<int, pair<int, int> > > MST;
        int parent[V];
        memset(parent, -1, sizeof(parent));
        sort(edges.begin(), edges.end());
        int edgeCount = 0;

        for(auto i = edges.begin(); i != edges.end(); i++) {
            int u = i->second.first;
            int v = i->second.second;
            int weight = i->first;

            int set_u = find(parent, u);
            int set_v = find(parent, v);

            if(set_u != set_v) {
                MST.push_back(make_pair(weight, make_pair(u, v)));
                unionset(parent, set_u, set_v);
                edgeCount++;
                if(edgeCount == V - 1) {
                    break;
                }
            }
        }

        cout << "Minimum Spanning Tree:\n";
        for(auto i = MST.begin(); i != MST.end(); i++) {
            cout << i->second.first << " - " << i->second.second << " : " << i->first << endl;
        }
    }
};

int main() {
    Graph g(6);

    g.addEdge(0, 1, 4);
    g.addEdge(0, 2, 2);
    g.addEdge(0, 5, 6);
    g.addEdge(1, 2, 1);
    g.addEdge(1, 5, 7);
    g.addEdge(2, 3, 3);
    g.addEdge(2, 4, 8);
    g.addEdge(3, 4, 6);
    g.addEdge(4, 5, 5);

    g.Kruskal();

    return 0;
}
```

This implementation uses `vector` to store the graph edges and `pair` to represent each edge. The `find` and `unionset` functions are used in Kruskal's algorithm to check and assign parent nodes accordingly. The `Kruskal` function sorts and traverses through the edges to build the minimum spanning tree and then outputs the results.

