```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>
#include <fcntl.h>
#include "huffman.h"

#define READ_END 0
#define WRITE_END 1

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s [input_file] [output_file]\n", argv[0]);
        return 1;
    }

    int freq_pipe[2], encode_pipe[2], decode_pipe[2];
    pid_t pid;
    unsigned int freq[128] = {0};
    char *in_file = argv[1];
    char *out_file = argv[2];

    if (pipe(freq_pipe) == -1) {
        fprintf(stderr, "Error: frequency pipe failed\n");
        return 1;
    }
    if (pipe(encode_pipe) == -1) {
        fprintf(stderr, "Error: encoding pipe failed\n");
        return 1;
    }
    if (pipe(decode_pipe) == -1) {
        fprintf(stderr, "Error: decoding pipe failed\n");
        return 1;
    }

    pid = fork();
    if (pid < 0) {
        fprintf(stderr, "Error: fork failed\n");
        return 1;
    } else if (pid == 0) { // child process
        close(freq_pipe[WRITE_END]); // close unused write end
        import_file(fopen(in_file, "r"), freq, freq_pipe); // calculate frequencies and send data to parent process
        close(encode_pipe[READ_END]); // close unused read end
        encode(fopen(in_file, "r"), fdopen(encode_pipe[WRITE_END], "w"), freq); // encode file and send data to parent process
        close(decode_pipe[WRITE_END]); // close unused write end
        decode(fdopen(decode_pipe[READ_END], "r"), fdopen(fopen(out_file, "w"), "w"), freq); // decode file and save to output file
        return 0;
    } else { // parent process
        close(freq_pipe[READ_END]); // close unused read end
        close(encode_pipe[WRITE_END]); // close unused write end
        close(decode_pipe[READ_END]); // close unused read end

        FILE *input_fp = fopen(in_file, "r");
        if (!input_fp) {
            fprintf(stderr, "Error: unable to open input file '%s'\n", in_file);
            return 1;
        }
        FILE *output_fp = fopen(out_file, "w");
        if (!output_fp) {
            fprintf(stderr, "Error: unable to open output file '%s'\n", out_file);
            return 1;
        }

        unsigned int freq_copy[128]; // copy of frequency data received from child process
        close(freq_pipe[WRITE_END]); // close unused write end
        read(freq_pipe[READ_END], freq_copy, 128 * sizeof(unsigned int)); // read frequency data from child process
        close(freq_pipe[READ_END]); // close read end
        memcpy(freq, freq_copy, 128 * sizeof(unsigned int)); // copy frequency data to global variable

        encode(fopen(in_file, "r"), fdopen(encode_pipe[WRITE_END], "w"), freq); // encode file and write to pipe
        close(encode_pipe[WRITE_END]); // done writing to pipe
        fseek(input_fp, 0, SEEK_END); // seek to end of input file to determine original file size
        long original_size = ftell(input_fp);
        rewind(input_fp); // seek back to beginning of input file
        unsigned int encoded_size;
        fscanf(fdopen(encode_pipe[READ_END], "r"), "%04u\n", &encoded_size); // read encoded size from pipe
        char encoded_header[6];
        sprintf(encoded_header, "%04u\n", encoded_size);
        fwrite(encoded_header, sizeof(char), strlen(encoded_header), output_fp); // write encoded size header to output file
        char *encode_buf = (char *)malloc((encoded_size / 8 + 1) * sizeof(char));
        fread(encode_buf, sizeof(char), encoded_size / 8 + 1, fdopen(encode_pipe[READ_END], "r")); // read encoded data from pipe
        fwrite(encode_buf, sizeof(char), encoded_size / 8 + 1, output_fp); // write encoded data to output file
        free(encode_buf); // free temporary buffer for encoded data
        close(encode_pipe[READ_END]); // done reading from pipe

        char decode_header[5];
        sprintf(decode_header, "%ld\n", original_size);
        fwrite(decode_header, sizeof(char), strlen(decode_header), fdopen(decode_pipe[WRITE_END], "w")); // write original size header to pipe
        char decode_buf[1024];
        int num_read;
        while ((num_read = fread(decode_buf, sizeof(char), 1024, input_fp)) > 0) { // read input file in chunks of 1KB and write encoded output to pipe
            for (int i = 0; i < num_read; i++) {
