The issue is happening because the source of the gif is not getting reloaded after the first two times, causing it to not play the gif animation. One way to resolve this is by adding a cache buster (or a random query parameter) to the gif src. Here's the modified function:

```javascript
function toggleDarkMode() {
  const body = document.querySelector("body");
  const button = document.querySelector(".darki");
  const currentMode = button.classList.contains("dark-mode") ? "dark" : "light";
  body.classList.toggle("dark-mode");
  button.classList.toggle("dark-mode");

  // Check if the button is in "dark mode" and set the appropriate image and animation
  if (button.classList.contains("dark-mode")) {
    const gif = document.createElement("img");
    gif.classList.add("img1");
    gif.src = "./img/animated_button.gif?cache=" + new Date().getTime();
    button.querySelector(".img1").replaceWith(gif);
  } else {
    const gif = document.createElement("img");
    gif.classList.add("img1");
    gif.src = "./img/reverse_animated_button.gif?cache=" + new Date().getTime();
    button.querySelector(".img1").replaceWith(gif);
  }
}
```

