/*
 * PASO_DATA structure to track rooms visited while finding the shortest path.
 */
typedef struct paso_data PASO_DATA;
struct paso_data
{
    PASO_DATA *next;
    PASO_DATA *prev;
    ROOM_INDEX_DATA *room;
    char dir;
    int num;
};

/* Helper functions to manage PASO_DATA */
PASO_DATA *nuevo_paso(void);
void liberar_paso(PASO_DATA *paso);
void paso_enlazar(ROOM_INDEX_DATA *room, char dir, int num);
void paso_desenlazar(void);
void liberar_pasos(void);

static PASO_DATA *primer_paso = NULL;
static PASO_DATA *ultimo_paso = NULL;

/* Error codes */
#define paso_error        -1
#define paso_en_destino   -2
#define paso_sin_camino   -3

/*
 * Create a new PASO_DATA instance and initialize its variables.
 */
PASO_DATA *nuevo_paso(void)
{
    PASO_DATA *paso = NULL;

    CREATE(paso, PASO_DATA, 1);

    paso->next = NULL;
    paso->prev = NULL;
    paso->room = NULL;
    paso->dir = '\0';
    paso->num = 0;

    return paso;
}

/*
 * Free a PASO_DATA instance.
 */
void liberar_paso(PASO_DATA *paso)
{
    if (!paso)
        return;

    paso->next = NULL;
    paso->prev = NULL;
    paso->room = NULL;
    paso->dir = '\0';
    DISPOSE(paso);
}

/*
 * Add PASO_DATA instances at the end of the linked list.
 */
void paso_enlazar(ROOM_INDEX_DATA *room, char dir, int num)
{
    PASO_DATA *actual = NULL;

    actual = nuevo_paso();
    if (!actual)
    {
        BUG("actual NULL after nuevo_paso()");
        return;
    }
    actual->room = room;
    actual->dir = dir;
    actual->num = num;
    if (ultimo_paso)
        actual->num++;

    LINK(actual, primer_paso, ultimo_paso, prev, next);
}

/*
 * Remove PASO_DATA instances from the start of the linked list.
 */
void paso_desenlazar(void)
{
    PASO_DATA *actual = NULL;

    actual = primer_paso;
    UNLINK(actual, primer_paso, ultimo_paso, prev, next);
    liberar_paso(actual);
}

/*
 * Free all PASO_DATA instances in the linked list.
 */
void liberar_pasos(void)
{
    while (primer_paso)
        paso_desenlazar();
}

/*
 * Find and return the shortest distance between two rooms using BFS, given constraints.
 */
int distancia_mapa(CHAR_DATA *ch, ROOM_INDEX_DATA *origen, ROOM_INDEX_DATA *destino, int distancia_max, int *direccion, bool Area)
{
    EXIT_DATA *salida = NULL;
    int cantidad;
    int dir;
    int distancia;
    bool visitada[40000] = {FALSE};

    if (!origen)
    {
        BUG("origen NULL");
        *direccion = paso_error;
        return paso_error;
    }

    if (!destino)
    {
        BUG("origen NULL");
        *direccion = paso_error;
        return paso_error;
    }

    if (origen == destino)
    {
        *direccion = paso_en_destino;
        return paso_en_destino;
    }

    if (Area && origen->area != destino->area)
    {
        *direccion = paso_sin_camino;
        return paso_sin_camino;
    }

    visitada[origen->vnum] = TRUE;

    /* Enqueue the initial steps and their corresponding directions */
    for (dir = DIR_NORTE; dir < MAX_DIR; dir++)
    {
        salida = origen->exit[dir];
        if (visitable(ch, salida, Area))
        {
            if (visitada[salida->to_room->vnum] == FALSE)
            {
                visitada[salida->to_room->vnum] = TRUE;
                paso_enlazar(salida->to_room, dir, 0);
                primer_paso->num = 1;

                if (primer_paso->room == destino)
                {
                    *direccion = primer_paso->dir;
                    distancia = 1;
                    liberar_pasos();
                    return distancia;
                }
            }
        }
    }

    cantidad = 0;
    while (primer_paso)
    {
        if (primer_paso->num > distancia_max || cantidad++ > 100000)
        {
            liberar_pasos();
            *direccion = paso_sin_camino;
            return paso_sin_camino;
        }
        if (primer_paso->room == destino)
        {
            *direccion = primer_paso->dir;
            distancia = primer_paso->num;
            liberar_pasos();
            return distancia;
        }
        else
        {
            for (dir = DIR_NORTE; dir < MAX_DIR; dir++)
            {
                salida = primer_paso->room->exit[dir];
                if (visitable(ch, salida, Area))
                {
                    if (visitada[salida->to_room->vnum] == FALSE)
                    {
                        visitada[salida->to_room->vnum] = TRUE;
                        paso_enlazar(salida->to_room, primer_paso->dir, primer_paso->num);
                    }
                }
            }
            paso_desenlazar();
        }
    }

    *direccion = paso_sin_camino;
    return paso_sin_camino;
}
