    const easing = (t) => {
      if (t < 0.5) {
        return 4 * t * t * t;
      } else {
        return 1 - Math.pow(-2 * t + 2, 3) / 2;
      }
    };

    let start;

    if (!diff) return;

    window.requestAnimationFrame(function step(timestamp) {
      if (!start) start = timestamp;
      const time = timestamp - start;
      let progress = Math.min(time / duration, 1);
      progress = easing(progress);

      window.scrollTo(0, startingY + diff * progress);

      if (time < duration) {
        window.requestAnimationFrame(step);
      } else {
        isAnimating = false;
      }
    });
  }

  function handleScroll(event) {
    if (isAnimating) {
      event.preventDefault();
      return;
    }

    const deltaY = event.deltaY;
    const currentSectionIndex = Math.round(window.scrollY / window.innerHeight);

    if (deltaY > 0) {
      const nextSection = sections[currentSectionIndex + 1];
      if (nextSection) {
        event.preventDefault();
        isAnimating = true;
        scrollToElement(nextSection, 1000);
      }
    } else if (deltaY < 0) {
      const prevSection = sections[currentSectionIndex - 1];
      if (prevSection) {
        event.preventDefault();
        isAnimating = true;
        scrollToElement(prevSection, 1000);
      }
    }
  }

  window.addEventListener("wheel", handleScroll, { passive: false });
})();
