In this case, since the keys are not only numbers, we can modify the function to find the non-string values for the key and the string values for keyValue. Here's the modified function:

```javascript
function toArrayToObject(array) {
  const resultObject = {};

  array.forEach(element => {
    let key, keyValue;

    Object.entries(element).forEach(([property, value]) => {
      if (typeof value === "string" && !isNaN(Number(value))) {
        key = value;
      } else if (typeof value === "string") {
        keyValue = value;
      }
    });

    resultObject[key] = keyValue;
  });

  return resultObject;
}

