    services.AddMassTransit(x =>
    {
        x.AddSagaStateMachine<SampleStateMachine, SampleState>()
            .MongoDbRepository(r =>
            {
                r.Connection = Configuration.GetConnectionString("MongoDatabase");
                r.DatabaseName = "SagaRepository";
            });

        x.UsingRabbitMq((context, cfg) =>
