    public string Reason { get; set; }
}
```

4. State Machine Class:
```csharp
public class OrderStateMachine : MassTransitStateMachine<OrderState>
{
    public OrderStateMachine()
    {
        Event(() => OrderSubmitted, x => x.CorrelateById(m => m.Message.OrderId));
        Event(() => OrderAccepted, x => x.CorrelateById(m => m.Message.OrderId));
        Event(() => OrderCancelled, x => x.CorrelateById(m => m.Message.OrderId));

        InstanceState(x => x.CurrentState);

        Initially(
            When(OrderSubmitted)
                .Then(context =>
                {
                    context.Instance.CustomerId = context.Data.CustomerId;
                    // Other properties
                })
                .TransitionTo(Submitted));

        During(Submitted,
            When(OrderAccepted)
                .Then(context =>
                {
                    // Perform necessary actions upon accepting the order
                })
                .TransitionTo(Accepted));

        During(Submitted,
            When(OrderCancelled)
                .Then(context =>
                {
                    // Perform necessary actions upon cancelling the order
                })
                .TransitionTo(Cancelled));

    }

    public State Submitted { get; private set; }
    public State Accepted { get; private set; }
    public State Cancelled { get; private set; }
    public Event<IOrderSubmitted> OrderSubmitted { get; private set; }
    public Event<IOrderAccepted> OrderAccepted { get; private set; }
    public Event<IOrderCancelled> OrderCancelled { get; private set; }
}
```

