```javascript
// Require dependencies
const express = require('express');
const path = require('path');
const mysql = require('mysql');
const http = require('http');
const socketio = require('socket.io');

// Create Express app
const app = express();

// Create server
const server = http.createServer(app);

// Set up Socket.IO
const io = socketio(server);

// Set up database connection
const connection = mysql.createConnection({
  host: 'localhost',
  user: 'root',
  password: 'root',
  database: 'flight_information'
});

// Connect to database
connection.connect();

// Set up SQL query to retrieve flight information
const query = 'SELECT * FROM flights';

// Set up Socket.IO event listener
io.on('connection', (socket) => {
  console.log('New client connected');

  // Send latest flight information to client on connection
  connection.query(query, (error, results) => {
    if (error) throw error;
    socket.emit('flightData', results);
  });

  // Send updated flight information to client when database changes
  connection.on('change', () => {
    connection.query(query, (error, results) => {
      if (error) throw error;
      socket.emit('flightData', results);
    });
  });
});

// Set up route to render flight information using EJS template
app.get('/', (req, res) => {
  connection.query(query, (error, results) => {
    if (error) throw error;
    res.render('index.ejs', { flights: results });
  });
});

// Set up EJS as view engine
app.set('view engine', 'ejs');
app.set('views', path.join(__dirname, 'views'));

