2. Create a JavaScript file (script.js) to handle file uploading, image preview, and navigation between images:

```javascript
const fileInput = document.getElementById("fileInput");
const prevButton = document.getElementById("prevButton");
const nextButton = document.getElementById("nextButton");
const imagePreview = document.getElementById("imagePreview");

let images = [];
let currentImageIndex = -1;

fileInput.addEventListener("change", handleFileUpload);
prevButton.addEventListener("click", showPrevImage);
nextButton.addEventListener("click", showNextImage);

function handleFileUpload() {
  images = Array.from(fileInput.files).filter((file) =>
    file.type.startsWith("image/")
  );
  currentImageIndex = -1;

  if (images.length > 0) {
    currentImageIndex = 0;
    showImage();
    updateNavigationButtons();
  } else {
    imagePreview.innerHTML = "No image to preview";
    prevButton.disabled = true;
    nextButton.disabled = true;
  }
}

function showImage() {
  if (currentImageIndex >= 0 && currentImageIndex < images.length) {
    const reader = new FileReader();
    reader.onload = (e) => {
      imagePreview.innerHTML = `<img src="${e.target.result}" alt="Preview">`;
    };
    reader.readAsDataURL(images[currentImageIndex]);
  } else {
    imagePreview.innerHTML = "No image to preview";
  }
}

function showPrevImage() {
  if (currentImageIndex > 0) {
    currentImageIndex--;
    showImage();
    updateNavigationButtons();
  }
}

function showNextImage() {
  if (currentImageIndex < images.length - 1) {
    currentImageIndex++;
    showImage();
    updateNavigationButtons();
  }
}

function updateNavigationButtons() {
  prevButton.disabled = currentImageIndex === 0;
  nextButton.disabled = currentImageIndex === images.length - 1;
}
```

