function dragRectangle(event) {
  if (draggedRectangles.length > 0) {
    const gameBoard = document.getElementById("game-board");
    const boardRect = gameBoard.getBoundingClientRect();
    const columnWidth = gameBoard.offsetWidth / boardWidth;

    const newColumnIndex = Math.floor((event.clientX - boardRect.left) / columnWidth);

    const lastNonColoredRectangle = getLastNonColoredRectangle(newColumnIndex);
    if (lastNonColoredRectangle) {
      const rowIndex = Math.floor(
        Array.from(document.getElementsByClassName('rectangle')).indexOf(lastNonColoredRectangle) / boardWidth
      );

      draggedRectangles.forEach((draggedRectangle, i) => {
        const index = (rowIndex - i) * boardWidth + newColumnIndex;
        const rectangles = document.getElementsByClassName("rectangle");
        const targetRectangle = rectangles[index];

        if (!targetRectangle.style.backgroundColor) {
          draggedRectangles[i] = targetRectangle;
          draggedRectangle.style.left = newColumnIndex * columnWidth + 'px';
          draggedRectangle.style.top = (rowIndex - i) * draggedRectangle.offsetHeight + 'px';
        }
      });
    }
  }
}
