using System;

namespace PayrollProcessing
{
    class Program
    {
        static void Main(string[] args)
        {
            double totalGrossPay = 0, totalTaxes = 0, totalNetPay = 0;
            bool runProgram = true;

            while (runProgram)
            {
                Console.Write("Enter the employee's name: ");
                string employeeName = Console.ReadLine();

                Console.Write("Enter the employee's pay rate: ");
                double payRate = ReadPositiveDouble("Invalid pay rate. Please enter a positive number.");

                Console.Write("Enter the hours worked: ");
                double hoursWorked = ReadPositiveDouble("Invalid hours. Please enter a positive number.");

                double grossPay = payRate * hoursWorked;
                double taxRate = CalculateTaxRate(grossPay);
                double taxes = grossPay * taxRate;
                double netPay = grossPay - taxes;

                Console.WriteLine("\nEmployee Pay Summary:");
                Console.WriteLine($"Name: {employeeName}");
                Console.WriteLine($"Gross Pay: {grossPay:C2}");
                Console.WriteLine($"Taxes Withheld: {taxes:C2}");
                Console.WriteLine($"Net Pay: {netPay:C2}\n");

                totalGrossPay += grossPay;
                totalTaxes += taxes;
                totalNetPay += netPay;

                Console.Write("Enter data for another employee? (y/n): ");
                char userInput = Console.ReadKey().KeyChar;
                if (userInput != 'y' && userInput != 'Y')
                {
                    runProgram = false;
                }
                Console.WriteLine("\n");
            }

            Console.WriteLine("\nTotal Gross Pay: " + totalGrossPay.ToString("C2"));
            Console.WriteLine("Total Taxes: " + totalTaxes.ToString("C2"));
            Console.WriteLine("Total Net Pay: " + totalNetPay.ToString("C2"));
        }

        static double ReadPositiveDouble(string errorMessage)
        {
            double number;
            while (!double.TryParse(Console.ReadLine(), out number) || number <= 0)
            {
                Console.WriteLine(errorMessage);
            }
            return number;
        }

        static double CalculateTaxRate(double grossPay)
        {
            if (grossPay >= 2000)
            {
                return 0.20;
            }
            else if (grossPay >= 1000)
            {
                return 0.15;
            }
            else
            {
                return 0.10;
            }
        }
    }
}
