  private updateBookList(): void {
    const bookTable = document.querySelector("#book-table");
    const books = this.bookService.getBooks();

    // Clear existing rows
    while (bookTable?.firstChild) {
      bookTable.firstChild.remove();
    }

    // Add new rows for each book in the `BookService`
    books.forEach(book => {
      const newRow = document.createElement("tr");

      // Add cell for each book property
      newRow.appendChild(this.createTableCell(book.id));
