      newRow.appendChild(this.createTableCell(book.price));

      bookTable?.appendChild(newRow);
    });
  }

  private createTableCell(value: string | number): HTMLTableCellElement {
    const cell = document.createElement("td");
    cell.textContent = value.toString();
    return cell;
  }
}
