    double largestThickness = -1;
    int indexOfLargest = -1;
    int indexOfTarget = -1;

    for(int i = 0; i < dataList.length; i++) {
        if(dataList[i].getThickness() > largestThickness) {
            largestThickness = dataList[i].getThickness();
            indexOfLargest = i;
        }

        if(dataList[i].getThickness() == 4.63) {
            indexOfTarget = i;
        }
