    for (int i = 0; i < selectionSort.length - 1; i++) {
        int minIndex = i;
        for (int j = i + 1; j < selectionSort.length; j++) {
            if (selectionSort[j].getThickness() < selectionSort[minIndex].getThickness()) {
                minIndex = j;
            }
        }

        if (minIndex != i) {
            Entry temp = selectionSort[i];
            selectionSort[i] = selectionSort[minIndex];
            selectionSort[minIndex]= temp;
        }
    }

    for (Entry e : selectionSort) {
        System.out.println(e);
    }

    System.out.println("\nSorted data using an insertion sort:");

    // Insertion Sort
    for (int i = 1; i < insertionSort.length; i++) {
        Entry key = insertionSort[i];
        int j = i - 1;

        while (j >= 0 && insertionSort[j].getThickness() > key.getThickness()) {
            insertionSort[j + 1] = insertionSort[j];
            j = j - 1;
        }

        insertionSort[j + 1] = key;
    }

    for (Entry e : insertionSort) {
        System.out.println(e);
    }
}
