Here's the complete modified `main()` method with the added code for capturing the running times for each algorithm:

```java
public static void main(String[] args) {
    DataHelper helper = new DataHelper(50);
    Entry[] dataList = helper.getData();
    Entry[] selectionSort = new Entry[50];
    Entry[] insertionSort = new Entry[50];

    for (int i = 0; i < dataList.length; i++) {
        selectionSort[i] = dataList[i];
        insertionSort[i] = dataList[i];
    }

    System.out.println(dataList[0] + "\n" + selectionSort[0] + "\n" + insertionSort[0] + "\n");

    // Linear Search
    long linearSearchStartTime = System.nanoTime();
    double largestThickness = -1;
    int indexOfLargest = -1;
    int indexOfTarget = -1;

    for(int i = 0; i < dataList.length; i++) {
        if(dataList[i].getThickness() > largestThickness) {
            largestThickness = dataList[i].getThickness();
            indexOfLargest = i;
        }

        if(dataList[i].getThickness() == 4.63) {
            indexOfTarget = i;
        }
    }

    System.out.println("Largest Ice Thickness: " + dataList[indexOfLargest]);
    if (indexOfTarget != -1) {
        System.out.println("Item with 4.63 thickness: " + dataList[indexOfTarget]);
    } else {
        System.out.println("Item with 4.63 thickness not found.");
    }
    long linearSearchEndTime = System.nanoTime();
    long linearSearchTime = linearSearchEndTime - linearSearchStartTime;
    System.out.println("Linear Search Time: " + linearSearchTime + " nanoseconds");

    System.out.println("Sorted data using a selection sort:");

    // Selection Sort
    long selectionSortStartTime = System.nanoTime();
    for (int i = 0; i < selectionSort.length - 1; i++) {
        int minIndex = i;
        for (int j = i + 1; j < selectionSort.length; j++) {
            if (selectionSort[j].getThickness() < selectionSort[minIndex].getThickness()) {
                minIndex = j;
            }
        }

        if (minIndex != i) {
            Entry temp = selectionSort[i];
            selectionSort[i] = selectionSort[minIndex];
            selectionSort[minIndex]= temp;
        }
    }

    // print out the sorted data
    for (Entry e : selectionSort) {
        System.out.println(e);
    }
    long selectionSortEndTime = System.nanoTime();
    long selectionSortTime = selectionSortEndTime - selectionSortStartTime;
    System.out.println("Selection Sort Time: " + selectionSortTime + " nanoseconds");

    System.out.println("\nSorted data using an insertion sort:");

    // Insertion Sort
    long insertionSortStartTime = System.nanoTime();
    for (int i = 1; i < insertionSort.length; i++) {
        Entry key = insertionSort[i];
        int j = i - 1;

        while (j >= 0 && insertionSort[j].getThickness() > key.getThickness()) {
            insertionSort[j + 1] = insertionSort[j];
            j = j - 1;
        }

        insertionSort[j + 1] = key;
    }

    // print out the sorted data
    for (Entry e : insertionSort) {
        System.out.println(e);
    }
    long insertionSortEndTime = System.nanoTime();
    long insertionSortTime = insertionSortEndTime - insertionSortStartTime;
    System.out.println("Insertion Sort Time: " + insertionSortTime + " nanoseconds");
}
```

