Board::Board(QWidget *parent)
    : QGraphicsView(parent)
{
    scene = new QGraphicsScene(this);
    setScene(scene);
    setRenderHint(QPainter::Antialiasing);

    squareSize = 50;

    createGrid();
    positionSquares();
}

void Board::createGrid()
{

    for (int i = 0; i < 10; ++i) {
        for (int j = 0; j < 10; ++j) {
            squares[i][j] = new Square(Qt::gray, squareSize);
            scene->addItem(squares[i][j]);
            squares[i][j]->setPos(j * squareSize, i * squareSize);
        }
    }

}

void Board::positionSquares()
{
    const int margin = 10;
    qreal viewWidth = width() - 2 * margin;
    qreal viewHeight = height() - 2 * margin;

    qreal squareWidth = viewWidth / 10;
    qreal squareHeight = viewHeight / 10;

    for (int i = 0; i < 10; ++i) {
        for (int j = 0; j < 10; ++j) {
            squares[i][j]->setPos(margin + j * squareWidth, margin + i * squareHeight);
            squares[i][j]->setScale(squareWidth / squareSize);
        }
    }
}


