// Pin Definitions
const int pbPin = 2;
const int ledPins[] = {3, 4, 5, 6};
const int numLeds = sizeof(ledPins) / sizeof(ledPins[0]);

// Variables
bool pbClosed; // Pushbutton status
unsigned long lastTime; // For LED time delay
unsigned long delayTime; // Delay in milliseconds

void setup() {
  pinMode(pbPin, INPUT_PULLUP);

  for (int i = 0; i < numLeds; i++) {
    pinMode(ledPins[i], OUTPUT);
  }

  lastTime = millis();
}

void loop() {
  pbClosed = digitalRead(pbPin) == LOW;

  if (pbClosed) {
    delayTime = 100; // 100ms for LEDs blinking
    toggleLedsAll();
  } else {
    delayTime = 250; // 250ms for LEDs flashing alternately
    toggleLedsAlternate();
  }

  delay(delayTime);
}

void toggleLedsAll() {
  for (int i = 0; i < numLeds; i++) {
    digitalWrite(ledPins[i], !digitalRead(ledPins[i]));
  }
}

void toggleLedsAlternate() {
  static bool highWeight = true;

  for (int i = 0; i < numLeds; i++) {
