#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include "ADT_binary_search_tree.h"

// Helper function to generate a random integer between min and max
int random_int(int min, int max) {
    return rand() % (max - min + 1) + min;
}

// Shuffle function to randomize the order of `packet_seq`
void shuffle(TipoItem *packet_seq, int len) {
    for (int i = 0; i < len; i++) {
        int random_idx = random_int(i, len - 1);
        TipoItem temp = packet_seq[i];
        packet_seq[i] = packet_seq[random_idx];
        packet_seq[random_idx] = temp;
    }
}

int main() {
    char original_message[100];
    TipoCelula *tree;
    TipoItem packet_seq[1000];
    int total_packets = 0;

    // Seed random number generator
    srand(time(0));

    // 1 - ask the user to enter a message to be transmitted over the network
    printf("Enter a message to be transmitted: ");
    fgets(original_message, sizeof(original_message), stdin);

    // 2 - print the message
    printf("Original message: %s\n", original_message);

    // 3 - fragment the message so that each character represents a packet to be transmitted
    for (int i = 0; original_message[i] != '\n' && original_message[i] != '\0'; i++) {
        // 4 - generate a random int between 1 and 10 to determine the replication count
        int replication_count = random_int(1, 10);

        // Add packets to packet_seq
        for (int j = 0; j < replication_count; j++) {
            packet_seq[total_packets].chave = i;
            packet_seq[total_packets].pacote = original_message[i];
            total_packets++;
        }
    }

    // 5 - generate a new sequence of packets with both original and replicated packets scrambled
    shuffle(packet_seq, total_packets);

    // 6 - print the new packet sequence
    printf("New packet sequence: \n");
    for (int i = 0; i < total_packets; i++) {
        printf("%c %d\n", packet_seq[i].pacote, packet_seq[i].chave);
    }

    // 7 - build the binary search tree from the new sequence of packets
    CriaArvoreBinariaBuscaVazia(&tree);
    for (int i = 0; i < total_packets; i++) {
        InsereArvoreBinariaBusca(&tree, packet_seq[i]);
    }

    // 8 - print the tree
    printf("Binary search tree: \n");
    ImprimeArvoreBinariaBusca(&tree, 0);

    // 9 - reconstruct the original message from the binary search tree
    char reconstructed_message[100] = {0};
    for (int i = 0; i < 100; i++) {
        TipoItem *item = BuscaArvoreBinariaBusca(&tree, i);
        if (item) {
            reconstructed_message[i] = item->pacote;
        }
    }

    // 10 - print the message
    printf("Reconstructed message: %s\n", reconstructed_message);

    return 0;
}
