        if (digitalRead(STOP_Pin) == LOW) {
            Serial.println("ST. ON");
            digitalWrite(STARTER_Pin, HIGH);
            delay(StTime);
            digitalWrite(STARTER_Pin, LOW);
            Serial.println("ST. OFF");
            delay(6000);
        }
    }
    if (VoltRead() > Vstart) {
        Serial.println("VBAT OK");
        heating = true;
    } else {
        heatingstop();
    }

    Serial.println("OUT");
    interval = 1;
}

float VoltRead() {
    float ADCC = analogRead(BAT_Pin);
    ADCC = ADCC / m;
    Serial.print("АКБ: ");
    Serial.print(ADCC);
    Serial.println("V");
    if (ADCC < V_min) {
        V_min = ADCC;
    }
    return (ADCC);
}

void heatingstop() {
    digitalWrite(SECOND_P, LOW);
    delay(100);
    digitalWrite(FIRST_P_Pin, LOW);
    delay(100);
    digitalWrite(IMMO, LOW);
    delay(100);
    digitalWrite(K5, LOW);
    digitalWrite(13, LOW);
    heating = false;
    Timer = 0;
    Serial.println("All OFF");
}

void detection() {
    Vbat = VoltRead();
    Serial.print("Инт:");
    Serial.println(interval);
    inDS = 0;
    sensors.requestTemperatures();
    while (inDS < 10) {
        TempDS[inDS] = sensors.getTempCByIndex(inDS);
        if (TempDS[inDS] == -127.00) {
            TempDS[inDS] = 80;
            break;
        }
        inDS++;
    }

    for (int i = 0; i < inDS; i++) {
        Serial.print("Temp");
        Serial.print(i);
        Serial.print("= ");
        Serial.println(TempDS[i]);
    }
    Serial.println("");

    if (heating == true && Timer < 1) {
        heatingstop();
    }

    interval--;
    if (interval < 1) {
        interval = 6; // Poll timer
    }
}

void blocking(bool st) {
    digitalWrite(st ? Lock_Pin : Unlock_Pin, HIGH);
    delay(500);
    digitalWrite(st ? Lock_Pin : Unlock_Pin, LOW);
    Security = st;
    Serial.println(st ? "На охране" : "Открыто");
}
