```javascript
function isColliding(x, y, width, height) {
  for (const obstacle of obstacles) {
    if (
      x < obstacle.x + obstacle.width &&
      x + width > obstacle.x &&
      y < obstacle.y + obstacle.height &&
      y + height > obstacle.y
    ) {
      return true;
    }
  }
  return false;
}

function checkCollision() {
  // Player Obstacle Collision
  if (isColliding(playerX, playerY, PLAYER_RADIUS * 2, PLAYER_RADIUS * 2)) {
    if (playerSpeedY > 0) {
      playerY -= playerSpeedY;
      playerSpeedY = 0;
      playerIsOnGround = true;
    } else {
      playerY -= playerSpeedY;
      playerSpeedY = 0;
    }
  } else {
    playerIsOnGround = false;
  }

  // Enemy Obstacle Collision
  if (isColliding(enemyX - ENEMY_RADIUS, enemyY - ENEMY_RADIUS, ENEMY_RADIUS * 2, ENEMY_RADIUS * 2)) {
    enemySpeedX = -enemySpeedX;
    enemySpeedY = -enemySpeedY;
    enemyX += enemySpeedX;
    enemyY += enemySpeedY;
  }
}

