```javascript
const canvas = document.getElementById("game-canvas");
const context = canvas.getContext("2d");
canvas.width = 480;
canvas.height = 320;
const GRAVITY = 60;
const ENEMY_RADIUS = 10;
const PLAYER_RADIUS = 10;
const TRACTION = 0.999;
const OBSTACLE_COUNT = 6;
const PLATFORM_SPEED = 1;
let playerX = 50;
let playerY = 250;
let isPlayerAlive = true;
let enemyX = 400;
let enemyY = 100;
let enemySpeedX = 0;
let enemySpeedY = 0;
let enemyMultiplier = 0;
let playerSpeedX = 0;
let playerSpeedY = 0;
let playerIsOnGround = false;
let lasers = [];
let shootingTimer = 0;
let obstacles = [];
const obstacleWidth = 320;
const obstacleHeight = 5;

function applyGravity() {
    if (!playerIsOnGround) {
        playerSpeedY += GRAVITY / 60
    }
}

function applyTraction() {
    playerSpeedX *= TRACTION
}

function movePlayer() {
    if (!isPlayerAlive) return;
    playerX += playerSpeedX;
    playerY += playerSpeedY;
    if (playerY < 0) {
        playerY = canvas.height - PLAYER_RADIUS * 2;
        playerSpeedY = 0;
    }
    if (playerY > canvas.height) {
        playerY = 0;
        playerSpeedY = 0;
    }
    context.fillStyle = "pink";
    context.fillRect(playerX, playerY, PLAYER_RADIUS * 2, PLAYER_RADIUS * 2);
}

function moveEnemy() {
    if (!isPlayerAlive) return;
    const angle = Math.atan2(playerY - enemyY, playerX - enemyX);
    enemySpeedX = Math.cos(angle) * 2;
    enemySpeedY = Math.sin(angle) * 2;
    enemyX += enemySpeedX;
    enemyY += enemySpeedY;

    if (shootingTimer <= 0) {
        shootLaser();
        shootingTimer = 1;
    }
    shootingTimer -= 1e-4;
    context.fillStyle = "cyan";
    context.fillRect(enemyX - ENEMY_RADIUS, enemyY - ENEMY_RADIUS, ENEMY_RADIUS * 2, ENEMY_RADIUS * 2);
}

function createObstacles() {
    for (let i = 0; i < OBSTACLE_COUNT; i++) {
        const obstacleX = Math.random() * (canvas.width - obstacleWidth);
        const obstacleY = Math.random() * (canvas.height - obstacleHeight);
        obstacles.push({ x: obstacleX, y: obstacleY, width: obstacleWidth, height: obstacleHeight });
    }
}

function moveObstacles() {
    for (const obstacle of obstacles) {
        obstacle.y += PLATFORM_SPEED;
        if (obstacle.y > canvas.height) {
            obstacle.y = -obstacleHeight;
            obstacle.x = Math.random() * (canvas.width - obstacleWidth);
        }
    }
}

function drawObstacles() {
    context.fillStyle = "yellow";
    for (const obstacle of obstacles) {
        context.fillRect(obstacle.x, obstacle.y, obstacle.width, obstacle.height);
    }
}

function checkCollision() {
    for (const obstacle of obstacles) {
        if (playerX < obstacle.x + obstacle.width && playerX + PLAYER_RADIUS * 2 > obstacle.x && playerY < obstacle.y + obstacle.height && playerY + PLAYER_RADIUS * 2 > obstacle.y) {
            if (playerSpeedY >= 0) {
                playerY = obstacle.y - PLAYER_RADIUS * 2;
                playerSpeedY = 0;
                playerIsOnGround = true;
            }
        } else {
            playerIsOnGround = false;
        }
    }
}

function draw() {
    context.fillStyle = "black";
    context.fillRect(0, 0, canvas.width, canvas.height);
    applyGravity();
    applyTraction();
    movePlayer();
    moveEnemy();
    moveObstacles();
    checkCollision();
    drawObstacles();
    requestAnimationFrame(draw);
}

createObstacles();
draw();

document.addEventListener("keydown", event => {
    if (event.code === "KeyA") {
        playerSpeedX = -5;
    }
    if (event.code === "KeyD") {
        playerSpeedX = 5;
    }
    if (event.code === "KeyW" && playerIsOnGround) {
        playerSpeedY = -20;
        playerIsOnGround = false;
    }
});

document.addEventListener("keyup", event => {
    if (event.code === "KeyA" || event.code === "KeyD") {
        playerSpeedX = 0;
    }
});
```

