	CaseIPFSHash    string `json:"case_ipfs_hash"`
}

type CaseChaincode struct {
}

func (t *CaseChaincode) Init(stub shim.ChaincodeStubInterface) peer.Response {
	return shim.Success(nil)
}

func (t *CaseChaincode) Invoke(stub shim.ChaincodeStubInterface) peer.Response {
	function, args := stub.GetFunctionAndParameters()

	if function == "addCase" {
		return t.addCase(stub, args)
	} else if function == "queryCase" {
		return t.queryCase(stub, args)
	} else if function == "queryCasesByParams" {
		return t.queryCasesByParams(stub, args)
	}

	return shim.Error("Invalid function name.")
}

func (t *CaseChaincode) addCase(stub shim.ChaincodeStubInterface, args []string) peer.Response {
	if len(args) != 10 {
		return shim.Error("Incorrect number of arguments. Expecting 10.")
	}

	caseDetails := CaseDetails{
		CaseID:          args[0],
		CaseName:        args[1],
		CaseType:        args[2],
		CaseDescription: args[3],
		CaseStatus:      args[4],
		CaseDate:        args[5],
		CaseTime:        args[6],
		CaseLocation:    args[7],
		CaseIPFSHash:    args[8],
	}

	caseJSON, err := json.Marshal(caseDetails)
	if err != nil {
		return shim.Error(err.Error())
	}

	err = stub.PutState(args[0], []byte(caseJSON))
	if err != nil {
		return shim.Error(err.Error())
	}

	return shim.Success([]byte("Case added successfully."))
}

func (t *CaseChaincode) queryCase(stub shim.ChaincodeStubInterface, args []string) peer.Response {
	if len(args) != 1 {
		return shim.Error("Incorrect number of arguments. Expecting 1.")
	}

	caseJSON, err := stub.GetState(args[0])
	if err != nil {
		return shim.Error(err.Error())
	}

	return shim.Success(caseJSON)
}

func (t *CaseChaincode) queryCasesByParams(stub shim.ChaincodeStubInterface, args []string) peer.Response {
	if len(args) != 9 {
		return shim.Error("Incorrect number of arguments. Expecting 9.")
	}

	queryString := composeQueryString(args)

	resultsIterator, err := stub.GetQueryResult(queryString)
	if err != nil {
		return shim.Error(err.Error())
	}
	defer resultsIterator.Close()

	var buffer bytes.Buffer
	buffer.WriteString("[")
	for resultsIterator.HasNext() {
		queryResponse, err := resultsIterator.Next()
		if err != nil {
			return shim.Error(err.Error())
		}

		buffer.WriteString(string(queryResponse.Value))
		if resultsIterator.HasNext() {
			buffer.WriteString(",")
		}
	}
	buffer.WriteString("]")

	return shim.Success(buffer.Bytes())
}

func composeQueryString(args []string) string {
	queryString := `{"selector":{`
	for i, arg := range args {
		if arg != "" {
			if i != 0 {
				queryString += `,`
			}
			var field string
			switch i {
			case 0:
				field = "case_id"
			case 1:
				field = "case_name"
			case 2:
				field = "case_type"
			case 3:
				field = "case_description"
			case 4:
