			case 6:
				field = "case_time"
			case 7:
				field = "case_location"
			case 8:
				field = "case_ipfs_hash"
			}
			queryString += `"` + field + `":"` + strings.ToLower(arg) + `"`
		}
	}
	queryString += `}}`
	return queryString
}

