class BlockPair {
    constructor() {
        this.x = Math.floor(boardWidth / 2) - 1;
        this.y = 0;
        this.color1 = randomColor();
        this.color2 = randomColor();
        this.shape = [
            [this.color1, this.color2]
        ];
    }
}

// 現在のブロックペアを移動
function moveCurrentPair(dx, dy) {
  if (isValidMove(currentPair.x + dx, currentPair.y + dy, currentPair.shape)) {
    currentPair.x += dx;
    currentPair.y += dy;
  }
}

// 現在のブロックペアを回転
function rotateCurrentPair() {
  let newShape = rotate(currentPair.shape);
  if (isValidMove(currentPair.x, currentPair.y, newShape)) {
    currentPair.shape = newShape;
  }
}

// 移動が有効かどうかを判断
function isValidMove(x, y, shape) {
  for (let i = 0; i < shape.length; i++) {
    for (let j = 0; j < shape[i].length; j++) {
      if (shape[i][j] && (
        y + i < 0 || 
        x + j < 0 || 
        x + j >= boardWidth || 
        y + i >= boardHeight || 
        board[y + i][x + j]
      )) {
        return false;
      }
    }
  }
  return true;
}

// 現在のブロックペアを固定
function lockCurrentPair() {
  for (let y = 0; y < currentPair.shape.length; y++) {
    for (let x = 0; x < currentPair.shape[y].length; x++) {
      if (currentPair.shape[y][x]) {
        board[currentPair.y + y][currentPair.x + x] = currentPair.color;
      }
    }
  }
}

// ゲームオーバー判定
function isGameOver() {
  for (let x = 0; x < boardWidth; x++) {
    if (board[0][x]) {
      return true;
    }
  }
  return false;
}

// 接続されたブロックを見つける
function findConnectedBlocks(x, y, color, visited) {
  if (x < 0 || y < 0 || x >= boardWidth || y >= boardHeight || visited[y][x] || board[y][x] !== color) {
    return [];
  }

  visited[y][x] = true;
  let connectedBlocks = [{x: x, y: y}];

  connectedBlocks = connectedBlocks.concat(findConnectedBlocks(x - 1, y, color, visited));
  connectedBlocks = connectedBlocks.concat(findConnectedBlocks(x + 1, y, color, visited));
  connectedBlocks = connectedBlocks.concat(findConnectedBlocks(x, y - 1, color, visited));
  connectedBlocks = connectedBlocks.concat(findConnectedBlocks(x, y + 1, color, visited));

  return connectedBlocks;
}

// 空のセルを埋め、連鎖を処理
function collapseAndChain() {
    let chain = false;
    for (let x = 0; x < boardWidth; x++) {
        let emptyY;
        for (let y = boardHeight - 1; y >= 0; y--) {
            if (board[y][x] === 0) {
                if (!emptyY) emptyY = y;
            } else {
                if (emptyY) {
                    board[emptyY][x] = board[y][x];
                    board[y][x] = 0;
                    chain = true;
                    emptyY = null;
                    y = emptyY + 1;
                }
            }
        }
    }
    if (chain) {
        chainMultiplier += 0.25;
        setTimeout(checkClearAndChain, gravityInterval);
    } else {
        chainMultiplier = 1;
    }
}

// 接続されたブロックをクリア
function clearConnectedBlocks(connectedBlocks) {
  for (let i = 0; i < connectedBlocks.length; i++) {
    clearBlock(connectedBlocks[i].x, connectedBlocks[i].y);
  }
}

// ブロックをクリアする
function clearBlock(x, y) {
  board[y][x] = 0;
}

// クリアと連鎖のチェック
function checkClearAndChain() {
    let visited = new Array(boardHeight).fill(null).map(() => new Array(boardWidth).fill(false));

    for (let y = 0; y < boardHeight; y++) {
        for (let x = 0; x < boardWidth; x++) {
            if (!visited[y][x] && board[y][x]) {
                const color = board[y][x];
                const connectedBlocks = findConnectedBlocks(x, y, color, visited);

                if (connectedBlocks.length >= minimumConnected) {
                    clearConnectedBlocks(connectedBlocks);
                    updateScore(connectedBlocks);
                }
            }
        }
    }
    collapseAndChain();
}

