function drawGrid() {
    for (let x = 0; x <= gridWidth; x += blockSize) {
        ctx.beginPath();
        ctx.moveTo(x, 0);
        ctx.lineTo(x, gridHeight);
        ctx.stroke();
    }

    for (let y = 0; y <= gridHeight; y += blockSize) {
        ctx.beginPath();
        ctx.moveTo(0, y);
        ctx.lineTo(gridWidth, y);
        ctx.stroke();
    }
}

function drawBlocks() {
  for (let y = 0; y < boardHeight; y++) {
    for (let x = 0; x < boardWidth; x++) {
      if (board[y][x]) {
        ctx.fillStyle = board[y][x];
        ctx.fillRect(x * blockSize, y * blockSize, blockSize, blockSize);
        ctx.beginPath();
        ctx.arc((x + 0.5) * blockSize, (y + 0.5) * blockSize, blockSize / 2, 0, 2 * Math.PI);
        ctx.closePath();
        ctx.fill();
      }
    }
  }

  for (let y = 0; y < currentPair.shape.length; y++) {
    for (let x = 0; x < currentPair.shape[y].length; x++) {
      if (currentPair.shape[y][x]) {
        ctx.fillStyle = currentPair.color;
        ctx.fillRect((currentPair.x + x) * blockSize, (currentPair.y + y) * blockSize, blockSize, blockSize);
        ctx.beginPath();
        ctx.arc((currentPair.x + x + 0.5) * blockSize, (currentPair.y + y + 0.5) * blockSize, blockSize / 2, 0, 2 * Math.PI);
        ctx.closePath();
        ctx.fill();
      }
    }
  }
}

function drawScore() {
  ctx.fillStyle = "white";
  ctx.font = "20px Arial";
  ctx.fillText("Score: " + score, 10, 30);
}

function drawGameOverMessage() {
  ctx.fillStyle = "rgba(0, 0, 0, 0.75)";
  ctx.fillRect(0, canvas.height / 4, canvas.width, canvas.height / 2);

  ctx.fillStyle = "white";
  ctx.font = "40px Arial";
  ctx.fillText("Game Over", canvas.width / 2 - 100, canvas.height / 2 - 20);
}

function drawGamePausedMessage() {
  ctx.fillStyle = "rgba(0, 0, 0, 0.75)";
  ctx.fillRect(0, canvas.height / 4, canvas.width, canvas.height / 2);

  ctx.fillStyle = "white";
  ctx.font = "40px Arial";
  ctx.fillText("Paused", canvas.width / 2 - 70, canvas.height / 2 - 20);
}

class BlockPair {
    constructor() {
        this.x = Math.floor(boardWidth / 2) - 1;
        this.y = 0;
        this.color1 = randomColor();
        this.color2 = randomColor();
        this.shape = [
            [this.color1, this.color2]
        ];
    }
}

function moveCurrentPair(dx, dy) {
  if (isValidMove(currentPair.x + dx, currentPair.y + dy, currentPair.shape)) {
    currentPair.x += dx;
    currentPair.y += dy;
  }
}

function rotateCurrentPair(clockwise = false) {
  let newShape = rotate(currentPair.shape, clockwise);
  if (isValidMove(currentPair.x, currentPair.y, newShape)) {
    currentPair.shape = newShape;
  }
}

function dropCurrentPairToGround() {
  let dropDist = 0;
  while (isValidMove(currentPair.x, currentPair.y + dropDist + 1, currentPair.shape)) {
    dropDist++;
  }
  moveCurrentPair(0, dropDist);
}

function gameLoop() {
  update();
  draw();
  requestAnimationFrame(gameLoop);
}

function lockCurrentPair() {
  for (let y = 0; y < currentPair.shape.length; y++) {
    for (let x = 0; x < currentPair.shape[y].length; x++) {
      if (currentPair.shape[y][x]) {
        board[currentPair.y + y][currentPair.x + x] = currentPair.color;
      }
    }
  }
}

init();
