    vkWaitForFences(window_.device, 1, &inFlightFences_[currentFrame_], VK_TRUE, UINT64_MAX);

    // Acquire image and record command buffers
    uint32_t imageIndex = swapchain_.acquireNextImage(imageAvailableSemaphores_[currentFrame_]);
    recordCommandBuffers(objects, imageIndex);

    // Submit render commands and present frame
    swapchain_.submitRenderCommandsAndWait(renderFinishedSemaphores_[currentFrame_], inFlightFences_[currentFrame_]);
