```javascript
// Import h and Component from preact
const { h, Component } = preact;

// Our App component that will manage Server-Sent Events
class App extends Component {
  constructor() {
    super();

    // Set an initial state containing an empty "messages" array
    this.state = {
      messages: []
    };
  }

  // Lifecycle method to start listening to events when the component gets mounted
  componentDidMount() {
    // Create a new EventSource to establish a connection with the SSE stream
    this.eventSource = new EventSource("path/to/sse/server");

    // Set a callback to handle incoming message events
    this.eventSource.onmessage = (event) => {
      // Parse the event data as JSON
      const newMessage = JSON.parse(event.data);

      // Append the new message to the current list of messages in the state
      this.setState({
        messages: [...this.state.messages, newMessage]
      });
    };
  }

  // Lifecycle method to clean up the event source when a component is unmounted
  componentWillUnmount() {
    this.eventSource.close();
  }

  render() {
    const { messages } = this.state;

    return (
      // Display the list of messages
      <ul>
        {messages.map((message, index) => (
          <li key={index}>{message.text}</li>
        ))}
      </ul>
    );
  }
}

// Render the App component
preact.render(h(App), document.getElementById("app"));
```

