    // ... set up other aspects like vertex buffers, descriptor sets, etc., and draw objects ...
    for (const auto& obj : gameObjects)
    {
        obj.Draw(commandBuffer);
    }

    vkEndCommandBuffer(commandBuffer);

    m_Swapchain->SubmitCommandBuffer(commandBuffer);
    m_Swapchain->Present(imageIndex);
}

