import java.util.ArrayList;
import java.util.Arrays;
import java.util.PriorityQueue;

public class Graph {

    private int totalCost;

	private ArrayList<Vertex> vertexList;
	private ArrayList<Edge> edgeList;

	public Graph(ArrayList<Edge> edgeList, int maxVertex) {

		this.edgeList = edgeList;
		this.vertexList = new ArrayList<>(maxVertex);

		for (int i = 0; i < maxVertex + 1; i++) {
			this.vertexList.add(new Vertex(i));
		}

	}

	public void getMaxFlow(int source, int sink) {

        int maxFlow = 0;
        totalCost = 0;
        int[] parent = new int[vertexList.size()];

        while (dijkstra(source, sink, parent)) {

            int pathFlow = Integer.MAX_VALUE;
            int pathCost = 0;

            for (int v = sink; v != source; v = parent[v]) {
                int u = parent[v];
                for (Edge e : this.edgeList) {
                    if (e.getA() == u && e.getB() == v) {
                        pathFlow = Math.min(pathFlow, e.getCapacity() - e.getFlow());
                        pathCost += e.getCost();
                    }
                }
            }

            for (int v = sink; v != source; v = parent[v]) {
                int u = parent[v];
                for (Edge e : this.edgeList) {
                    if (e.getA() == u && e.getB() == v) {
                        e.addFlow(pathFlow);
                    } else if (e.getA() == v && e.getB() == u) {
                        e.addFlow(-pathFlow);
                    }
                }
            }
            maxFlow += pathFlow;
            totalCost += pathFlow * pathCost;
        }

        System.out.println(String.format("Output [source, sink, max-flow, min-cost]: %d, %d, %d, %d", source, sink, maxFlow, totalCost));
    }

    private boolean dijkstra(int source, int sink, int[] parent) {

        int[] dist = new int[vertexList.size()];
        Arrays.fill(dist, Integer.MAX_VALUE);
        dist[source] = 0;

        boolean[] visited = new boolean[vertexList.size()];

        PriorityQueue<Integer> pq = new PriorityQueue<>((u, v) -> dist[u] - dist[v]);
        pq.add(source);

        while (!pq.isEmpty()) {
            int u = pq.poll();
            visited[u] = true;

            for (Edge e : this.edgeList) {
                if ((e.getCapacity() - e.getFlow()) > 0 && e.getA() == u) {
                    int v = e.getB();
                    int alt = dist[u] + e.getCost();
                    if (alt < dist[v]) {
                        dist[v] = alt;
                        parent[v] = u;
                        pq.add(v);
                    }
                }
            }
        }

        return visited[sink];
    }
}

It looks like the issue is with the cost calculation in the getMaxFlow method. After some investigation, I found that Dijkstra's algorithm is not suitable for finding a minimum cost flow since it treats negative edge costs incorrectly. Instead, you can use another shortest-path algorithm called the Bellman-Ford algorithm. I've implemented the Bellman-Ford algorithm and made a few other changes to the code to accommodate it.

