1. 首先，创建一个名为 IEntity 的接口，所有实体将实现此接口：

```csharp
public interface IEntity
{
    int Id { get; set; }
}
```

2. 创建一个简单的实体类：

```csharp
public class Product : IEntity
{
    public int Id { get; set; }
    public string Name { get; set; }
    public decimal Price { get; set; }
}
```

3. 创建一个泛型的 IRepository 接口，包含基本的 CRUD 操作：

```csharp
public interface IRepository<T> where T : class, IEntity
{
    Task<IEnumerable<T>> GetAllAsync();
    Task<T> GetByIdAsync(int id);
    Task AddAsync(T entity);
    void Update(T entity);
    void Delete(T entity);
}
```

4. 创建一个继承 IRepository 接口的泛型存储库类 GenericRepository：

```csharp
public class GenericRepository<T> : IRepository<T> where T : class, IEntity
{
    protected readonly DbContext _context;

    public GenericRepository(DbContext context)
    {
        _context = context;
    }

    public async Task<IEnumerable<T>> GetAllAsync()
    {
        return await _context.Set<T>().ToListAsync();
    }

    public async Task<T> GetByIdAsync(int id)
    {
        return await _context.Set<T>().FindAsync(id);
    }

    public async Task AddAsync(T entity)
    {
        await _context.Set<T>().AddAsync(entity);
        await _context.SaveChangesAsync();
    }

    public void Update(T entity)
    {
        _context.Set<T>().Update(entity);
        _context.SaveChanges();
    }

    public void Delete(T entity)
    {
        _context.Set<T>().Remove(entity);
        _context.SaveChanges();
    }
}
```

5. 创建 DbContext 类：

```csharp
public class AppDbContext : DbContext
{
    public AppDbContext(DbContextOptions<AppDbContext> options) : base(options) { }

    public DbSet<Product> Products { get; set; }
}
```

6. 在 Startup.cs 文件中的 ConfigureServices 方法里，添加如下代码以配置依赖注入：

```csharp
// Enable dependency injection for the DbContext using the connection string
services.AddDbContext<AppDbContext>(options =>
    options.UseSqlServer(Configuration.GetConnectionString("DefaultConnection")));

// Register the GenericRepository for dependency injection
services.AddScoped(typeof(IRepository<>), typeof(GenericRepository<>));
```

