                                this.mw.blockColours,
                                new RenderChunk(chunk),
                                this.pixels, pixelOffset, this.textureSize,
                                this.py, mask
                        );
                        return null;
                    }));
                }
                flagOffset += 1;
            }
        }

        renderFutures.forEach(future -> {
            try {
                future.get();
            } catch (InterruptedException | ExecutionException e) {
                e.printStackTrace();
            }
        });

        this.renderToTexture(this.py + 1);
    }

