Here is a sample C++ program that creates a window consisting of 60x60 square blocks, each 20 pixels square big, that can turn black or white when clicked or dragged. This code uses the Simple DirectMedia Layer (SDL) library to create the window and handle input events:

```c++
#include <SDL2/SDL.h>

const int BLOCK_SIZE = 20;   // Width and height of each block
const int GRID_WIDTH = 60;   // Number of blocks in each row of the grid
const int GRID_HEIGHT = 60;  // Number of blocks in each column of the grid
const int WINDOW_WIDTH = GRID_WIDTH * BLOCK_SIZE;
const int WINDOW_HEIGHT = GRID_HEIGHT * BLOCK_SIZE;

// Tile states: 0 = white, 1 = black
int grid[GRID_WIDTH][GRID_HEIGHT] = {0};

// Returns the row and column of the block that corresponds to the given screen coordinates
void getBlockCoords(int x, int y, int& row, int& col)
{
    row = y / BLOCK_SIZE;
    col = x / BLOCK_SIZE;
}

// Toggle the state of the block at the given row and column
void toggleBlock(int row, int col)
{
    if (grid[row][col] == 0) {
        grid[row][col] = 1;
    } else {
        grid[row][col] = 0;
    }
}

int main(int argc, char* argv[])
{
    // Initialize SDL
    SDL_Init(SDL_INIT_VIDEO);

    // Create the window
    SDL_Window* window = SDL_CreateWindow("Grid",
                                          SDL_WINDOWPOS_CENTERED,
                                          SDL_WINDOWPOS_CENTERED,
                                          WINDOW_WIDTH,
                                          WINDOW_HEIGHT,
                                          SDL_WINDOW_SHOWN);

    // Create the renderer
    SDL_Renderer* renderer = SDL_CreateRenderer(window, -1, SDL_RENDERER_ACCELERATED);

    // Handle events
    bool quit = false;
    while (!quit) {
        SDL_Event event;
        while (SDL_PollEvent(&event)) {
            switch (event.type) {
                case SDL_QUIT:
                    quit = true;
                    break;
                case SDL_MOUSEBUTTONDOWN:
                    int row, col;
                    getBlockCoords(event.button.x, event.button.y, row, col);
                    toggleBlock(row, col);
                    break;
                case SDL_MOUSEMOTION:
                    if (event.motion.state & SDL_BUTTON(SDL_BUTTON_LEFT)) {
                        getBlockCoords(event.motion.x, event.motion.y, row, col);
                        toggleBlock(row, col);
                    }
                    break;
            }
        }

        // Clear the screen
        SDL_SetRenderDrawColor(renderer, 255, 255, 255, 255);
        SDL_RenderClear(renderer);

        // Draw the grid
        SDL_Rect rect;
        rect.w = BLOCK_SIZE;
        rect.h = BLOCK_SIZE;
        for (int row = 0; row < GRID_HEIGHT; row++) {
            for (int col = 0; col < GRID_WIDTH; col++) {
                if (grid[row][col] == 1) {
                    // Block is black
                    SDL_SetRenderDrawColor(renderer, 0, 0, 0, 255);
                } else {
                    // Block is white
                    SDL_SetRenderDrawColor(renderer, 255, 255, 255, 255);
                }

                rect.x = col * BLOCK_SIZE;
                rect.y = row * BLOCK_SIZE;
                SDL_RenderFillRect(renderer, &rect);
            }
        }

        // Update the screen
        SDL_RenderPresent(renderer);
    }

    // Clean up
    SDL_DestroyRenderer(renderer);
    SDL_DestroyWindow(window);
    SDL_Quit();

    return 0;
}
