```cpp
#include <SFML/Graphics.hpp>
#include <vector>

constexpr int blockSize = 20;
constexpr int numBlocks = 60;
constexpr int windowSize = numBlocks * blockSize;

int main() {
  sf::RenderWindow window(sf::VideoMode(windowSize, windowSize), "Grid Blocks");

  std::vector<sf::RectangleShape> blocks(numBlocks * numBlocks);
  for (int i = 0; i < numBlocks; ++i) {
    for (int j = 0; j < numBlocks; ++j) {
      int index = i * numBlocks + j;
      blocks[index].setSize(sf::Vector2f(blockSize, blockSize));
      blocks[index].setOutlineColor(sf::Color::Black);
      blocks[index].setOutlineThickness(1);
      blocks[index].setFillColor(sf::Color::White);
      blocks[index].setPosition(j * blockSize, i * blockSize);
    }
  }

  while (window.isOpen()) {
    sf::Event event;
    while (window.pollEvent(event)) {
      if (event.type == sf::Event::Closed) {
        window.close();
      } else if (event.type == sf::Event::MouseButtonPressed ||
                 event.type == sf::Event::MouseMoved) {
        if (event.mouseButton.button == sf::Mouse::Left ||
            event.type == sf::Event::MouseMoved) {
          sf::Vector2i mousePos = sf::Mouse::getPosition(window);

          if (mousePos.x >= 0 && mousePos.y >= 0 && mousePos.x < windowSize &&
              mousePos.y < windowSize) {
            int index = (mousePos.y / blockSize) * numBlocks + (mousePos.x / blockSize);
            if (blocks[index].getFillColor() == sf::Color::White) {
              blocks[index].setFillColor(sf::Color::Black);
            } else {
              blocks[index].setFillColor(sf::Color::White);
            }
          }
        }
      }
    }

    window.clear();
    for (int i = 0; i < numBlocks * numBlocks; ++i) {
      window.draw(blocks[i]);
    }
    window.display();
  }

  return 0;
}
