```go
package main

import (
	"fmt"
	"io/ioutil"
	"log"

	"github.com/goyy/goyacc"
)

type BibtexParser struct {
	entries []map[string]string
}

func (p *BibtexParser) getEntryByKey(key string) map[string]string {
	for _, entry := range p.entries {
		if entry["key"] == key {
			return entry
		}
	}
	return nil
}

func NewBibtexParser() *BibtexParser {
	return &BibtexParser{
		entries: make([]map[string]string, 0),
	}
}

// Bibtex lexer tokens
const (
	ENTRYTYPE  = "ENTRYTYPE"
	FIELDNAME  = "FIELDNAME"
	FIELDVALUE = "FIELDVALUE"
	COMMA      = "COMMA"
	LBRACE     = "LBRACE"
	RBRACE     = "RBRACE"
	IDENTIFIER = "IDENTIFIER"
	STRING     = "STRING"
	EQUALS     = "EQUALS"
	WHITESPACE = "WHITESPACE"
)

func (p *BibtexParser) Lex(l *goyacc.Lexer) goyacc.Token {
	for {
		c := l.Next()
		if c == 0 {
			return goyacc.Token{Type: goyacc.Eof}
		}
		switch c {
		case '@':
			l.Rewind()
			return goyacc.Token{Type: ENTRYTYPE, Value: l.MatchRegexp(`@\w+`)}
		case ',':
			return goyacc.Token{Type: COMMA}
		case '{':
			return goyacc.Token{Type: LBRACE}
		case '}':
			return goyacc.Token{Type: RBRACE}
		case '=':
			return goyacc.Token{Type: EQUALS}
		case ' ', '\t', '\n':
			l.Skip()
			return goyacc.Token{Type: WHITESPACE}
		case '\'':
			return goyacc.Token{Type: FIELDVALUE, Value: l.MatchRegexp(`'([^\\']|\\.)*'`)}
		default:
			if c >= 'a' && c <= 'z' || c >= 'A' && c <= 'Z' {
				l.Rewind()
				if l.Peek() == '"' {
					return goyacc.Token{Type: FIELDVALUE, Value: l.MatchRegexp(`"[^"]*"`)}
				} else if s := l.MatchRegexp(`\w+`); isIdentifier(s) {
					return goyacc.Token{Type: FIELDNAME, Value: s}
				} else {
					return goyacc.Token{Type: IDENTIFIER, Value: s}
				}
			} else {
				panic(fmt.Sprintf("illegal character: %q", c))
			}
		}
	}
}

func isIdentifier(s string) bool {
	switch s {
	case "author", "title":
		return true
	default:
		return false
	}
}

// Bibtex parsing rules
func (p *BibtexParser) ParseEntry(l *goyacc.Lexer) goyacc.Symbol {
	entryType := l.Peek(-1).Value
	l.Next() // consume the ENTRYTYPE token

	// Parse fields
	fields := make(map[string]string)
	for {
		switch l.Peek().Type {
		case FIELDNAME:
			fieldName := l.Next().Value
			l.Expect(EQUALS)
			fieldValue := l.Next().Value
			fields[fieldName] = fieldValue
			if l.Peek().Type == COMMA {
				l.Next()
			}
		case RBRACE:
			l.Next()
			p.entries = append(p.entries, map[string]string{
				"entrytype": entryType,
				"fields":    fields,
			})
			return 0
		default:
			panic(fmt.Sprintf("unexpected token: %s", l.Peek()))
		}
	}
}

func main() {
	input, err := ioutil.ReadFile("biblio.bib")
	if err != nil {
		log.Fatal(err)
	}

	parser := NewBibtexParser()

	if err := goyacc.ParseBytes(input, parser); err != nil {
		log.Fatal(err)
	}

	fmt.Printf("%+v\n", parser.entries)
}
```

This Bibtex parser defines token constants for the lexer, and the `Lex` method scans the input byte-by-byte and emits corresponding tokens.

The parsing rules are defined using method `ParseEntry`. It uses the Goyacc lexer to parse the fields for each @entry type and stores them in a map with the corresponding field names and values.

The `main` function reads the Bibtex input file, initializes the parser, and then uses the `ParseBytes` method from Goyacc to parse the input. At the end, it prints the parsed entries.

This is just a basic implementation, and there are many more features that could be added to make it more flexible and robust.

