<?php
    $apiKey = 'YOUR_API_KEY'; // Replace with your own API key
    $city = 'San Francisco'; // Replace with the city you want weather data for
    $url = 'https://api.openweathermap.org/data/2.5/weather?q=' . $city . '&appid=' . $apiKey;

