    echo '<p>Description: ' . $weatherData['weather'][0]['description'] . '</p>';
    echo '<p>Humidity: ' . $weatherData['main']['humidity'] . '%</p>';

    $forecastUrl = 'https://api.openweathermap.org/data/2.5/forecast?q=' . $city . '&appid=' . $apiKey;

    // Fetch forecast data
    $ch = curl_init();
    curl_setopt($ch, CURLOPT_URL, $forecastUrl);
    curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
    $response = curl_exec($ch);
    curl_close($ch);

    $forecastData = json_decode($response, true);

    // Print forecast data
    echo '<h2>5-Day Forecast for ' . $forecastData['city']['name'] . '</h2>';
    foreach($forecastData['list'] as $data) {
        $date = date('Y-m-d', strtotime($data['dt_txt']));
        if(strpos($data['dt_txt'], '18:00:00') !== false) {
            echo '<h3>' . date('l', strtotime($date)) . '</h3>';
