// qsort comparator function to sort edges by weight
int edge_cmp(const void* a, const void* b) {
    return ((edge*)a)->w - ((edge*)b)->w;
}

// Find parent vertex of a given vertex in a disjoint-set structure
int find_set(int* parent, int v) {
    if (parent[v] == v) return v;
    return parent[v] = find_set(parent, parent[v]);
}

// Merge two disjoint sets based on their parent vertices
void merge_sets(int* parent, int* rank, int u, int v) {
    u = find_set(parent, u);
    v = find_set(parent, v);
    if (rank[u] < rank[v]) {
        parent[u] = v;
    } else if (rank[u] > rank[v]) {
        parent[v] = u;
    } else {
        parent[u] = v;
        rank[v]++;
    }
}

// Find minimum spanning tree in which nodes of U are leaves
edge* min_spanning_tree(int n, edge* edges, int m, int* U, int k, int* num_edges) {
    // Sort edges by weight in increasing order
    qsort(edges, m, sizeof(edge), edge_cmp);

    // Initialize disjoint-set structure for connected components
    int* parent = (int*) malloc(n * sizeof(int));
    int* rank = (int*) malloc(n * sizeof(int));
    for (int i = 0; i < n; i++) {
        parent[i] = i;
        rank[i] = 0;
    }

    // Initialize X and Y sets of vertices
    int* x = (int*) malloc(k * sizeof(int));
    int* y = (int*) malloc((n - k) * sizeof(int));
    int x_size = k, y_size = n - k;
    for (int i = 0; i < k; i++) {
        x[i] = U[i];
    }
    int j = 0;
    for (int i = 0; i < n; i++) {
        if (!(j < k && i == U[j])) {
            y[j] = i;
            j++;
        }
    }

    // Add minimum-weight edges (u,v) for each u in X and v in Y
    for (int i = 0; i < k; i++) {
        int u = x[i];
        int min_w = -1;
        int min_v = -1;
        for (int j = 0; j < y_size; j++) {
            int v = y[j];
            int e_idx = i * y_size + j;
            if (edges[e_idx].u == -1 || edges[e_idx].v == -1) break;
            if (find_set(parent, u) != find_set(parent, v) && 
                min_w == -1 || edges[e_idx].w < min_w) {
                min_w = edges[e_idx].w;
                min_v = v;
            }
        }
        if (min_w != -1) {
            num_edges++;
            T[num_edges].u = u;
            T[num_edges].v = min_v;
            T[num_edges].w = min_w;
            merge_sets(parent, rank, u, min_v);
        }
    }

    // Compute minimum spanning tree of subgraph induced by Y
    for (int i = 0; i < m; i++) {
        int u = edges[i].u;
        int v = edges[i].v;
        if (find_set(parent, u) != find_set(parent, v)) {
            if ((u < k && v >= k) || (u >= k && v >= k)) {
                num_edges++;
                T[num_edges].u = u;
                T[num_edges].v = v;
                T[num_edges].w = edges[i].w;
                merge_sets(parent, rank, u, v);
