Here is one way to implement the solution:

1. Create a function to parse the input string and create a dictionary with building names as keys and indices as values.
2. Create another function to parse the connected building pairs and store them as a list of tuples.
3. Create a function to find the connected buildings using depth-first search.
4. In the main function, for each dataset, iterate through the buildings, find the connected buildings and remove them from the list. Count the number of iterations as the number of distinct parts.

```java
import java.io.File;
import java.io.IOException;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Scanner;

public class Tunnels {

    public static HashMap<String, Integer> parseBuildingList(String buildings) {
        HashMap<String, Integer> result = new HashMap<>();
        String[] buildingNames = buildings.split(",");

        for (int i = 0; i < buildingNames.length; i++) {
            result.put(buildingNames[i], i);
        }
        return result;
    }

    public static ArrayList<String[]> parseConnectedPairs(String pairs) {
        ArrayList<String[]> result = new ArrayList<>();
        String[] rawPairs = pairs.split("},");

        for (String rawPair : rawPairs) {
            String[] connectedBuildings = rawPair.substring(1, rawPair.length() - 1).split(",");
            result.add(connectedBuildings);
        }
        return result;
    }

    public static HashSet<String> connected(String building, ArrayList<String[]> connectedPairs) {
        HashSet<String> result = new HashSet<>();
        result.add(building);

        for (int i = 0; i < connectedPairs.size(); i++) {
            if (connectedPairs.get(i)[0].equals(building) || connectedPairs.get(i)[1].equals(building)) {
                result.add(connectedPairs.get(i)[0]);
                result.add(connectedPairs.get(i)[1]);
                connectedPairs.remove(i);
                i--;
            }
        }
        return result;
    }

    public static void main(String[] args) throws IOException {
        Scanner input = new Scanner(new File("tunnels.dat"));
        int numDataSets = input.nextInt();
        input.nextLine();

        for (int dataSet = 0; dataSet < numDataSets; dataSet++) {
            String[] inputData = input.nextLine().split("},");

            HashMap<String, Integer> buildingsMap = parseBuildingList(inputData[0].substring(1));
            ArrayList<String[]> connectedPairs = parseConnectedPairs(inputData[1] + '}');

            int distinctParts = 0;

            while (!buildingsMap.isEmpty()) {
                String building = buildingsMap.keySet().iterator().next();
                HashSet<String> connectedBuildings = connected(building, connectedPairs);

                for (String connectedBuilding : connectedBuildings) {
                    buildingsMap.remove(connectedBuilding);
                }
                distinctParts++;
            }
            System.out.println(distinctParts);
        }
        input.close();
    }
}
```

