Here's a simple Arduino code for the Train Accident Prevention Project described earlier:

```cpp
// Pin definitions
const int trigPin = 2;
const int echoPin = 3;
const int greenLED = 4;
const int yellowLED = 5;
const int redLED = 6;
const int firstBuzzer = 7;
const int secondBuzzer = 8;
const int thirdBuzzer = 9;

// Distance thresholds (in cm)
const int safeDistance = 30;
const int cautionDistance = 20;

// Timing variables
unsigned long previousMillis = 0;
const long interval = 200;

void setup() {
    pinMode(trigPin, OUTPUT);
    pinMode(echoPin, INPUT);
    pinMode(greenLED, OUTPUT);
    pinMode(yellowLED, OUTPUT);
    pinMode(redLED, OUTPUT);
    pinMode(firstBuzzer, OUTPUT);
    pinMode(secondBuzzer, OUTPUT);
    pinMode(thirdBuzzer, OUTPUT);
    Serial.begin(9600);
}

void loop() {
    unsigned long currentMillis = millis();
    if (currentMillis - previousMillis >= interval) {
        previousMillis = currentMillis;
        int distance = measureDistance();
        Serial.print("Distance: ");
        Serial.println(distance);

        if (distance >= safeDistance) {
            setWarningLevel(greenLED, false);
        } else if (distance >= cautionDistance) {
            setWarningLevel(yellowLED, true);
        } else {
            setWarningLevel(redLED, true);
        }
    }
}

int measureDistance() {
    digitalWrite(trigPin, LOW);
    delayMicroseconds(2);
    digitalWrite(trigPin, HIGH);
    delayMicroseconds(10);
    digitalWrite(trigPin, LOW);

    int duration = pulseIn(echoPin, HIGH);
    int distance = duration * 0.034 / 2;
    return distance;
}

void setWarningLevel(int activeLED, bool activateBuzzers) {
    digitalWrite(greenLED, activeLED == greenLED);
    digitalWrite(yellowLED, activeLED == yellowLED);
    digitalWrite(redLED, activeLED == redLED);
    digitalWrite(firstBuzzer, activateBuzzers);
    digitalWrite(secondBuzzer, activateBuzzers && activeLED == redLED);
    digitalWrite(thirdBuzzer, activateBuzzers && activeLED == redLED);
}
```

This code uses the ultrasonic sensor to measure distance and sets warning levels at the safeDistance and cautionDistance thresholds. LEDs and buzzers are activated according to the warning levels. The measureDistance() function calculates the distance to the obstacle, and the setWarningLevel() function adjusts the active LED and buzzer states based on the measured distance.

