void Pipeline::createPipeline(VkDevice device, VkRenderPass renderPass)
{
    // Load shaders from files
    std::vector<char> vertShaderCode = {}; // Read vertex shader code from file
    std::vector<char> fragShaderCode = {}; // Read fragment shader code from file

    VkShaderModule vertShaderModule;
    VkShaderModule fragShaderModule;

    createShaderModule(device, vertShaderCode, &vertShaderModule);
    createShaderModule(device, fragShaderCode, &fragShaderModule);

    // Set up shader stage create infos
    // ...

    // Set up vertex input state create info
    // ...

    // Set up input assembly state create info
    // ...

