2. Update your JavaScript file (e.g., script.js) to implement lazy loading:

```javascript
const batchSize = 500; // Number of rows per batch
const totalRows = 10000; // Total number of rows
const columns = 10; // Number of columns

const tableWrapper = document.getElementById('table-wrapper');
const tableContainer = document.getElementById('table-container');

let currentRowIndex = 0;

function generateSampleDataRow(rowIndex) {
  const rowData = [];
  for (let i = 0; i < columns; i++) {
    rowData.push(`Data-${rowIndex}-${i}`);
  }
  return rowData;
}

function renderRow(data) {
  const row = document.createElement('tr');
  for (const cellData of data) {
    const cell = document.createElement('td');
    cell.textContent = cellData;
    cell.style.border = '1px solid #ccc';
    cell.style.padding = '8px';
    row.appendChild(cell);
  }
  return row;
}

function loadBatch() {
  const start = currentRowIndex;
  const end = Math.min(currentRowIndex + batchSize, totalRows);
  for (let i = start; i < end; i++) {
    const rowData = generateSampleDataRow(i);
    const row = renderRow(rowData);
    tableWrapper.appendChild(row);
  }
  currentRowIndex += batchSize;
}

function handleScroll(event) {
  const { scrollHeight, scrollTop, clientHeight } = event.target;
  if (scrollHeight - scrollTop === clientHeight && currentRowIndex < totalRows) {
    loadBatch();
  }
}

function init() {
  tableWrapper.style.display = 'table';
  tableWrapper.style.borderCollapse = 'collapse';
  tableWrapper.style.width = '100%';

  loadBatch();

  tableContainer.addEventListener('scroll', handleScroll);
}

init();
```

Now, the table will initially load `batchSize` number of rows, and whenever the user scrolls to the bottom of the table, another batch of rows will load until all rows are loaded.

The `generateSampleDataRow(rowIndex)` function generates a sample data row, and the `renderRow(data)` function renders a single table row.

The `loadBatch()` function is used to load a batch of rows in the table, starting at row index `currentRowIndex`. The `handleScroll(event)` function is triggered on the `scroll` event, and if the user scrolls to the bottom of the table, it calls `loadBatch()` to load more rows.

Finally, the `init()` function sets up the table and its event listeners on page load.

