private data class POINT(
    val id: Int,
    val x: Double,
    val y: Double
)

private fun readFile(filePath: String, size: Int): Array<POINT> {
    val instance = Array(size) { POINT(0, 0.0, 0.0) }
    try {
        File(filePath).useLines { lines ->
            val linesList = lines.toList()
            if (linesList.size < size) {
                throw RuntimeException("File contains fewer than $size lines")
            }
            linesList.take(size).forEachIndexed { i, line ->
                val (id, x, y) = line.trim().split(",")
                instance[i] = POINT(id.toInt(), x.toDouble(), y.toDouble())
            }
        }
    } catch (e: Exception) {
        e.printStackTrace()
    }
    return instance
}



private fun getDistance(p1: POINT, p2: POINT): Double { // calculate distance between two point
    val dx = p1.x - p2.x
    val dy = p1.y - p2.y
    val distance = sqrt(dx.pow(2.0) + dy.pow(2.0))
    return abs(distance) // distance can not be negative
}



private fun greedy(arrayOfPoints: Array<POINT>, idx: Int): Double {
    // Don't forget to print your solution before returning the total distance!
    var startPoint = idx
    var travelNotDone = true // control if all points visited or not
    var totalDistance = 0.0
    val visited = BooleanArray(arrayOfPoints.size) { false } // assign false to all indexes. Each index represents a point. true -> if visited
    val path = mutableListOf(startPoint) // add startPoint to the path

    while (travelNotDone) {
        var minDistance = Double.MAX_VALUE
        var nextPointId = -1 // make the nextPoint -1 at the start of the loop, it will remain -1 if there is no unvisited point left
        visited[startPoint] = true // mark the point as visited

        // Find the next unvisited point with the minimum distance to the current point
        for (point in arrayOfPoints) {
            if (!visited[point.id] && point.id != startPoint) { // check if visited or same point
                val distance = getDistance(arrayOfPoints[startPoint], point)
                if (distance < minDistance) {
                    minDistance = distance // update the min distance
                    nextPointId = point.id // update the nextPoint if distance smaller
                }
            }
        }

        // if there is no unvisited point left, travelNotDone is set to false
        if (nextPointId == -1) {
            travelNotDone = false
        } else {
            // Update the total distance and path
            totalDistance += minDistance // update the total distance
            path.add(nextPointId)  // add next closest point to the path
            startPoint = nextPointId // update current point
        }
    }

    // Print the travel path
    println("Travel Path: ${path.joinToString(" -> ")}")

    return totalDistance
}

