        request.type = ORDER_TYPE_BUY;
    }
    else if (cmd == "SELL")
    {
        request.action = TRADE_ACTION_DEAL;
        request.type = ORDER_TYPE_SELL;
    }

    request.price = NormalizeDouble(SymbolInfoDouble(_Symbol, SYMBOL_ASK), _Digits);

    double ATR = iATR(_Symbol, TimeFrame, 14, 0);
    request.sl = NormalizeDouble(request.price - (2.5 * ATR), _Digits);
    request.tp = NormalizeDouble(request.price + (3.5 * ATR), _Digits);

    OrderSend(request, result);
}

double calculate_lot_size(double riskPercentage)
{
    double accountBalance = AccountInfoDouble(ACCOUNT_BALANCE);
    double riskAmount = (riskPercentage/100.0) * accountBalance;
    double ATR = iATR(_Symbol, TimeFrame, 14, 0);
    int stopLossPips = int(2.5 * (_Digits == Digits() ? ATR : Point));

    double lotSize = riskAmount / (stopLossPips * SymbolInfoDouble(_Symbol, SYMBOL_TRADE_TICK_VALUE));

    return NormalizeDouble(lotSize, 2);
}

