void AddWatermark(IDirect3DDevice9* pDevice, IDirect3DTexture9* pTexture, const char* szWatermark)
{
    if (!pDevice || !pTexture || !szWatermark)
    {
        return;
    }

    // 创建水印文本信息
    ID3DXFont* pFont;
    D3DXCreateFont(pDevice, 32, 0, FW_BOLD, 1, FALSE, DEFAULT_CHARSET, OUT_DEFAULT_PRECIS,
        DEFAULT_QUALITY, DEFAULT_PITCH | FF_DONTCARE, TEXT("Arial"), &pFont);

    RECT rc;
    SetRect(&rc, 10, 10, 600, 600);

    // 创建水印表面
    IDirect3DSurface9* pSurface;
    pTexture->GetSurfaceLevel(0, &pSurface);

    // 开始渲染
    pDevice->BeginScene();
    pDevice->StretchRect(pSurface, NULL, pSurface, NULL, D3DTEXF_NONE);

    // 插入水印文本
    pFont->DrawTextA(NULL, szWatermark, -1, &rc, DT_LEFT | DT_WORDBREAK | DT_NOPREFIX, D3DCOLOR_ARGB(255, 255, 255, 255));

    // 完成渲染
    pDevice->EndScene();
    pSurface->Release();
    pFont->Release();
}

int main()
{
    // 获取屏幕
    IDirect3D9* pD3D9 = Direct3DCreate9(D3D_SDK_VERSION);
    IDirect3DDevice9* pDevice;
    D3DPRESENT_PARAMETERS d3dpp;
    ZeroMemory(&d3dpp, sizeof(d3dpp));

    d3dpp.Windowed = TRUE;
    d3dpp.SwapEffect = D3DSWAPEFFECT_DISCARD;
    d3dpp.BackBufferFormat = D3DFMT_UNKNOWN;

    pD3D9->CreateDevice(D3DADAPTER_DEFAULT, D3DDEVTYPE_HAL, GetDesktopWindow(), D3DCREATE_SOFTWARE_VERTEXPROCESSING, &d3dpp, &pDevice);

    // 获取屏幕宽度和高度
    D3DDISPLAYMODE d3ddm;
    pD3D9->GetAdapterDisplayMode(D3DADAPTER_DEFAULT, &d3ddm);

    int iWidth = d3ddm.Width;
    int iHeight = d3ddm.Height;

    // 创建表面和纹理
    IDirect3DSurface9* pSurface;
    IDirect3DTexture9* pTexture;
    pDevice->CreateOffscreenPlainSurface(iWidth, iHeight, D3DFMT_A8R8G8B8, D3DPOOL_SYSTEMMEM, &pSurface, NULL);
    pDevice->CreateTexture(iWidth, iHeight, 1, D3DUSAGE_RENDERTARGET, D3DFMT_A8R8G8B8, D3DPOOL_DEFAULT, &pTexture, NULL);

    // 复制到表面
    pDevice->GetFrontBufferData(0, pSurface);
    pDevice->UpdateTexture(pSurface, pTexture);

    // 添加水印
    AddWatermark(pDevice, pTexture, "Your Watermark");

    // 显示到窗口
    HWND hWnd = CreateWindow("STATIC", NULL, WS_VISIBLE | WS_SYSMENU, 0, 0, iWidth, iHeight, NULL, NULL, NULL, NULL);

    IDirect3DSurface9* pSurface2;
    pTexture->GetSurfaceLevel(0, &pSurface2);

    HDC hdc;
    PAINTSTRUCT ps;
    hdc = BeginPaint(hWnd, &ps);
    pDevice->StretchRect(pSurface2, NULL, GetDC(hWnd), NULL, D3DTEXF_NONE);
    EndPaint(hWnd, &ps);

    // 释放资源
    pSurface->Release();
    pSurface2->Release();
    pTexture->Release();
    pDevice->Release();
    pD3D9->Release();

    return 0;
}
