#include <C8051F410.h>

// Peripheral specific initialization functions,
// Called from the Init_Device() function
void PCA_Init()
{
    PCA0MD    &= ~0x40;
    PCA0MD    = 0x00;
}

void Timer_Init()
{
    TCON      = 0x40;
    TMOD      = 0x10;
    TH1=0xFF;   //20us
    TL1=0xD8;
}

void Port_IO_Init()
{
