    key := fmt.Sprintf("%s:%d", sessionID, referenceNum)

    payload, err := r.client.Get(r.client.Context(), key).Bytes()
    if err == redis.Nil {
        // Key has expired, segment is considered expired
        return nil, fmt.Errorf("segment with session %s and reference %d is expired", sessionID, referenceNum)
    }
    if err != nil {
        return nil, fmt.Errorf("failed to retrieve segments: %w", err)
    }

    segments := make([]*Segment, 0)
    segments = append(segments, &Segment{
        SessionID:     sessionID,
        ReferenceNum:  referenceNum,
        Payload:       payload,
        ValidityTime:  time.Minute * 5, // example validity time
    })

    return segments, nil
}
```

In this updated implementation, we check if the returned error is of type `redis.Nil`. If it is, we know that the key has expired and return an error indicating that the segment is considered expired.

This implementation allows us to handle expired segments transparently and ensure that only valid segments are returned.

In case we receive 3 out of 4 segments and their validity time expires before we receive the fourth segment, we can implement a solution that uses a combination of Redis and a separate storage system that allows us to keep the expired segments temporarily. This way, we can process the expired segments in our use case service.

