	"go.mongodb.org/mongo-driver/mongo/options"
	"go.mongodb.org/mongo-driver/mongo/readpref"
)

type SegmentRepository interface {
	Save(segment *Segment) error
	GetBySessionAndRefNum(sessionID string, referenceNum int) ([]*Segment, error)
	SearchExpired() ([]*Segment, error)
	DeleteExpired(segment *Segment) error
}

type RedisSegmentRepository struct {
	client *redis.Client
}

type MongoDBSegmentRepository struct {
	client  *mongo.Client
	ctx     context.Context
	timeout time.Duration
}

func NewRedisSegmentRepository(addr, password string, db int) (*RedisSegmentRepository, error) {
	r := &RedisSegmentRepository{}

	r.client = redis.NewClient(&redis.Options{
		Addr:     addr,
		Password: password,
		DB:       db,
	})

	_, err := r.client.Ping(context.Background()).Result()
	if err != nil {
		return nil, fmt.Errorf("unable to connect to redis: %w", err)
	}

	return r, nil
}

func NewMongoDBSegmentRepository(uri string, db string, connectTimeout time.Duration) (*MongoDBSegmentRepository, error) {
	m := &MongoDBSegmentRepository{
		timeout: connectTimeout,
	}

	ctx, cancel := context.WithTimeout(context.Background(), connectTimeout)
	defer cancel()

	client, err := mongo.Connect(ctx, options.Client().ApplyURI(uri))
	if err != nil {
		return nil, err
	}

	m.ctx = context.Background()
	m.client = client

	if err := m.Ping(); err != nil {
		return nil, err
	}

	return m, nil
}

func (m *MongoDBSegmentRepository) Ping() error {
	ctx, cancel := context.WithTimeout(context.Background(), m.timeout)
	defer cancel()

	err := m.client.Ping(ctx, readpref.Primary())
	if err != nil {
		return fmt.Errorf("unable to connect to mongo: %w", err)
	}
	return nil
}

func (r *RedisSegmentRepository) Save(segment *Segment) error {
	key := fmt.Sprintf("%s:%d", segment.SessionID, segment.ReferenceNum)

	err := r.client.Set(r.client.Context(), key, segment.Payload, segment.ValidityTime).Err()
	if err != nil {
		return fmt.Errorf("failed to save segment: %w", err)
	}

	return nil
}

func (r *RedisSegmentRepository) GetBySessionAndRefNum(sessionID string, referenceNum int) ([]*Segment, error) {
	key := fmt.Sprintf("%s:%d", sessionID, referenceNum)

	payload, err := r.client.Get(r.client.Context(), key).Bytes()
	if err == redis.Nil {
		// Key has expired, segment is considered expired
		segments, err := expiredSegmentRepository.SearchExpired()
		if err != nil {
			return nil, err
		}
		for _, segment := range segments {
			if segment.SessionID == sessionID && segment.ReferenceNum == referenceNum {
				return []*Segment{segment}, nil
			}
		}
		return nil, fmt.Errorf("segment with session %s and reference %d is not found", sessionID, referenceNum)
	}

	if err != nil {
		return nil, fmt.Errorf("failed to retrieve segments: %w", err)
	}

	segments := make([]*Segment, 0)
	segments = append(segments, &Segment{
		SessionID:    sessionID,
		ReferenceNum: referenceNum,
		Payload:      payload,
		ValidityTime: time.Minute * 5, // example validity time
	})

	return segments, nil
}

func (m *MongoDBSegmentRepository) Save(segment *Segment) error {
	collection := m.client.Database("segments").Collection("segments")

	_, err := collection.InsertOne(m.ctx, bson.M{
		"sessionId":    segment.SessionID,
		"referenceNum": segment.ReferenceNum,
		"payload":      segment.Payload,
		"validityTime": segment.ValidityTime,
		"createdAt":    time.Now(),
	})

	if err != nil {
		return err
	}

	return nil
}

func (m *MongoDBSegmentRepository) SearchExpired() ([]*Segment, error) {
	collection := m.client.Database("segments").Collection("segments")

	filter := bson.M{
		"$and": []bson.M{
			{"createdAt": bson.M{"$lte": time.Now().Add(-segmentValidityTime)}},
			{"processedAt": bson.M{"$eq": nil}},
		},
	}

	results, err := collection.Find(m.ctx, filter, options.Find().SetLimit(1000))

	if err == mongo.ErrNoDocuments {
		return []*Segment{}, nil
	}

	if err != nil {
		return nil, err
	}

	segments := []*Segment{}
	for results.Next(m.ctx) {
		var segment Segment
		err = results.Decode(&segment)
		if err != nil {
			return nil, err
		}

		segments = append(segments, &segment)
	}

	return segments, nil
}

func (m *MongoDBSegmentRepository) DeleteExpired(segment *Segment) error {
	collection := m.client.Database("segments").Collection("segments")

	filter := bson.M{
		"$and": []bson.M{
			{"sessionId": bson.M{"$eq": segment.SessionID}},
			{"referenceNum": bson.M{"$eq": segment.ReferenceNum}},
			{"createdAt": bson.M{"$lte": time.Now().Add(-segmentValidityTime)}},
			{"processedAt": bson.M{"$eq": nil}},
		},
	}

	update := bson.M{"$set": bson.M{"processedAt": time.Now()}}

	_, err := collection.UpdateOne(m.ctx, filter, update)
	if err != nil {
		return err
	}

	return nil
}

