  useFindAndModify: false,
  useCreateIndex: true,
});

async function processCustomerChunk(chunk, walletId, wallet, quantity, sendNotificationsToCustomers) {
  let addedClients = 0;
  let duplicatedClients = 0;
  let malformedClients = 0;
  let customers = [];

  for (const element of chunk) {
    if (
      (!element.email && !element.phoneNumber) ||
      !element.firstName ||
      !element.lastName
    ) {
      malformedClients++;
    } else {
      const errorFields = await verifyFields(walletId, {
        barcode: element.barcode,
        email: element.email,
        phoneNumber: element.phoneNumber,
      });

      if (errorFields) {
        duplicatedClients++;
      } else {
        try {
          const customer = await Customer.create({
            _id: element.barcode,
            ...element,
          });

          await StatsClientModel.create({
            customer,
            walletId,
            customerId: customer._id,
          });

          const customerObj = customer.toJSON();
          customerObj.history = [];

          addedClients++;
          customers.push(customerObj);

          if (customer.phoneNumber && sendNotificationsToCustomers) {
            await sms.send(wallet, quantity);
          }
        } catch (error) {
          malformedClients++;
        }
      }
    }
  }

  return {
    addedClients,
    duplicatedClients,
    malformedClients,
    customers,
  };
}

(async () => {
