```javascript
const express = require('express');
const { parseCsvFile } = require('./csvParser');
const { addToDatabase } = require('./db');
const { workerpool } = require('workerpool');
const nodemailer = require('nodemailer');

const app = express();
const workerPool = workerpool.pool(__dirname + '/workerThread.js');

async function sendEmail() {
  let transporter = nodemailer.createTransport({
    // Add your email configuration here
  });

  let mailOptions = {
    from: 'example@example.com',
    to: 'admin@example.com',
    subject: 'CSV Import Completed',
    text: 'The long CSV import process has been completed.',
  };

  transporter.sendMail(mailOptions, (error, info) => {
    if (error) {
      console.log(error);
    } else {
      console.log('Email sent: ' + info.response);
    }
  });
}

app.post('/import-customers', async (req, res) => {
  try {
    const filePath = 'path_to_your_csv_file';
    const records = await parseCsvFile(filePath);

    res.status(200).send('CSV import started, email will be sent when complete.');

    const recordChunks = []; // Divide the records into smaller chunks for parallel processing
    const chunkSize = 500; // Adjust the chunk size based on the available resources and optimizations
    for (let i = 0; i < records.length; i += chunkSize) {
      recordChunks.push(records.slice(i, i + chunkSize));
    }

    const promises = [];

    for (const chunk of recordChunks) {
      promises.push(
        workerPool.exec('addRecordsToDatabase', [chunk]).timeout(5 * 60 * 1000) // 5 minutes timeout
      );
    }

    await Promise.all(promises);
    sendEmail();
  } catch (error) {
    console.error(error);
    res.status(500).send('An error occurred while processing the CSV file.');
  }
});

app.listen(5000, function () {
  console.log('Server listening on port 5000');
});
```

