3. Start writing the code as follows:

```javascript
// Define a region of interest for Java Island, Indonesia.
var roi = ee.Geometry.Polygon([[[105.147,-8.732], [114.711,-8.732], [114.711,-6.069], [105.147,-6.069], [105.147,-8.732]]]);

// Load the MOD11A1 dataset from Google Earth Engine.
var mod11a1 = ee.ImageCollection('MODIS/006/MOD11A1');

// Define seasons: DJF, MAM, JJA, and SON for 2014 and 2015.
var periods = [
  { start: '2014-12-01', end: '2015-02-28', season: 'DJF' },
  { start: '2015-03-01', end: '2015-05-31', season: 'MAM' },
  { start: '2015-06-01', end: '2015-08-31', season: 'JJA' },
  { start: '2015-09-01', end: '2015-11-30', season: 'SON' },
];

for (var p in periods) {
  // Filter MOD11A1 dataset by date and region of interest.
  var mod11a1_filtered = mod11a1.filterDate(periods[p].start, periods[p].end).filterBounds(roi);

  // Calculate the mean of the LST Day 1km band and scale it.
  var mean_temp = mod11a1_filtered.mean().select('LST_Day_1km').multiply(0.02).subtract(273.15);

  // Calculate TCI (Temperature Condition Index) using the mean temperature.
  var tci = mean_temp.subtract(mean_temp.reduce(ee.Reducer.mean())).divide(mean_temp.reduce(ee.Reducer.stdDev()));

