```c
#include <stdio.h>

int main() {
    int boundary, total_points = 0, halftime_points = 0;
    char answer;

    printf("Enter the boundary between questions worth 1 and 2 points: ");
    scanf("%d", &boundary);

    do { // read categories until end is reached
        int category_points = 0, category_multiplier = 1, category_questions = 0;

        // read answers for the current category and count the points earned
        while (scanf(" %c", &answer) == 1 && answer != '\n') {
            if (answer == '-') {
                // skip question, no points earned
            } else if (answer == 'o') {
                category_points += 1;
            } else if (answer == '$') {
                category_multiplier = 2;
            }
            category_questions++;
        }

        // double the points if the joker was not used in this category
        if (category_multiplier == 1 && category_questions > 0) {
            category_points *= 2;
        }

        // add bonus points for questions after the boundary
        if (category_questions >= boundary) {
            category_points += (category_questions - boundary) * 2;
        }

        // add category points to the total and halftime points
        total_points += category_points * category_multiplier;
        if (category_multiplier == 1) {
            halftime_points += category_points;
        } else {
            halftime_points += category_points / 2;
        }

        // print answers for this category
        for (int i = 0; i < category_questions; i++) {
            printf("%c", answer);
        }
        printf("\n");
    } while (answer != EOF);

    // print total and halftime points in the desired format
    printf("%d %d\n", halftime_points, total_points);

    return 0;
}
```

