Here is a program in C that takes the length of three sides of a triangle as input and determines if they form a Pythagorean triple:

```c
#include <stdio.h>

int is_pythagorean_triple(int a, int b, int c) {
    if (a * a + b * b == c * c ||
        a * a + c * c == b * b ||
        b * b + c * c == a * a) {
        return 1;
    } else {
        return 0;
    }
}

int main() {
    int side1, side2, side3;

    // Input three sides
    printf("Enter the length of the first side: ");
    scanf("%d", &side1);
    printf("Enter the length of the second side: ");
    scanf("%d", &side2);
    printf("Enter the length of the third side: ");
    scanf("%d", &side3);

    // Check if the sides form a Pythagorean triple
    int result = is_pythagorean_triple(side1, side2, side3);

    if (result) {
        printf("The given sides form a Pythagorean triple.\n");
    } else {
        printf("The given sides do not form a Pythagorean triple.\n");
    }

    return 0;
}
```

