To create a resizable array (sometimes called a dynamic array or a growable array) in C++, you can use a `std::vector`. 

Here's an example:

```cpp
#include <iostream>
#include <vector>   // Include the vector library

using namespace std;

int main()
{
    vector<int> array;   // Create an empty vector of integers

    // Add elements to the vector using push_back 
    array.push_back(10);    
    array.push_back(20);
    array.push_back(30);

    // Resize the vector to hold 5 elements
    array.resize(5);

    // Add a few more elements
    array.push_back(40);
    array.push_back(50);

    // Print out the vector
    for(auto i : array) {
        cout << i << endl;
    }

    return 0;
