bool hasThreeIdenticalChars(std::string word) {
    int len = word.size();
    if (len < 3) {
        return false;
    }
    char prev = word[0];
    int count = 1;
    for (int i = 1; i < len; i++) {
        char curr = word[i];
        if (curr == prev) {
            count++;
            if (count == 3) {
