    // Interfaces

    [ComImport, Guid("B123F57D-9D04-469d-9CF7-FC60AEF0B6D6")]
    private interface IStillImage
    {
        int EnumDevices(uint dwType, IntPtr pInterface, out IEnumWIA_DEV_INFO ppIEnum);
    }

    [ComImport, Guid("5e38b83c-8cf1-11d1-bf92-0060081ed811"), InterfaceType(ComInterfaceType.InterfaceIsIUnknown)]
    private interface IEnumWIA_DEV_INFO
    {
        [PreserveSig]
