        text: text,
        alignmentX: Jimp.HORIZONTAL_ALIGN_CENTER, // center the text horizontally
        alignmentY: Jimp.VERTICAL_ALIGN_MIDDLE, // center the text vertically
        maxWidth: imageWidth, // wrap the text to multiple lines if it exceeds the image width
      }
    );

    // save the resulting image to disk
    image.write('output.jpg', (err) => {
      if (err) throw err;
      console.log('Done!');
    });
  });
