using System.IO.Ports;

public class SerialPortInfo
{
    public string PortName { get; set; }
    public string Description { get; set; }
    public string VID { get; set; }
    public string PID { get; set; }
}

public static class SerialPortHelper
{
    public static List<SerialPortInfo> GetSerialPortList()
    {
        var portList = new List<SerialPortInfo>();

        ManagementObjectCollection collection;
        using (var searcher = new ManagementObjectSearcher("SELECT * FROM Win32_SerialPort"))
            collection = searcher.Get();

        foreach (var device in collection)
        {
            string desc = device.GetPropertyValue("Description").ToString();
            string deviceId = device.GetPropertyValue("DeviceID").ToString();

            if (deviceId.Contains("USB"))
            {
                string[] splitArray = deviceId.Split(new string[] { "\\", "#" }, StringSplitOptions.RemoveEmptyEntries);
                string vid = splitArray[1];
                string pid = splitArray[2];

                var port = new SerialPortInfo
                {
                    PortName = device.GetPropertyValue("DeviceID").ToString(),
                    Description = desc,
                    VID = vid,
                    PID = pid
                };

                portList.Add(port);
            }
        }

        return portList;
    }
}
