using System.IO.Ports;
using System.Text.RegularExpressions;

public class SerialPortInfo
{
    public string PortName { get; set; }
    public string Description { get; set; }
    public string VID { get; set; }
    public string PID { get; set; }
}

public static class SerialPortHelper
{
    public static List<SerialPortInfo> GetSerialPortList()
    {
        var portList = new List<SerialPortInfo>();

        var portNames = SerialPort.GetPortNames();

        foreach (var portName in portNames)
        {
            var port = new SerialPortInfo
            {
                PortName = portName,
                Description = "",
                VID = "",
                PID = ""
            };

            // Use regex to extract VID and PID from port name
            var match = Regex.Match(portName, @"VID_([0-9a-fA-F]+)&PID_([0-9a-fA-F]+)");
            if (match.Success)
            {
                port.VID = match.Groups[1].Value;
                port.PID = match.Groups[2].Value;
            }

            // Use SerialPort class to get description of port
            using (var serialPort = new SerialPort(portName))
            {
                try
                {
                    serialPort.Open();
                    port.Description = serialPort.ReadExisting();
                    serialPort.Close();
                }
                catch (Exception ex)
                {
                    // Could not get description of port
                }
            }

            portList.Add(port);
        }

        return portList;
    }
}
