public static class SerialPortHelper
{
    private const uint DIGCF_PRESENT = 0x00000002;
    private const uint DIGCF_DEVICEINTERFACE = 0x00000010;
    private const uint SPDRP_HARDWAREID = 0x00000001;
    private const uint SPDRP_FRIENDLYNAME = 0x0000000C;
    private const uint SPDRP_DEVICEDESC = 0x00000000;
    private const uint SPDRP_CLASS = 0x00000007;
    private const uint SPDRP_CLASSGUID = 0x00000008;
    private const uint MAX_DEV_LEN = 1000;

    private static Guid GuidDevInterfaceSerial = new Guid("4D36E978-E325-11CE-BFC1-08002BE10318");

    private struct SP_DEVINFO_DATA
    {
        public uint cbSize;
        public Guid ClassGuid;
        public uint DevInst;
        public IntPtr Reserved;
    }

    private struct SP_DEVICE_INTERFACE_DETAIL_DATA
    {
        public uint cbSize;
        public string DevicePath;
    }

    [DllImport("setupapi.dll", CharSet = CharSet.Auto)]
    private extern static IntPtr SetupDiGetClassDevs(
        ref Guid ClassGuid,
        [MarshalAs(UnmanagedType.LPTStr)] string Enumerator,
        IntPtr hwndParent,
        uint Flags
    );

    [DllImport("setupapi.dll", CharSet = CharSet.Auto)]
    private extern static bool SetupDiEnumDeviceInfo(
        IntPtr DeviceInfoSet,
        uint MemberIndex,
        ref SP_DEVINFO_DATA DeviceInfoData
    );

    [DllImport("setupapi.dll", CharSet = CharSet.Auto)]
    private extern static bool SetupDiGetDeviceRegistryProperty(
        IntPtr DeviceInfoSet,
        ref SP_DEVINFO_DATA DeviceInfoData,
        uint Property,
        out uint PropertyRegDataType,
        IntPtr PropertyBuffer,
        uint PropertyBufferSize,
        out uint RequiredSize
    );

    [DllImport("setupapi.dll", CharSet = CharSet.Auto)]
    private extern static bool SetupDiEnumDeviceInterfaces(
        IntPtr DeviceInfoSet,
        IntPtr DeviceInfoData,
        ref Guid InterfaceClassGuid,
        uint MemberIndex,
        ref SP_DEVICE_INTERFACE_DATA DeviceInterfaceData
    );

    [DllImport("setupapi.dll", CharSet = CharSet.Auto, SetLastError = true)]
    private static extern bool SetupDiGetDeviceInterfaceDetail(
        IntPtr DeviceInfoSet,
        ref SP_DEVICE_INTERFACE_DATA DeviceInterfaceData,
        IntPtr DeviceInterfaceDetailData,
        uint DeviceInterfaceDetailDataSize,
        out uint RequiredSize,
        IntPtr DeviceInfoData
    );

    [DllImport("setupapi.dll", CharSet = CharSet.Auto)]
    private extern static bool SetupDiDestroyDeviceInfoList(
        IntPtr DeviceInfoSet
    );

    private static string GetDeviceProperty(IntPtr deviceInfoSet, SP_DEVINFO_DATA deviceInfoData, uint property)
    {
        uint propertyRegDataType;
        IntPtr propertyBuffer = Marshal.AllocHGlobal((int)MAX_DEV_LEN);

        try
        {
            uint requiredSize;
            if (SetupDiGetDeviceRegistryProperty(deviceInfoSet, ref deviceInfoData, property, out propertyRegDataType, propertyBuffer, MAX_DEV_LEN, out requiredSize))
            {
                return Marshal.PtrToStringAuto(propertyBuffer);
            }
        }
        finally
        {
            Marshal.FreeHGlobal(propertyBuffer);
        }

        return null;
    }

    private static List<SerialPortInfo> ListSerialPorts(Guid guid)
    {
        var portList = new List<SerialPortInfo>();

        IntPtr deviceInfoSet = SetupDiGetClassDevs(ref guid, null, IntPtr.Zero, DIGCF_PRESENT | DIGCF_DEVICEINTERFACE);
        if (deviceInfoSet.ToInt64() != -1)
        {
            try
            {
                uint memberIndex = 0;
                bool moreItems = true;
                while (moreItems)
                {
                    var deviceInfoData = new SP_DEVINFO_DATA { cbSize = (uint)Marshal.SizeOf(typeof(SP_DEVINFO_DATA)) };
                    if (SetupDiEnumDeviceInfo(deviceInfoSet, memberIndex, ref deviceInfoData))
                    {
                        string deviceDesc = GetDeviceProperty(deviceInfoSet, deviceInfoData, SPDRP_DEVICEDESC);
                        string friendlyName = GetDeviceProperty(deviceInfoSet, deviceInfoData, SPDRP_FRIENDLYNAME);
                        string hardwareId = GetDeviceProperty(deviceInfoSet, deviceInfoData, SPDRP_HARDWAREID);
                        string className = GetDeviceProperty(deviceInfoSet, deviceInfoData, SPDRP_CLASS);
                        string classGuid = GetDeviceProperty(deviceInfoSet, deviceInfoData, SPDRP_CLASSGUID);

                        if (className == "Ports" || className == "COM")
                        {
                            string portName = null;

                            var deviceInterfaceData = new SP_DEVICE_INTERFACE_DATA { cbSize = (uint)Marshal.SizeOf(typeof(SP_DEVICE_INTERFACE_DATA)) };
                            if (SetupDiEnumDeviceInterfaces(deviceInfoSet, IntPtr.Zero, ref guid, memberIndex, ref deviceInterfaceData))
                            {
                                uint requiredSize;
                                IntPtr detailDataBuffer = Marshal.AllocHGlobal(MAX_DEV_LEN);
                                try
                                {
                                    if (SetupDiGetDeviceInterfaceDetail(deviceInfoSet, ref deviceInterfaceData, detailDataBuffer, MAX_DEV_LEN, out requiredSize, IntPtr.Zero))
                                    {
                                        var detailData = (SP_DEVICE_INTERFACE_DETAIL_DATA)Marshal.PtrToStructure(detailDataBuffer, typeof(SP_DEVICE_INTERFACE_DETAIL_DATA));
                                        portName = detailData.DevicePath;
                                    }
                                }
                                finally
                                {
                                    Marshal.FreeHGlobal(detailDataBuffer);
                                }
                            }

                            if (portName != null)
                            {
                                var port = new SerialPortInfo
                                {
                                    DeviceID = hardwareId,
                                    Description = friendlyName ?? deviceDesc,
                                    Name = portName,
                                    PNPDeviceID = "\\\\?\\" + hardwareId,
                                    Caption = friendlyName ?? deviceDesc
                                };

                                portList.Add(port);
                            }
                        }
                    }

                    memberIndex++;
                    if (Marshal.GetLastWin32Error() == ERROR_NO_MORE_ITEMS)
                    {
                        moreItems = false;
                    }
                }
            }
            finally
            {
                SetupDiDestroyDeviceInfoList(deviceInfoSet);
            }
        }

        return portList;
    }

    public static List<SerialPortInfo> GetSerialPortList()
    {
        var portList = new List<SerialPortInfo>();

        portList.AddRange(ListSerialPorts(GuidDevInterfaceSerial));

        return portList;
    }

    private const int ERROR_NO_MORE_ITEMS = 259;

    [StructLayout(LayoutKind.Sequential)]
    private struct SP_DEVICE_INTERFACE_DATA
    {
        public uint cbSize;
        public Guid InterfaceClassGuid;
        public uint Flags;
        public IntPtr Reserved;
    }
}
